\newmethod{ \textbf{Charge consumption during BLE connection intervals}:} \\
Referring to Fig. \ref{fig:ble_conn}, the average current consumption during a BLE connection interval is obtained as:
\begin{equation}
\begin{aligned}[t]
I_{\text{connInt}} = 
\frac{( I_{\text{connEvent}} \times T_{\text{connEvent}}) + 
(I_{\text{connIdle}} \times T_{\text{connIdle}} )}{T_{\text{connEvent}} + T_{\text{connIdle}} }  
\end{aligned}
\label{Ibleint}
\end{equation}
where $T_{\text{connEvent}}$ is the average duration of a single BLE connection event, $I_{\text{connEvent}}$ is the average current consumed during a BLE connection event, $T_{\text{connIdle}}$ is the idle period between two successive connection events, and $I_{\text{connIdle}}$ is the average current consumed during the idle period between two successive BLE connection events. 
Using Eq. (\ref{Ibleint}) and Table \ref{tab:param}, $I_{\text{connInt}}=5.52 \ \text{mA}$.
Table \ref{tab:ble_conn_txpower} 
also shows the average current consumption of the BLE connection interval for different TX power levels ($P_\text{tx}$). 
There is a noticeable decrease in the average current during BLE connection events with decreasing BLE TX power level from +8 dBm to 0 dBm (from 8.58 mA to 7.31 mA for normal unoptimized BLE connected-only state and from 4.69 mA to 3.52 mA for low-power software optimized BLE connected-only state). This indicates that reducing the TX power significantly lowers the current consumption during the active BLE connection events. The idle current, $I_{\text{connIdle}}$, between connection events remains fairly stable showing that idle periods between connection events are not affected by changes in TX power levels, as expected. The overall average current during a BLE connection interval, $I_{\text{connInt}}$  decreases slightly with reduced TX power levels, but the change is more modest compared to the BLE connection event current, $I_{\text{connEvent}}$.
The total charge consumption (in mAh) for BLE connection intervals is given by:
\begin{equation}
\begin{aligned}[t]
& Q_{\text{connInt}} =  & I_{\text{connInt}}  \times T_{\text{connInt}} \times N_{\text{connInt}},
\end{aligned}
\label{q_bleconn_int}
\end{equation}
where $T_{\text{connInt}}$ is the duration of a BLE connection interval (in hours), and $N_{\text{connInt}}$ 
is the number of instances of the BLE connection intervals over a given period of time during the initial operations, and it can be computed as:
\begin{equation}
N_{\text{connInt}} = \frac{T_{\text{bleConn}}}{T_{\text{connInt}}},  
\label{num_ble_conn}
\end{equation}  
where $T_{\text{bleConn}}$ is the time spent in BLE-connected only mode during the initial operations. 


\newmethod{ \textbf{Charge consumption during startup}:} \\
As mentioned previously, the startup operation occurs only once when a firmware test mode is first activated (as illustrated in Fig. \ref{fig:startup}). The charge consumption (in mAh) during the startup activity is calculated as follows:
\begin{equation}
Q_{\text{start}} = I_{\text{start}}  \times T_{\text{start}}  ,
\label{q_startup}
\end{equation}  
where $T_{\text{start}}$ is the 
startup duration in hours, and $I_{\text{start}}$ is the average current consumed during the startup period (in mA).


\newmethod{ \textbf{Charge consumption during idle period after startup}: }\\
The charge consumption (in mAh) for the idle period that follows the startup operation can be computed as follows:
\begin{equation}
Q_{\text{idleStart}} = I_{\text{idleStart}}  \times T_{\text{idleStart}} ,
\label{q_idlestartup}
\end{equation}  
where $T_{\text{idleStart}}$ is the average duration of the idle period after startup (in hours, h), and $I_{\text{idleStart}}$ is the average current consumed during the idle period following startup (in mA).
Since the node is connected via BLE to a central device over the whole operating time, $I_{\text{idleStart}}$ corresponds to the average current consumption during a BLE connection interval, $I_{\text{connInt}}$, as computed in Eq. (\ref{Ibleint}).


\newmethod{ \textbf{Charge consumption during sensing operations}:} \\
The total charge consumed during the sensing operations (in mAh) can be formulated as:
\begin{equation}
Q_{\text{sens}} = I_{\text{sens}}  \times T_{\text{sens}} \times  N_{\text{sens}},
\label{q_sen}
\end{equation}  
where $T_{\text{sens}}$ is the average duration of a single sensing operation (in hours), $I_{\text{sens}}$ is the average current consumed during a sensing operation (in mA), and $N_{\text{sens}}$ is the number of instances of the sensing operations over the node’s operating duration. Table \ref{tab:normal_firmware01} shows the average current consumption during sensing under different BLE connection intervals ($T_\text{connInt}$) and TX power levels ($P_\text{tx}$).

\newmethod{ \textbf{Charge consumption during idle periods after sensing operations}:} \\
The total charge consumed during the idle periods after sensing (in mAh) can be expressed as:
\begin{equation}
\begin{aligned}[t]
& Q_{\text{idleSens}} =    & I_{\text{idleSens}}  \times T_{\text{idleSens}} \times  N_{\text{idleSens}},
\end{aligned}
\label{q_idlesensing}
\end{equation}  
where $T_{\text{idleSens}}$ is the average duration of the idle period after sensing (in hours), $I_{\text{idleSens}}$ is the average current consumed during the idle period following sensing (in mA),  and $N_{\text{idleSens}}$ is the number of instances of the idle period following the sensing operation over the node’s operating duration. Since the node is connected via BLE to a central device over the whole operating time, $I_{\text{idleSens}} \approx I_{\text{connInt}}$ (see Eq. (\ref{Ibleint}).


\newmethod{ \textbf{Charge consumption during E-ink display}: }\\
The total charge consumed during the E-ink displaying operations (in mAh) can be expressed as:
\begin{equation}
Q_{\text{eink}} = I_{\text{eink}}  \times T_{\text{eink}} \times  N_{\text{eink}},
\label{q_eink}
\end{equation}  
where $T_{\text{eink}}$ is the average duration of a single E-ink displaying operation (in hours), $I_{\text{eink}}$ is the average current consumed during the E-ink displaying operation (in mA), and $N_{\text{eink}}$ is the number of instances of the E-ink displaying operations over the node’s operating duration.
Table \ref{tab:normal_firmware01} shows the average current consumption during E-ink display under different BLE connection intervals ($T_\text{connInt}$) and TX power levels ($P_\text{tx}$).

\newmethod{ \textbf{Charge consumption during idle periods after E-ink display operations}:} \\
The total charge consumed during the idle periods after E-ink display operations (in mAh) can be written as:
\begin{equation}
\begin{aligned}[t]
& Q_{\text{idleEink}} =   & I_{\text{idleEink}}  \times T_{\text{idleEink}} \times  N_{\text{idleEink}},
\end{aligned}
\label{q_idle_eink}
\end{equation}  
where $T_{\text{idleEink}}$ is the average duration of the idle period after the E-ink display operation (in hours), $I_{\text{idleEink}}$ is the average current consumed during the idle period following the E-ink display operation (in mA), and $N_{\text{idleEink}}$ is the number of instances of the idle period following the E-ink display operations over the node’s operating duration.
Recall that the during the idle period after E-ink display, the node remains connected to a central device via BLE. 
Referring to Table \ref{tab:normal_firmware01} where we compared the impact of different TX power levels and BLE connection intervals on the node's average current consumption during sensing and E-ink displaying, we noticed an increase in the average idle current after E-ink displaying between 0.5\% and 0.9\% when compared to the average current during BLE connected-only mode  for the same BLE connection interval of 45 ms (see Table \ref{tab:ble_conn_txpower} for ``normal (unoptimized)" BLE connected-only state). Thus, the idle current after E-ink displaying, is considered to be on average, around 0.7\% higher than the BLE connected-only mode, i.e.
\begin{equation}
I_{\text{idleEink}} \approx  1.007 \times I_{\text{connInt}} = 5.56 \ \text{mA}. 
\end{equation}  
From Table \ref{tab:normal_firmware01}, we also note that with smaller connection intervals (e.g. 11.25 ms), the impact of increasing the BLE TX power level is greater on the overall average current consumption. However, with higher connection intervals such as 250 ms and 1000 ms, increasing the BLE TX power level has minimal impact on the overall current consumption.


\newmethod{ \textbf{Charge consumption during NBVLC TX/RX}:} \\
The total charge consumed during the NBVLC transmission and reception operations (in mAh) can be expressed as:
\begin{equation}
Q_{\text{nbvlc}} = I_{\text{nbvlc}}  \times T_{\text{nbvlc}} \times  N_{\text{nbvlc}},
\label{q_nbvlc}
\end{equation} 
where $T_{\text{nbvlc}}$  is the average duration of a single NBVLC transmission and reception operation (in hours), $I_{\text{nbvlc}}$ is the average current consumed during the NBVLC transmission and reception operation (in mA), and $N_{\text{nbvlc}}$ is the number of instances of the NBVLC TX/RX operations over the node’s operating duration. 	

\newmethod{ \textbf{Charge consumption during idle periods after NBVLC TX/RX operations}: }\\
The total charge consumed during the idle periods after the NBVLC TX/RX operations (in mAh) can be expressed as:
\begin{equation}
\begin{aligned}[t]
& Q_{\text{idleNbvlc}} = & I_{\text{idleNbvlc}}  \times T_{\text{idleNbvlc}} \times  N_{\text{idleNbvlc}},
\end{aligned}
\label{q_idle_nbvlc}
\end{equation} 
where $T_{\text{idleNbvlc}}$ is the average duration of the idle period after the NBVLC TX/RX operation (in hours), $I_{\text{idleNbvlc}}$ is the average current consumed during the idle period following a NBVLC TX/RX operation (in mA), and $N_{\text{idleNbvlc}}$ is the number of instances of the idle periods following the NBVLC TX/RX operation over the node’s operating duration.
We noted that the average idle current after NBVLC TX/RX followed the same trend as the average idle current after E-ink, when compared to the average current during BLE connected-only mode only. Thus, 
\begin{equation}
I_{\text{idleNbvlc}} \approx  1.007 \times I_{\text{connInt}} = 5.56 \ \text{mA},  
\end{equation}  
%\end{enumerate}
\end{methods}

\setlength{\belowdisplayskip}{2pt} \setlength{\belowdisplayshortskip}{2pt}
\setlength{\abovedisplayskip}{0pt} \setlength{\abovedisplayshortskip}{0pt}


The operations that are part of the duty cycle of the node and will be repeated over time consist of sensing, idle after sensing, E-ink displaying, idle after E-ink displaying, NBVLC TX/RX and idle after NBVLC TX/RX. Thus, the duration of a full cycle can be expressed as:
\begin{equation}
\begin{aligned}[t]
T_{\text{oneFullCycle}} = & \, T_{\text{sens}} + T_{\text{idleSens}} + T_{\text{eink}} + \\
& \, T_{\text{idleEink}} + T_{\text{nbvlc}} + T_{\text{idleNbvlc}}.
\end{aligned}
\label{duration_full_cycle}
\end{equation}
And the duration of the initial operations including BLE fast and slow advertising, BLE connected-only mode (idle), startup and idle after startup can be expressed as:
\begin{equation} 
\begin{aligned}[t]
T_{\text{initOper}} =  T_{\text{fastAdv}} + T_{\text{slowAdv}} + T_{\text{bleConn}} +  T_{\text{start}} + T_{\text{idleStart}} .
\end{aligned}
\label{duration_initial_oper}
\end{equation}
The number of cycles consisting of sensing, E-ink displaying and NBVLC operations (including the idle periods that follow these operations) over the node's operating time is obtained as follows:
\begin{equation}
\begin{aligned}[t]
N_{\text{cycles}} = \frac{(T - T_{\text{initOper}})}{T_{\text{oneFullCycle}}},
\end{aligned}
\label{num_sens_eink_nbvlc}
\end{equation}
where $T$ is the total operating time of the node.
The number of full cycles 
over the node's operating time can be expressed as:
\begin{equation}
\begin{aligned}[t]
N_{\text{fullCycles}} = \left\lfloor N_{\text{cycles}} \right\rfloor.
\end{aligned}
\label{eq:numcompletecycles}
\end{equation}
The total duration of the full cycles 
is then computed as:
\begin{equation}
\begin{aligned}[t]
T_{\text{fullCycles}} = &N_{\text{fullCycles}} \times  T_{\text{oneFullCycle}}.
\end{aligned}
\label{eq:duration_complete_cycles}
\end{equation}
In the event that there are both $N_{\text{fullCycles}}$
full cycles and also a partial cycle, we need to determine which operations will fit entirely within the partial cycle, which operations will only fit partially, and which operations will not fit at all. These need to be accounted for in the total charge consumption. 
The partial cycle duration 
can be computed as 
\begin{equation}
\begin{aligned}[t]
T_{\text{partCycle}} = (T - T_{\text{initOper}}) -  T_{\text{fullCycles}}.
\end{aligned}
\label{duration_partial_cycle}
\end{equation}
Next, we need to understand how the partial duration, $T_{\text{partCycle}}$, is distributed among the operations. Typically, operations occur sequentially within each cycle, so we proceed in order and determine how much of each operation fits into 
$T_{\text{partCycle}}$.
First, let’s write the total charge consumption for the partial cycle, $Q_{\text{partial}}$ (in simpler notations) as in Eq. (\ref{eq:partial}),  
where 
\( T_{\text{s}} \) and \( I_{\text{s}} \) denote the sensing duration ($T_{\text{sens}}$) and current ($I_{\text{sens}}$), respectively, 
\( T_{\text{i1}} \) and \( I_{\text{i1}} \) represent the idle period duration ($T_{\text{idleSens}}$) and current ($I_{\text{idleSens}}$) after sensing respectively (with \( I_{\text{i1}} \approx I_{\text{connInt}} \)), 
\( T_{\text{e}} \) and \( I_{\text{e}} \) correspond to the E-ink display duration ($T_{\text{eink}}$) and current ($I_{\text{eink}}$), respectively,
\( T_{\text{i2}} \) and \( I_{\text{i2}} \) refer to the idle period duration ($T_{\text{idleEink}}$) and current ($I_{\text{idleEink}}$) after the E-ink display respectively (with \( I_{\text{i2}} \approx 1.007 \times I_{\text{connInt}} \)), 
\( T_{\text{n}} \) and \( I_{\text{n}} \) are the NBVLC TX/RX duration ($T_{\text{nbvlc}}$) and current ($I_{\text{nbvlc}}$), respectively, and 
\( I_{\text{i3}} \) is the idle current ($I_{\text{idleNbvlc}}$) after NBVLC TX/RX (with \( I_{\text{i3}} \approx 1.007 \times I_{\text{connInt}} \)).


\vspace{-10mm}
\begin{strip}
\small
\begin{equation}
Q_{\text{partial}} = 
\left\{
\begin{aligned}
  & I_{\text{s}} \cdot T_{\text{partCycle}}, \quad  \text{if } T_{\text{partCycle}} \leq T_{\text{s}} \\ 
  & I_{\text{s}} \cdot T_{\text{s}} + I_{\text{i1}} \cdot (T_{\text{partCycle}} - T_{\text{s}}), \quad  \text{if } T_{\text{partCycle}} > T_{\text{s}} \text{ and } T_{\text{partCycle}} \leq T_{\text{s}} + T_{\text{i1}} \\ 
  & I_{\text{s}} \cdot T_{\text{s}} + I_{\text{i1}} \cdot T_{\text{i1}} + I_{\text{e}} \cdot (T_{\text{partCycle}} - T_{\text{s}} - T_{\text{i1}}), \quad  \text{if } T_{\text{partCycle}} > T_{\text{s}} + T_{\text{i1}} \text{ and } T_{\text{partCycle}} \leq T_{\text{s}} + T_{\text{i1}} + T_{\text{e}} \\ 
  & I_{\text{s}} \cdot T_{\text{s}} + I_{\text{i1}} \cdot T_{\text{i1}} + I_{\text{e}} \cdot T_{\text{e}} + I_{\text{i2}} \cdot (T_{\text{partCycle}} - T_{\text{s}} - T_{\text{i1}} - T_{\text{e}}), 
  \quad  \text{if } T_{\text{partCycle}} > T_{\text{s}} + T_{\text{i1}} + T_{\text{e}} \text{ and } T_{\text{partCycle}} \leq T_{\text{s}} + T_{\text{i1}} + T_{\text{e}} + T_{\text{i2}} \\ 
  & I_{\text{s}} \cdot T_{\text{s}} + I_{\text{i1}} \cdot T_{\text{i1}} + I_{\text{e}} \cdot T_{\text{e}} + I_{\text{i2}} \cdot T_{\text{i2}} + I_{\text{n}} \cdot (T_{\text{partCycle}} - T_{\text{s}} - T_{\text{i1}} - T_{\text{e}} - T_{\text{i2}}), 
  \quad  \text{if } T_{\text{partCycle}} > T_{\text{s}} + T_{\text{i1}} + T_{\text{e}} + T_{\text{i2}} \\ & \text{ and } T_{\text{partCycle}} \leq T_{\text{s}} + T_{\text{i1}} + T_{\text{e}} + T_{\text{i2}} + T_{\text{n}} \\ 
  & I_{\text{s}} \cdot T_{\text{s}} + I_{\text{i1}} \cdot T_{\text{i1}} + I_{\text{e}} \cdot T_{\text{e}} + I_{\text{i2}} \cdot T_{\text{i2}} + I_{\text{n}} \cdot T_{\text{n}} + I_{\text{i3}} \cdot (T_{\text{partCycle}} - T_{\text{s}} - T_{\text{i1}} - T_{\text{e}} - T_{\text{i2}} - T_{\text{n}}),  
  \\ & \text{if } T_{\text{partCycle}} > T_{\text{s}} + T_{\text{i1}} + T_{\text{e}} + T_{\text{i2}} + T_{\text{n}} 
\end{aligned}
\right.
\label{eq:partial}
\end{equation}
\vspace{-10mm}
\end{strip}

\noindent \textbf{Explanation of Eq. \ref{eq:partial}:}
\begin{methods}
%\begin{enumerate}[]
    \item \textbf{Sensing:} If the remaining time $T_{\text{partCycle}}\leq T_{\text{s}}$, the sensing operation is only partially completed, and the charge consumption is $I_{\text{s}} \cdot T_{\text{partCycle}}$.

    \item \textbf{Idle after sensing:} If the remaining time $T_{\text{partCycle}} > T_{\text{s}}$ but less than or equal to $T_{\text{s}} + T_{\text{i1}}$, the sensing operation is fully completed, and part or all of the idle period after sensing is completed. The charge consumption accounts for the full sensing duration plus the idle time that fits.

    \item \textbf{E-ink:} 
    %This logic continues for each subsequent operation:
    %\begin{itemize}
        %\item 
        If $T_{\text{partCycle}}$ exceeds the combined time up to the E-Ink operation but is less than or equal to $T_{\text{s}} + T_{\text{i1}} + T_{\text{e}}$, it means that both the sensing and idle period after sensing fit fully, and part or all of the E-ink display operation fits.
    %\end{itemize}
    \item \textbf{Subsequent operations:} The pattern repeats for each operation, adding full contributions for the operations that fit entirely and partial contributions for the first operation that does not fit within the remaining time.
%\end{enumerate}
\end{methods}


The overall total charge consumption (in mAh) of the Si-based node during normal (unoptimized) operation can be expressed as:
\setlength{\belowdisplayskip}{1pt} \setlength{\belowdisplayshortskip}{1pt}
\setlength{\abovedisplayskip}{1pt} \setlength{\abovedisplayshortskip}{1pt}
\begin{equation}
\begin{aligned}[t]
 Q_{\text{total}} = & \, Q_{\text{fastAdvInt}} + Q_{\text{slowAdvInt}} + Q_{\text{startup}} + Q_{\text{sensing}} + \\ 
& \, Q_{\text{eink}} + Q_{\text{nbvlc}} + Q_{\text{idle}} + Q_{\text{partial}}
\end{aligned}
\label{q_all}
\end{equation}
where 
$Q_{\text{idle}}$ is the total charge consumption during the idle states in the initial operations (i.e BLE-connected only mode and idle after startup) and the idle periods in full operation cycles (i.e. idle states after sensing, E-ink displaying and NBVLC TX/RX), which can be expressed as:
\begin{equation}
\begin{aligned}[t]
   Q_{\text{idle}} &= Q_{\text{connInt}} + Q_{\text{idleStart}} + Q_{\text{idleSens}} +  Q_{\text{idleEink}} + Q_{\text{idleNbvlc}} \\ 
  & = I_{\text{connInt}} [ \left(T_{\text{connInt}} \times N_{\text{connInt}}\right) +  T_{\text{idleStart}} +  \\ & \quad  \left(T_{\text{idleSens}} \times N_{\text{fullCycles}}\right) +    \left(1.007 \times T_{\text{idleEink}} \times N_{\text{fullCycles}}\right) + \\ & \quad  \left(1.007 \times T_{\text{idleNbvlc}} \times N_{\text{fullCycles}}\right) ].
\end{aligned}
\label{q_idle}
\end{equation} 
Thus, we can rewrite Eq. \ref{q_all} as follows:
\begin{equation}
\begin{aligned}[t]
    Q_{\text{total}} 
    &= \left(I_{\text{fastAdvInt}} \times T_{\text{fastAdvInt}} \times N_{\text{fastAdv}}\right) + \\ 
    & \quad \left(I_{\text{slowAdvInt}} \times T_{\text{slowAdvInt}} \times N_{\text{slowAdv}}\right) +  
    \left(I_{\text{start}} \times T_{\text{start}}\right) + \\ 
    & \quad N_{\text{fullCycles}}  [ \left(I_{\text{sens}} \times T_{\text{sens}}\right) +  \left(I_{\text{eink}} \times T_{\text{eink}}\right) + \\ & \quad \left(I_{\text{nbvlc}} \times T_{\text{nbvlc}}\right)  ]   + 
     Q_{\text{idle}}
    +  Q_{\text{partial}}.
\end{aligned}
\label{eq:q_overall}
\end{equation}
The total charge consumption in Coulombs is given by:
\begin{equation}
Q_{\text{total}} \times 3.6,
\end{equation}
and the 
total energy consumption (in mWh) of the node 
over an operating duration of $T$ is given by:
\begin{equation}
P_{\text{total}} = Q_{\text{total}} \times V_{\text{operating}},
\end{equation}
where $V_{\text{operating}}$ is the operating voltage of the node.
Finally, the total energy consumption in Joules is given by:
\begin{equation}
P_{\text{total}} \times 3.6.
\end{equation}
The overall average current consumption (in mA) of the node 
over an operating duration of  $T$ is given by:
\begin{equation}
I_{\text{overall}} = \frac{
%\begin{aligned}
   I_{\text{1}} \times ( %\begin{aligned}
   T_{\text{initOper}} +  
   T_{\text{fullCycles}} 
 % \end{aligned}
 ) +  
   I_{2} \times T_{\text{partCycle}}
%\end{aligned}
}
{\begin{aligned}
  & T
\end{aligned}}
\label{eq:I_overall}
\end{equation}
where $T= T_{\text{initOper}} + T_{\text{fullCycles}} + T_{\text{partCycle}} $, and
\begin{equation*}
I_{1} = \frac{\left( \begin{aligned}
  & Q_{\text{fastAdvInt}} + Q_{\text{slowAdvInt}} + Q_{\text{start}} + \\ 
  & Q_{\text{sens}} + Q_{\text{eink}} + Q_{\text{nbvlc}} + Q_{\text{idle}} 
\end{aligned} \right)}{
( 
  T_{\text{initOper}} + 
  T_{\text{fullCycles}} 
)},
I_{2} = \frac{Q_{\text{partial}}}{T_{\text{partCycle}}}.
\end{equation*}


