\title[A rigid origami elliptic-hyperbolic vertex duality]{A rigid origami elliptic-hyperbolic vertex duality}



\author{Thomas C. Hull}

\address{Mathematics Department, Franklin \& Marshall College, Lancaster, PA, 17604-3003  USA}

\email{thomas.hull@fandm.edu}






%\keywords{origami, kinematics, metamaterials}



