\begin{example}\label{example:notGB}
    From the proof of Proposition~\ref{prop:rowcolumn}, one may reasonably ask whether the conditions of the proposition can be formulated as: for each $G_i \in \pset{G}_i$ and $G_j \in \pset{G}_j$ with $i\neq j$, there exists a one-sided ladder in $X$ which covers these two minors. But in general this reformulated condition cannot imply that $\bigcup_{i=1}^k \pset{G}_i$ is a \grobner basis of $I(\p{B}, \p{r})$ w.r.t. $<$. Take the Schubert determinantal ideal $I_w$ with $w=2143$ for example, its Futon generators consist of a 1-minor $x_{11}$ in $X_{11}$ and a 3-minor $(\{1,2,3\},\{1,2,3\})$ in $X_{33}$. These two minors is covered by $X_{33}$ which can be identified as a one-sided ladder, but they do not form a \grobner basis of $I_w$ w.r.t. any diagonal term order since $w$ is not vexillary.

\end{example}

\begin{corollary}\label{cor:uniqueuppercorner}
    If the blocks $B_1,\ldots,B_k$ of $I(\p{B}, \p{r})$ are one-sided ladders which share the same unique upper corner, and for any lower corners $x_{a_i b_i}$ of $B_i$ and $x_{\tilde{a}_j \tilde{b}_j}$ of $B_j$ with $i \neq j$, neither $a_i >\tilde{a}_j, b_i > \tilde{b}_j$ nor $a_i < \tilde{a}_j, b_i < \tilde{b}_j$ holds, then $\bigcup_{i=1}^k \pset{G}_i$ is a \grobner basis of $I(\p{B}, \p{r})$ w.r.t. $<$. 
\end{corollary}

\begin{proof}
    Let $x_{cd}$ be the unique upper corner. For each $G_i \in \pset{G}_i$ and $G_j \in \pset{G}_j$ with $i\neq j$, let $x_{a_ib_i}$ and $x_{\tilde{a}_j \tilde{b}_j}$ be any lower corners of $B_i$ and $B_j$ respectively such that $R(G_i) \subseteq [c, a_i], C(G_i) \subseteq [d, b_i]$ and $R(G_j) \subseteq [c, \tilde{a}_i], C(G_j) \subseteq [d, \tilde{b}_i]$ (clearly such lower corners exist). This implies condition~(1) of Proposition~\ref{prop:rowcolumn}, and condition~(2) follows from the assumption of this corollary. 
\end{proof}


