\subsection{Blockwise determinantal ideals}
\label{sec:gb-block}

Let $\p{m}_1$ and $\p{m}_2$ be two distinct minors in $X$. Then we say that $\p{m}_2$ is \emph{contained in} $\p{m}_1$ if $R(\p{m}_2) \subseteq R(\p{m}_1)$ and $C(\p{m}_2) \subseteq C(\p{m}_1)$. It is not hard to have the following criterion for testing reducibility between minors. 


\begin{proposition}\label{prop:reducible}
Let $\p{m}_1$ and $\p{m}_2$ be two distinct minors in $X$. Then $\p{m}_1$ is reducible modulo $\p{m}_2$ if and only if $\p{m}_2$ is contained in $\p{m}_1$. 
\end{proposition}


The following results are all presented w.r.t. the diagonal term order for diagonal blockwise determinantal ideals, but indeed they also hold w.r.t. any anti-diagonal term order for anti-diagonal ones. 

\begin{proposition}\label{prop:min-reduced}
Suppose that the generating set $\pset{G}$ of a diagonal blockwise determinantal ideal $I(\p{B}, \p{r})$ is a \grobner basis. For any $r$-minor $\p{m} \in \pset{G}$, let $\p{B}_{\p{m}} = \{B_i \in \p{B}: r_i = \deg(\p{m})\}$. Then the following statements hold:
  \begin{enumerate}
  \item[(1)] If for each $\p{m} \in \pset{G}$, $l(\lt(\p{m}), \tilde{B}) < \tilde{r}$ for any $\tilde{B} \in \p{B} \setminus \p{B}_{\p{m}}$, where $\tilde{r}$ is the size of minors in $\tilde{B}$, then $\pset{G}$ is a minimal \grobner basis of $I(\p{B}, \p{r})$. 
  \item[(2)] If for each $\p{m} \in \pset{G}$ and for any term $\p{t}$ of $\p{m}$, we have $l(\p{t}, \tilde{B}) < \tilde{r}$ for any $\tilde{B} \in \p{B} \setminus \p{B}_{\p{m}}$, then $\pset{G}$ is the reduced \grobner basis of $I(\p{B}, \p{r})$. 
  \end{enumerate}
\end{proposition}

\begin{proof}

  Let $\p{m}$ be an $r$-minor and $\tilde{\p{m}}$ be an arbitrary $r$-minor in some $B \in \p{B}_{\p{m}}$ distinct from $\p{m}$. Then for each term $\p{t}$ of $\p{m}$, we claim that $\lt(\tilde{\p{m}})$ and $\p{t}$ are distinct. This is because otherwise if $\lt(\tilde{\p{m}}) = \p{t}$, then $s(\p{t})$ is a decreasing sequence of length $r$, and thus by Lemma~\ref{lem:leadingTerm} we have $\p{t} = \lt(\p{m})$. Since different $r$-minors have different leading terms, we have $\lt(\tilde{\p{m}}) \neq \lt(\p{m})$, and thus $\lt(\tilde{\p{m}})$ does not divide any term $\p{t}$ of $\p{m}$.

  For the remaining case when $\tilde{\p{m}}$ is a minor from other $\tilde{B} \in \p{B} \setminus \p{B}_{\p{m}}$, by Theorem~\ref{thm:divisible} we know that in (1) $\lt(\tilde{\p{m}})$ does not divide $\lt(\p{m})$ and that in (2) $\lt(\tilde{\p{m}})$ does not divide any term $\p{t}$ of $\p{m}$ either. To summarize, $\pset{G}$ is a minimal \grobner basis of $I(\p{B}, \p{r})$ in (1) and is the reduced one in (2).
\end{proof}

Let $\p{m}$ be a minor generator from $B \in \p{B}$ and $\tilde{B} \neq B$. We use $\p{m} \cap \tilde{B}$ to denote the intersection of the submatrix corresponding to $\p{m}$ and the block $\tilde{B}$ and $R(\p{m} \cap \tilde{B}) := \{i \in [m]: \exists x_{ij} \in \p{m} \cap \tilde{B}\}$. $C(\p{m} \cap \tilde{B})$ can be similarly defined. Clearly for any term $\p{t}$ of $\p{m}$, we have $l(\p{t}, \tilde{B}) \leq \#R(\p{m} \cap \tilde{B})$ and $l(\p{t}, \tilde{B}) \leq \#C(\p{m} \cap \tilde{B})$. That is, the length of any term of $\p{m}$ in $\tilde{B}$ is bounded by the number of rows (or columns) of the submatrix of $\p{m}$ appearing in $\tilde{B}$. Note that a row (or column) appearing in $\tilde{B}$ does not necessarily means that the corresponding full row (or column) belongs to $\tilde{B}$. With these straightforward inequalities, we have the following sufficient conditions for a \grobner basis of a diagonal blockwise determinantal ideal to be the reduced one.

\begin{corollary}\label{cor:fewerRows}
Suppose that the generating set $\pset{G}$ of a diagonal blockwise determinantal ideal $I(\p{B}, \p{r})$ is a \grobner basis. If for each $\p{m} \in \pset{G}$, $\#R(\p{m} \cap \tilde{B}) < \tilde{r}$ or $\#C(\p{m} \cap \tilde{B}) < \tilde{r}$ for any $\tilde{B} \in \p{B} \setminus \p{B}_{\p{m}}$, where $\p{B}_{\p{m}} = \{B_i \in \p{B}: r_i = \deg(\p{m})\}$, then $\pset{G}$ is the reduced \grobner basis of $I(\p{B}, \p{r})$.
\end{corollary}


Next we consider the special case when a minor $\p{m}$ in $B$ intersects another block $\tilde{B} \neq B$ with consecutive full rows or columns of $\p{m}$. 

\begin{proposition}\label{prop:fullRows}
  Let $\p{m}$ be a minor generator of a diagonal blockwise determinantal ideal $I(\p{B}, \p{r})$ such that $\p{m} \cap \tilde{B}$ consists of consecutive full rows or columns of the submatrix of $\p{m}$ for any $\tilde{B} \in \p{B} \setminus \p{B}_{\p{m}}$, where $\p{B}_{\p{m}} = \{B_i \in \p{B}: r_i = \deg(\p{m})\}$. Then for any $\tilde{\p{m}}$ in $\tilde{B}$, if $\lt(\tilde{\p{m}})\nmid \lt(\p{m})$, then $\p{m}$ is reduced modulo $\tilde{\p{m}}$, namely $\lt(\tilde{\p{m}}) \nmid  \p{t}$ for each term $\p{t}$ of $\p{m}$. 
\end{proposition}

\begin{proof}
  Suppose that $\p{m} \cap \tilde{B}$ consists of $k$ consecutive full rows or columns of the submatrix of $\p{m}$. Then clearly we have $l(\lt(\p{m}), \tilde{B}) = k$ and $l(\p{t}, \tilde{B}) \leq k$ for any term $\p{t}$ of $\p{m}$. Then with Proposition~\ref{prop:min-reduced} the conclusion follows. 
\end{proof}

\begin{corollary}\label{cor:fullRows}
  Suppose that the generating set $\pset{G}$ of a diagonal blockwise determinantal ideal $I(\p{B}, \p{r})$ is a minimal \grobner basis. If for each $\p{m} \in \pset{G}$, $\p{m} \cap \tilde{B}$ consists of consecutive full rows or columns of the submatrix of $\p{m}$ for any $\tilde{B} \in \p{B} \setminus \p{B}_{\p{m}}$, where $\p{B}_{\p{m}} = \{B_i \in \p{B}: r_i = \deg(\p{m})\}$, then $\pset{G}$ is the reduced \grobner basis of $I(\p{B}, \p{r})$.
\end{corollary}


\subsection{Schubert determinantal ideals}
 \label{sec:gb-schubert}

We found the same results on reduced \grobner bases of Schubert determinantal ideals as in this section already presented in \cite[Theorem~1.5]{S23m} when we were finishing this manuscript. We decided to keep this section for the reason of completeness, and the readers should also refer to \cite{S23m} for these results. 

 Note that the defining blocks $X_{pq}$ with $(p,q) \in \ess(w)$ of a Schubert determinantal ideal $I_w$ are both anti-diagonal and diagonal. So we can study the reduced \grobner basis of $I_w$ w.r.t.\! both anti-diagonal and diagonal term orders with the results presented in Section~\ref{sec:gb-block}. 

Let $w \in S_n$ be a permutation. For any two distinct $(p, q), (\tilde{p}, \tilde{q}) \in \ess(w)$, let $r= \rank(w^T_{pq})+1$ and $B = X_{pq}$, and $\tilde{r}$ and $\tilde{B}$ be similarly defined for $(\tilde{p}, \tilde{q})$. To study the reduced \grobner basis of $I_w$, we need to test whether an $r$-minor in $B$ is reducible modulo any $\tilde{r}$-minor in $\tilde{B}$. Clearly we only need to consider the case when $r> \tilde{r}$. There exist two kinds of relative positions between $(p, q)$ and $(\tilde{p}, \tilde{q})$: (1) $\tilde{p} < p$ and $\tilde{q} < q$, and (2) otherwise, namely $\tilde{p} \geq p$ or $\tilde{q} \geq q$.

Case~(2) is easier: in this case for any $r$-minor $\p{m}$ in $B$, $\p{m} \cap \tilde{B}$ is either empty or consists of consecutive full rows or columns of the submatrix of $\p{m}$. Then by Proposition~\ref{prop:fullRows}, we only need to ensure that $\lt(\tilde{\p{m}}) \nmid \lt(\p{m})$ for any $\tilde{\p{m}}$ in $\tilde{B}$, and this is guaranteed by the minimality of elusive minors in Theorem~\ref{thm:minimal}. 

Case~(1) only happens when $w$ is not vexillary, and one can see that this case contains the following two sub-cases: (1.1) $\p{m} \cap \tilde{B}$ is either empty or consists of consecutive rows or columns of the submatrix of $\p{m}$, this case is similar to case (2) above; (1.2) $\p{m} \cap \tilde{B}$ does not contain full rows or columns of the submatrix of $\p{m}$, namely $1 \leq \#R(\p{m} \cap \tilde{B}) < r$ and $1 \leq \#C(\p{m} \cap \tilde{B}) < r$. In this sub-case, for any anti-diagonal term order, one can see that there exists a term $\p{t}$ of $\p{m}$ other than $\lt(\p{m})$ such that $l(\p{t}, \tilde{B}) > l(\lt(\p{m}), \tilde{B})$. Therefore, unlike case~(2) above, $l(\lt(\p{m}), \tilde{B}) < \tilde{r}$ does not imply $l(\p{t}, \tilde{B}) < \tilde{r}$. Take $w = 2143 \in S_4$ for example. Then $\ess(w) = \{(1, 1), (3,3)\}$, and the leading term of the only $3$-minor $\p{m}$ in $X_{33}$ is $x_{13}x_{22}x_{31}$, not divisible by the only $1$-minor $x_{11}$ in $X_{11}$. However, two terms of $\p{m}$, $x_{11}x_{23}x_{32}$ and $x_{11}x_{22}x_{33}$, are divisible by $x_{11}$. Hence, Fulton generators, which are also the elusive minors for this $w$, form a minimal \grobner basis of $I_w$ but is not the reduced one. In fact, in this sub-case reducibility between elusive minors always occurs w.r.t. the anti-diagonal term order. 


\begin{theorem}\label{thm:schubert-vex-reduced}
  Let $w \in S_n$ be a vexillary permutation. Then elusive minors form the reduced \grobner basis of $I_w$ w.r.t. any anti-diagonal or diagonal term order. 
\end{theorem}

\begin{proof}
   If $w$ is vexillary, then for any two distinct $(p, q), (\tilde{p}, \tilde{q}) \in \ess(w)$, we have $\tilde{p} \geq p$ or $\tilde{q} \geq q$. Hence for any minor $\p{m}$ in $B$, $\p{m} \cap \tilde{B}$ is either empty or consists of consecutive rows or columns of the submatrix of $\p{m}$. By Theorem~\ref{thm:minimal}, the set of elusive minors form a minimal \grobner basis of $I_w$, and thus further by Corollary~\ref{cor:fullRows} we know that they are the reduced \grobner basis.
\end{proof}

\begin{theorem}\label{thm:schubert-reduced-vex}
Let $w \in S_n$ be a permutation. If elusive minors form the reduced \grobner basis of $I_w$ w.r.t. an anti-diagonal term order, then $w$ is vexillary. 
\end{theorem}

\begin{proof}
  We prove that if $w$ is not vexillary, then there exists an elusive minor which is reducible modulo another elusive minor. Since $w$ is not vexillary, there exist two distinct $(p, q), (\tilde{p}, \tilde{q}) \in \ess(w)$ with $\tilde{p} < p$ and $\tilde{q} < q$. Consider the submatrix $M$ of $w^{T}$ with the entries at $(\tilde{p}+1, \tilde{q}+1)$ and $(p, q)$ as its diagonal corners. Let $(\overline{p}, \overline{q})$ be one of the northwest most elements in $M$ such that $(\overline{p}, \overline{q})$ belongs to the Rothe diagram $D(w)$ and any other element in $\{(i, j): i \in [\tilde{p}+1,\overline{p}], j \in [\tilde{q}+1, \overline{q}]\}$ does not. With $(p, q) \in \ess(w) \subseteq D(w)$ and $(p, q) \in M$, clearly such an element $(\overline{p}, \overline{q})$ exists. The relative positions of $(p, q)$, $(\tilde{p}, \tilde{q})$, and $(\overline{p}, \overline{q})$ are illustrated in Figure~\ref{fig:schubert-vex}. Denote $\overline{r} = \rank(w^T_{\overline{p}\overline{q}})+1$ and $\tilde{r} = \rank(w^T_{\tilde{p}\tilde{q}})+1$. Let $\p{m} = ([\overline{p}-\overline{r}+1, \overline{p}], [\overline{q}-\overline{r}+1, \overline{q}])$. Then by Proposition~\ref{prop:corner}, $\p{m}$ is an elusive minor of size $\overline{r}$, and next we prove that $\p{m}$ is reducible modulo some elusive minor in $X_{\tilde{p}\tilde{q}}$.


By the assumption, none of $(\overline{p}, \tilde{q}+1), \ldots, (\overline{p}, \overline{q}-1)$ and $(\tilde{p}+1, \overline{q}), \ldots, (\overline{p}-1, \overline{q})$ belongs to $D(w)$. But with $(\overline{p}, \overline{q}) \in D(w)$, we know that any of $(\overline{p}, \tilde{q}+1), \ldots, (\overline{p}, \overline{q}-1)$ can only be removed from $D(w)$ by some $(k, w(k))$ to its north, and similarly any of $(\tilde{p}+1, \overline{q}), \ldots, (\overline{p}-1, \overline{q})$ only by some $(k, w(k))$ to its west. Furthermore, with $(\tilde{p}, \tilde{q}) \in \ess(w)$ we know that neither $(\tilde{p}, \tilde{q}+1)$ nor $(\tilde{p}+1, \tilde{q})$ lies in $D(w)$. Similarly, $(\tilde{p}+1, \tilde{q})$ can only be removed by some $(k, w(k))$ to its west and $(\tilde{p}, \tilde{q}+1)$ only by some $(k, w(k))$ to its north. All the boxes outside $D(w)$ we use are marked in red in Figure~\ref{fig:schubert-vex}.

Recall that there are $\overline{r}$ and $\tilde{r}$ non-zero entries in $w^{T}_{\overline{p}\overline{q}}$ and $w^{T}_{\tilde{p}\tilde{q}}$ respectively. Counting the entries $(k, w(k))$ in $w^{T}_{\overline{p}\overline{q}}$ but not in $w^{T}_{\tilde{p}\tilde{q}}$ to remove $(\overline{p}, \tilde{q}+1), \ldots, (\overline{p}, \overline{q}-1)$ and $(\tilde{p}+1, \tilde{q})$, we have $\overline{r} - \tilde{r} \geq (\overline{q}-\tilde{q}-1)+ 1 = \overline{q} - \tilde{q}$. Similarly we also have $\overline{r} - \tilde{r} \geq \overline{p} - \tilde{p}$. These mean that $\#(R(\p{m}) \cap [\tilde{p}]) = \tilde{p} - (\overline{p}-\overline{r}+1)+1 =  \overline{r} - (\overline{p} - \tilde{p}) \geq \tilde{r}$ and $\#(C(\p{m}) \cap [\tilde{q}]) = \tilde{q} - (\overline{q}-\overline{r}+1)+1 = \overline{r} - (\overline{q} - \tilde{q}) \geq \tilde{r}$. Consider the minor $\tilde{\p{m}} = ([\tilde{p}-\tilde{r}+1, \tilde{p}], [\tilde{q}-\tilde{r}+1, \tilde{q}])$. Then again by Proposition~\ref{prop:corner} we know that $\tilde{\p{m}}$ is an elusive minor of size $\tilde{r}$ in $X_{\tilde{p}\tilde{q}}$. Clearly $R(\tilde{\p{m}}) \subseteq R(\p{m})$ and $C(\tilde{\p{m}}) \subseteq C(\p{m})$, and thus by Proposition~\ref{prop:reducible} we know that $\p{m}$ is reducible modulo $\tilde{\p{m}}$: this ends the proof. 
\end{proof}

