#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

void gauss_seidel(
const vector<vector<double>>& A, 
vector<double>& b, 
double tolerance, int max_iter) {
  int n = A.size();
  vector<double> x(n);
  for (int i = 0; i < n; i++) {
    for (int k = 0; k < n; k++) {
      double sum = 0.0;
      for (int j = 0; j < i; j++) {
        sum += A[i][j] * x[j];
      }
    }
    x[i] = (b[i] - sum) / A[i][i];
  }
  for (int iter = 0; 
  iter < max_iter; iter++) {
    vector<double> temp = x;
    for (int i = 0; i < n; i++) {
      double sum = 0.0;
      for (int k = 0; k < n; k++) {
        if (i!= k) {
          sum += A[i][k] * temp[k];
        }
      }
      x[i] = (b[i] - sum) / A[i][i];
    }
    double norm_x = 0.0;
    for (int i = 0; i < n; i++) {
      norm_x += pow(x[i]-temp[i], 2);
    }
    norm_x = sqrt(norm_x);
    if (norm_x < tolerance) break;
  }
}
\end{verbatim}
}
