def gauss_seidel(A, b, 
tolerance=1e-10, max_iter=1000):
n = len(b)
x = [0.0 for i in range(n)]
for i in range(n):
    x[i] = b[i]
    for j in range(i):
        x[i] -= A[i][j] * x[j]
    x[i] /= A[i][i]
for iter in range(max_iter):
    temp = [0.0 for i in range(n)]
    for i in range(n):
        temp[i] = x[i]
        for j in range(i):
            temp[i] -= A[i][j] * x[j]
        temp[i] /= A[i][i]
    norm_x = sum([pow(x_i - t_i, 2) 
    for x_i, t_i in zip(x, temp)])
    norm_x = pow(norm_x, 0.5)
    if norm_x < tolerance:
        break
    x = temp

return x

# Example usage
A = [[3, 2, 1], [2, 4, 1], [1, 1, 6]]
b = [8, 12, 20]
x = gauss_seidel(A, b)
print(x)
\end{verbatim}
}

