As shown in Fig. \ref{fig_model}, we consider a downlink RSMA-assisted ISAC secure communication system that is composed of an ISAC BS ($S$), $K \ge 1$ LUs $\left( {{U_k}, k = 1, \cdots ,K} \right)$, $M \ge 1$ eavesdroppers $\left( {{E_m}, m = 1, \cdots ,M} \right)$, and $T \ge 1$ point targets $\left( {{T_t}, t = 1, \cdots ,T} \right)$. 
$S$ is equipped with $ N_t$ transmit antennas to transmit communication and sensing signals and $N_r$ receive antennas to receive echo signals from $T_t$. 
All the antennas at $S$ follow a uniform linear array layout. 
All the legitimate and illegitimate receivers are equipped with a single antenna.
It is assumed that $S$ utilizes the 1-layer RSMA scheme proposed in \cite{MaoY2022Survey}  and the transmission signal is expressed as
\begin{align}
	{\mathbf{x}} = \underbrace {{{\mathbf{w}}_c}{{{s}}_c}}_{{\rm{common}}\;\,{\rm{signal}}} + \underbrace {\sum\limits_{k = 1}^K {{{\mathbf{w}}_{k}}{{{s}}_{k}}} }_{{\rm{private}}\;{\rm{signal}}} + \underbrace {{{\mathbf{w}}_{v}}{{{s}}_v}}_{{\rm{extra}}\;{\rm{signal}}}, \label{signalx}
\end{align}			
where 
${\mathbf{w}}_c$, ${\mathbf{w}}_{k}$, and ${{\mathbf{w}}_{v}}$ denote the beamforming vector of the common stream, private stream, and the extra signal respectively, 
${{{s}}_c}$ and ${{{s}}_v}$ signify the common stream and the extra signal, respectively, 
${{{s}}_k}$ is the private stream symbol for $U_k$. 
{ It is assumed that ${{{s}}_c}$, ${{{s}}_k}$, and ${{{s}}_v}$ are assumed to be zero mean and unit power.}


\subsection{Communication Model}	

{Like \cite{WeiW2024TWC}, it is assumed that the channel between $S$ and $U_k$ experiences a Rician distribution,} which is expressed as
\begin{align}
	{{\mathbf{h}}_k} = \sqrt {\frac{{{\beta _0}}}{{{{\left( {d_k} \right)}^{{\alpha }}}}}} \left( {\sqrt {\frac{{{\rho _k}}}{{1 + {\rho _k}}}} {\mathbf{\bar h}}_{\rm{LoS}}^k + \sqrt {\frac{1}{{1 + {\rho _k}}}} {\mathbf{\tilde h}}_{\rm{NLoS}}^k} \right), \label{channelhk}
\end{align}
where 
${{\mathbf{h}}_k} \in {C^{{N_t} \times 1}}$, $\beta_0$ denotes the channel gain at reference distance 1m, 
$d_k$ denotes the distance between $S$ and $U_k$, 
$\alpha $ denotes the path loss coefficient, 
{$\rho _k$ denotes the Rician factor,}
${\mathbf{\bar h}}_{{\rm{LoS}}}^k = {\mathbf{a}}({\theta _k}) = \left[ {1,{e^{j\frac{{2\pi }}{\lambda }d\sin \left( {{\theta _k}} \right)}},...,{e^{j\frac{{2\pi }}{\lambda }d\left( {{N_t} - 1} \right)\sin \left( {{\theta _k}} \right)}}} \right]$ denotes the constituents of the line-of-sight (LoS) link, 
$\theta_k$ is the azimuth angle of $U_k$, 
$\lambda$ is wavelength, 
$d $ is the adjacent antenna spacing,  
${\mathbf{\tilde h}}_{\rm{NLoS}}^k$ denotes the constituent of the non-LoS link, which obeys a complex Gaussian distribution with zero mean and unit variance.
The signal received by $U_k$ is expressed as
\begin{align}
	{y_k} &= {\mathbf{h}}_k^H{\mathbf{x}} + {n_k} \nonumber\\
	&= {\mathbf{h}}_k^H\left( {{{\mathbf{w}}_c}{{{s}}_c} + \sum\limits_{k \in K} {{{\mathbf{w}}_k}{{{s}}_k}}  + {{\mathbf{w}}_{v}}}{{{{s}}_v}} \right) + {n_k}, \label{signalyk}
\end{align}
where $n_k$ denotes additive white Gaussian noise (AWGN).

{ Like \cite{MaoY2022Survey, LiuZ2024IOT, XiaH2023CL},} 
all the LUs decode the common stream first based on a shared codebook and extracts its own information when receiving the signal stream, the private stream of all the LUs and extra signal are treated as interference. Then the SINR of the common stream at $U_k$ is expressed as
\begin{align}
	{\gamma _{c,k}} &= \frac{{{{\left| {{\mathbf{h}}_k^H{{\mathbf{w}}_c}} \right|}^2}}}{{\sum\limits_{i = 1}^K {{{\left| {{\mathbf{h}}_k^H{{\mathbf{w}}_i}} \right|}^2}}  + {{\left| {{\mathbf{h}}_k^H{{\mathbf{w}}_v}} \right|}^2} + \sigma _k^2}} \nonumber\\
	&= \frac{{{\mathbf{h}}_k^H{{\mathbf{W}}_c}{{\mathbf{h}}_k}}}{{\sum\limits_{i = 1}^K {{\mathbf{h}}_k^H{{\mathbf{W}}_i}{{\mathbf{h}}_k}}  + {\mathbf{h}}_k^H{{\mathbf{W}}_v}{{\mathbf{h}}_k} + \sigma _k^2}}, \label{SNRck}
\end{align}	
where ${\mathbf{W}}_q={\mathbf w}_q{\mathbf w}_q^H$ and $q \in \left\{ {c,k,v} \right\}$.
After decoding the common stream, $U_k$ adopts the successive interference cancellation (SIC) technique to remove the common signal from the received signal and then decode the private part. 
When decoding the private signal, all signals other than its own private signal are regarded as interference, and the SINR of the private part at $U_k$ is expressed as			
\begin{align}
	{\gamma _{p,k}} &= \frac{{{{\left| {{\mathbf{h}}_k^H{{\mathbf{w}}_k}} \right|}^2}}}{{\sum\limits_{i = 1,i \ne k}^K {{{\left| {{\mathbf{h}}_k^H{{\mathbf{w}}_i}} \right|}^2}}  +  {{\left| {{\mathbf{h}}_k^H{{\mathbf{w}}_{v}}} \right|}^2} + {\sigma_k ^2}}} \nonumber\\
	&=\frac{{ {{\mathbf{h}}_k^H{{\mathbf{W}}_k}{{\mathbf{h}}_k}} }}{{\sum\limits_{i = 1,i \ne k}^K { {{\mathbf{h}}_k^H{{\mathbf{W}}_i}{{\mathbf{h}}_k}}  +   {{\mathbf{h}}_k^H{{{{\mathbf{W}}_v}}}{{\mathbf{h}}_k}}  + {\sigma_k ^2}} }}. \label{SNRpk}
\end{align}	

