\subsection{Sensing Model}	

%{\color{red}It is assumed that ISAC BS can utilize extra signals and common stream signals for cooperative sensing to fully utilize the energy and enhance the spectral efficiency \cite{JangC2024WCL}. Problem!}
Depending on which signal is utilized to perform the sensing function, the sensing signal is expressed as
\begin{align}
	{\mathbf{X}} = {\alpha _1}{{\mathbf{w}}_c}{{{s}}_c} + {\alpha _2}{{\mathbf{w}}_{v}}{{{s}}_v},
\end{align}
where 
$\alpha _1$ and $\alpha _2$ are binary variables.
{Depending on the values of $\alpha _1$ and $\alpha _2$, the following schemes are considered:
\begin{enumerate}
	\item Scheme 1: ${\alpha _1} = 0$ and ${\alpha _2} = 1$. In this scheme, the extra signal is utilized to sense the targets. % 

	\item Scheme 2: ${\alpha _1} = 1$ and ${\alpha _2} = 0$. In this scheme, the common stream is utilized for target sensing and the extra signal that is utilized as AN to improve the secrecy performance of the RSMA systems.
	\item Scheme 3: ${\alpha _1} = 1$ and ${\alpha _2} = 1$. Both the common stream and extra sequence are utilized for target sensing\footnote{
		A common point between Scheme 2 and Scheme 3 is that the common stream is utilized to sense the targets. The difference is whether the extra signal is used to sense. 
		This work considers the communication-centered scenarios while taking the sensing requirement as a constraint. Thus, Scheme 2 and Scheme 3 have similar performance, which is testified in \cite{XuC2021JSTSP} and Fig. \ref{fig02} of Section V. 		
	}. 
\end{enumerate}}

The received echo signal at $S$ is expressed as\footnote{
	%找一下文献，下行通信场景+PLS
Like \cite{SuN2024TWC}, \cite{ZhaoB2025WCL}, since the radar BS generally has a strong signal separation capability, and a variety of methods can be used for filtering. We assume that $S$ can perfectly separate the echo from $T_t$ from the interference. 
}
\begin{align}
	{\mathbf{Y}}\left( {\bm{\theta }} \right) = {{\mathbf{A}}_r}\left( {\bm{\theta }} \right){\mathbf{BA}}_t^H\left( {\bm{\theta }} \right){\mathbf{X}} + {\mathbf{Q}},
\end{align}
where 
${{\mathbf{A}}_r} = \left[ {{{\mathbf{a}}_r}\left( {{\theta _1}} \right),...,{{\mathbf{a}}_r}\left( {{\theta _T}} \right)} \right]$, 
${{\mathbf{A}}_t} = \left[ {{{\mathbf{a}}_t}\left( {{\theta _1}} \right),...,{{\mathbf{a}}_t}\left( {{\theta _T}} \right)} \right]$, ${\mathbf{B}} = {\rm diag}\left( {{\beta _1},...,{\beta _T}} \right),{\bm{\theta }} = \left[ {{{\mathbf{\theta }}_1},...,{{\mathbf{\theta }}_T}} \right]$,  
${{\mathbf{a}}_r}\left( \theta  \right) = \left[ {1,{e^{j\frac{{2\pi }}{\lambda }d\sin \left( \theta  \right)}},...,{e^{j\frac{{2\pi }}{\lambda }d\left( {{N_r} - 1} \right)\sin \left( \theta  \right)}}} \right]$, 
$\theta_t$ is the angle of $T_t$, 
$\beta _t = b_{R_t} + jb_{I_t}$ denotes the target reflection complex amplitude, which is a normalization factor that depends on the radar cross section and path loss of the $t$-th target \cite{HuaH2024TWC, LiJ2008TSP, WuG2024IOT},
and 
${\bm{Q} }\sim CN\left( {0,{\sigma ^2}{\mathbf{I}}} \right)$ denotes the AWGN matrix. 

In this work, the aim of sensing is to estimate ${\bm\zeta} = [\bm{\theta},\mathbf{B}_R,\mathbf{B}_I]$, where 
${{\mathbf{B}}_R} = \left[ {{b_{{R_1}}}, \cdots ,{b_{{R_T}}}} \right]$ 
and 
${{\mathbf{B}}_I} = \left[ {{b_{{I_1}}}, \cdots ,{b_{{I_T}}}} \right]$.
The CRB of ${\bm\zeta}$ is utilized as the sensing performance metric and expressed as \cite{LiJ2008TSP}
\begin{align}
	\bm{\phi(\bm\zeta)} = {\mathbf{F}^{ - 1}},
\end{align}
where 
${\mathbf{F}}$ denotes the FIM, which is expressed as
\begin{align}
	\mathbf{F} = \frac{2}{\sigma ^2}\left[ {\begin{array}{*{20}{c}}
			{{\mathop{\rm Re}\nolimits} \left( {{{\mathbf{F }}_{11}}} \right)}&{{\mathop{\rm Re}\nolimits} \left( {{{\mathbf{F }}_{12}}} \right)}&{ - {\mathop{\rm Im}\nolimits} \left( {{{\mathbf{F }}_{12}}} \right)}\\
			{{{{\mathop{\rm Re}\nolimits} }^T}\left( {{{\mathbf{F }}_{12}}} \right)}&{{\mathop{\rm Re}\nolimits} \left( {{{\mathbf{F }}_{22}}} \right)}&{ - {\mathop{\rm Im}\nolimits} \left( {{{\mathbf{F }}_{22}}} \right)}\\
			{ - {{{\mathop{\rm Im}\nolimits} }^T}\left( {{{\mathbf{F }}_{12}}} \right)}&{ - {{{\mathop{\rm Im}\nolimits} }^T}\left( {{{\mathbf{F }}_{22}}} \right)}&{{\mathop{\rm Re}\nolimits} \left( {{{\mathbf{F }}_{22}}} \right)}
	\end{array}} \right],
\end{align}
where 
${{\mathbf{F}}_{11}} = L\left( {\dot {\mathbf{A }}_r^H{{\dot {\mathbf{A }}}_r}} \right) \odot \left( {{{\mathbf{B }}^*}{\mathbf{A }}_t^H{{\mathbf{R }}^*}{{\mathbf{A }}_t}{\mathbf{B }}} \right)+ L\left( {\dot {\mathbf{A }}_r^H{{\mathbf{A }}_r}} \right) \odot \left( {{{\mathbf{B }}^*}{\mathbf{A }}_t^H{{\mathbf{R }}^*}{{\dot {\mathbf{A }}}_t}{{\mathbf{B }}^T}} \right) + L\left( {{\mathbf{A }}_r^H{{\dot {\mathbf{A }}}_r}} \right) \odot \left( {{{\mathbf{B }}^*}\dot {\mathbf{A }}_t^H{{\mathbf{R }}^*}{{\mathbf{A }}_t}{{\mathbf{B }}^T}} \right) + L\left( {{\mathbf{A }}_r^H{{\mathbf{A }}_r}} \right) \odot \left( {{{\mathbf{B }}^*}\dot {\mathbf{A }}_t^H{{\mathbf{R }}^*}{{\dot {\mathbf{A }}}_t}{{\mathbf{B }}^T}} \right)$,
${{\mathbf{F}}_{12}} =L\left( {\dot {\mathbf{A }}_r^H{{\mathbf{A }}_r}} \right) \odot \left( {{{\mathbf{B }}^*}{\mathbf{A }}_t^H{{\mathbf{R }}^*}{{\mathbf{A }}_t}} \right) + L\left( {{\mathbf{A }}_r^H{{\mathbf{A }}_r}} \right) \odot \left( {{{\mathbf{B }}^*}\dot {\mathbf{A }}_t^H{{\mathbf{R }}^*}{{\mathbf{A }}_t}} \right)$, 
and ${{\mathbf{F}}_{22}} = L\left( {{\mathbf{A }}_r^H{{\mathbf{A }}_r}} \right) \odot \left( {{\mathbf{A }}_t^H{{\mathbf{R }}^*}{{\mathbf{A }}_t}} \right)$,
${\dot {\mathbf A}_r} = \left[ {\frac{{\partial {{\mathbf{a }}_r}}}{{\partial {\theta _1}}},...\frac{{\partial {{\mathbf{a }}_r}}}{{\partial {\theta _t}}}} \right]$
${\dot {\mathbf A}_t} = \left[ {\frac{{\partial {{\mathbf{a }}_t}}}{{\partial {\theta _1}}},...\frac{{\partial {{\mathbf{a }}_t}}}{{\partial {\theta _t}}}} \right]$,
$\mathbf{R}$ is the covariance matrix of the sensing signal $\mathbf X$ and is denoted by
\begin{align}
	{\mathbf{R}} ={\alpha _1} {\mathbf{W}}_c + {\alpha _2} {{{{\mathbf{W}}_v}}}.
\end{align}

\section{The Scenarios with Eavesdropping CSI}
\label{sec:WithECSI}

{In this section, the scenarios wherein the eavesdropping CSI is available are considered. 
	Two optimization problems are formulated to design the precoding matrices. 
	One is maximizing the minimum URPR by jointly designing the BF vectors and CRA subject to the QoS, security, and sensing constraints, and 
	the other is maximizing the minimum USRPR by jointly designing the beamforming vectors and secrecy CRA subject to the QoS and sensing constraints.  }

\subsection{Maximizing the Minimum User's Rate to BS's Power Ratio}

{
In this subsection, it is assumed that the confidential messages are transmitted in the private stream and the common stream is utilized as AN. Thus the achievable secrecy rate of $U_k$ is equal to
${\left[ {{R_{p,k}} - \mathop {\max }\limits_m {R_{p,k,m}^{\rm{E}}}} \right]^ + }$,
where 
${\left[ x \right]^ + } = \max \left( {x,0} \right)$.
To ensure that the common stream can not be decoded by all the eavesdroppers, the following constraint must be satisfied { \cite{MaoY2022Survey, YaoB2024ARX, LiuZ2024IOT, GaoP2023JSAC}} 
\begin{align}
	\mathop {\max }\limits_{1 \le m \le M} {R_{c,m}^{\rm{E}}} \le {R_c}.
\end{align}	}

We consider the problem of minimizing the transmit power at $S$ and maximizing the minimum total rate among all the LUs by constraining the QoS, security, and sensing performance. The following optimization problem is formulated
\begin{subequations}
	\begin{align}	
		\mathcal{P}_{1} \,:\, &\mathop {\max }\limits_{{\mathbf{W}}, {\mathbf{C}}} \mathop {\min }\limits_k \,\, {\eta _k}             \label{P1a}\\
		{\mathrm{s.t.}}\; 
		&{c_k} \ge 0, \forall k,         																	\label{P1b}\\
		&\sum\limits_{i = 1}^K {{c_i}}  \le {R_{c}},  									  		\label{P1c}\\	
		&{{{R_c} - \mathop {\max }\limits_{1 \le m \le M} R_{c,m}^{\rm{E}}} > 0,}       			\label{P1d}  \\	
		&{ {R_{p,k}} - \mathop {\max }\limits_{1 \le m \le M} R_{p,k,m}^{\rm{E}} \ge R_{\sec }^{\rm th}, \forall k, }\label{P1e}\\
		& {R_k^{{\rm{total}}}} \ge {R_{\rm{U}}^{{\rm{th}}}}, \forall k									\label{P1f}			\\	
		&\left| {{\bm \phi} \left( {\bm \varsigma } \right)} \right| \le \vartheta,   			\label{P1g}\\
		&P \le {P_{\max }},                 													\label{P1h}\\
		&{{\mathbf{W}}_q} \succeq 0, q \in \left\{ {c,k,v} \right\},        						\label{P1i}\\
		&{\mathrm {rank}}\left( {{{\mathbf{W}}_q}} \right) = 1, q \in \left\{ {c,k,v} \right\},		\label{P1j} 
	\end{align} 
\end{subequations}	
where {
${\eta _k} = \frac{{R_k^{{\rm{total}}}}}{P}$,
which denotes the URPR of $U_k$ in this work\footnote{ 	
	It is important to note that URPR of $U_k$ represents the ratio of $U_k$'s total rate to the transmit power of the ISAC BS. This metric differs from both user' EE and system's EE. In uplink scenarios, users' EE is defined as the ratio of the user’s achievable rate to its own transmit power. In downlink scenarios, system's EE is defined as the ratio of the sum rate to the BS’s transmit power.
}, }
${\mathbf{W}} = \left\{ {{{\mathbf{W}}_c},{{\mathbf{W}}_k},{{\mathbf{W}}_v}} \right\}$, 
$P = {\rm{tr}}\left( {{{\mathbf{W}}_c}} \right) + \sum\limits_{k = 1}^K {{\rm{tr}}\left( {{{\mathbf{W}}_k}} \right)}  + {\rm{tr}}\left( {{{{\mathbf{W}}_v}}} \right)$, 
${\mathbf{C}} = \left\{ {{c_k}, k = 1, 2, ..., K} \right\}$, 
and 
$\vartheta$ denotes the CRB requirement.
(\ref{P1b}) and (\ref{P1c}) are the common stream constraints for the LUs, 
(\ref{P1d}) ensures that the common stream can not be decoded by the eavesdroppers, 
(\ref{P1e}) denotes the secrecy constraints, 
(\ref{P1f}) denotes the total rate constraints, 
(\ref{P1g}) is the CRB constraint on the accuracy of the estimation of the target parameters, 
(\ref{P1h}) denotes the total power budget constraint of $S$, 
and 
(\ref{P1i}) and (\ref{P1j}) are positive semi-definite and rank one constraints.
{Due to the non-convexity of the fractional objective function (\ref{P1a}) and non-convex constraints (\ref{P1c})-(\ref{P1f}) and (\ref{P1j}), solving $\mathcal{P}_{1}$ is challenging.}

%1目标函数
Firstly, utilizing the Dinkelbach’s method, $\mathcal{P}_{1}$ is reformulated as  
\begin{subequations}
	\begin{align}	
		\mathcal{P}_{1.1} &\mathop {\max }\limits_{{\mathbf{W}}, {\mathbf{C}},\lambda_1 } f\left( {\mathbf{W}},{\mathbf{C}} \right)  - \lambda_1 P   \label{P1.1a}\\
		&{\mathrm{s.t.}}\; {\rm (\ref{P1b})} - {\rm (\ref{P1j})},  \nonumber
	\end{align} 
\end{subequations}	
where 
$f\left( {\mathbf{W}}, {\mathbf{C}} \right) = \min \left( R_k^{\rm{total}} \right) = \min \left( {{c_k} + R_{p,k}} \right)$ 
and 
$\lambda_1$ is the penalty factor, which is obtained iteratively as follows 
\begin{align}	
	\lambda _1^{\left( {j + 1} \right)} = \frac{{{{\left( {\mathop {\min }\limits_k R_k^{\rm{total}}} \right)}^{\left( j \right)}}}}{{{P^{\left( j \right)}}}},
\end{align} 
where 
${\left(  \right)} ^{\left( j \right)}$ denotes the $j$-th iteration value.

%2 公共可达速率，对应约束是c和d？
Secondly, (\ref{P1c}) and (\ref{P1d}) are non-convex because the concavity of $R_{c,k}$ is uncertain. To deal this problem, 
based on (\ref{barSNRck}) and (\ref{Rck}),
$R_{c,k}$ is rewritten as
\begin{align}
	{R_{c,k}} & = \underbrace {{{\log }_2}\left( {{\rm{tr}}\left\{ {{{\mathbf{H}}_k}{{\mathbf{W}}_c}} \right\} + {\chi_1} + \sigma _k^2} \right)}_{ \buildrel \Delta \over = R_{c,k}^1} \nonumber \\
	& - \underbrace {{{\log }_2}\left( {{\chi_1} + \sigma _k^2} \right)}_{R_{c,k}^2}, \label{Rck22}
\end{align}
where 
${\chi_1} = {\rm{tr}}\left\{ {{{\mathbf{H}}_k}\sum\limits_{i = 1}^K {{{\mathbf{W}}_i}} } \right\} + {\rm{tr}}\left\{ {{{\mathbf{H}}_k}{{\mathbf{W}}_v}} \right\}$. 
It should be noted that both $R_{c,k}^1$ and $R_{c,k}^2$ are concave functions with respect to ${\mathbf W}$, which is proved in Appendix \ref{sec:appendicesA}. 
Then, the upper bound of $R_{c,k}^2$ is obtained as
\begin{align}
	R_{c,k}^2 &\le \frac{1}{{\ln 2}} \left({ {{{\left( {A_1^{\left( j \right)}} \right)}^{ - 1}} {{\chi_1}} }  - \left( {{{ {A_1^{\left( j \right)}} }^{ - 1}}\chi_1^{\left( j \right)}} \right)} \right) +{\log _2}\left(A_1^{\left( j \right)}\right) \nonumber\\
	& \buildrel \Delta \over = R_{c,k}^{2,{\rm {ub}}}, \label{Rck2up}
\end{align}
where 
$\chi_1^{\left( j \right)} = {\rm{tr}}\left\{ {{{\mathbf{H}}_k}\sum\limits_{i = 1}^K {{\mathbf{W}}_i^{\left( j \right)}} } \right\} + {\rm{tr}}\left\{ {{{\mathbf{H}}_k}{\mathbf{W}}_v^{\left( j \right)}} \right\}$ 
and 
$A_1^{\left( j \right)} = \chi_1^{\left( j \right)} + \sigma _k^2$.
Then, (\ref{P1c}) is reformulated as
\begin{align}
\sum\limits_{k = 1}^K {{c_k}}  \le R_{c,k}^1 - R_{c,k}^{2, {\rm{ub}}}, \forall k.	\label{p1.2c}	
\end{align}

Similarly, ${R_{c,m}^{\rm{E}}}$ is rewritten as
\begin{align}
	{R_{c,m}^{\rm{E}}} &= \underbrace {{{\log }_2}\left( {{\chi_2}} \right.\left. { + \sigma _m^2} \right)}_{ \buildrel \Delta \over = R_{c,m}^{{\rm{E}},1}} \nonumber \\
	&- \underbrace {{{\log }_2}\left( {{\rm{tr}}\left\{ {{{\mathbf{G}}_m}\sum\limits_{i = 1}^K {{{\mathbf{W}}_i}} } \right\} + {\rm{tr}}\left\{ {{{\mathbf{G}}_m}{{\mathbf{W}}_v}} \right\} + \sigma _m^2} \right)}_{ \buildrel \Delta \over = R_{c,m}^{{\rm{E}},2}},
\end{align}
where 
${\chi_2} = {\rm{tr}}\left\{ {{{\mathbf{G}}_m}{{\mathbf{W}}_c}} \right\} + {\rm{tr}}\left\{ {{{\mathbf{G}}_m}\sum\limits_{i = 1}^K {{{\mathbf{W}}_i}} } \right\} + {\rm{tr}}\left\{ {{{\mathbf{G}}_m}{{\mathbf{W}}_v}} \right\}$.
By utilizing the SCA technique, we have 
\begin{align}
	R_{c,m}^{{\rm{E}},1} &\le \frac{1}{{\ln 2}} \left({ {{{\left( {A_2^{\left( j \right)}} \right)}^{ - 1}}{{\chi_2}} }  - \left( {{{{A_2^{\left( j \right)}} }^{ - 1}}\chi_2^{\left( j \right)}} \right)} \right) +{\log _2}\left(A_2^{\left( j \right)}\right) \nonumber\\
	&\buildrel \Delta \over = R_{c,m}^{{\rm{E}}, 1, {\rm{ub}}},
\end{align}
where 
$\chi_2^{\left( j \right)} = {\rm{tr}}\left\{ {{{\mathbf{G}}_m}{\mathbf{W}}_c^{\left( j \right)}} \right\} + {\rm{tr}}\left\{ {{{\mathbf{G}}_m}\sum\limits_{i = 1}^K {{\mathbf{W}}_i^{\left( j \right)}} } \right\} + {\rm{tr}}\left\{ {{{\mathbf{G}}_m}{\mathbf{W}}_v^{\left( j \right)}} \right\}$ and $A_2^{\left( j \right)} = \chi_2^{\left( j \right)} + \sigma _m^2$.
Then, (\ref{P1d}) is reformulated as
\begin{align}
	R_{c,k}^1 - R_{c,k}^{2, {\rm{ub}}} \ge R_{c,m}^{{\rm{E}}, 1, {\rm{ub}}} - R_{c,m}^{{\rm{E}},2}, \forall k, m.	\label{p1.2d}	
\end{align}

{(\ref{P1e}) and (\ref{P1f}) are non-convex because the concavity of ${R_{p,k}}$ and $R_{p,k,m}^{\rm{E}}$ is uncertain. }
With the same method, ${R_{p,k}}$ is rewritten as
\begin{align}	
	{R_{p,k}} &= \underbrace {{{\log }_2}\left( {{\rm{tr}}\left\{ {{{\mathbf{H}}_k}{{\mathbf{W}}_k}} \right\} + {\chi_3} + \sigma _k^2} \right)}_{ \buildrel \Delta \over = R_{p,k}^1} \nonumber\\
	&- \underbrace {{{\log }_2}\left( {{\chi_3} + \sigma _k^2} \right)}_{ \buildrel \Delta \over = R_{p,k}^2},
\end{align}
where  
${\chi_3} = {\rm{tr}}\left\{ {{{\mathbf{H}}_k}\sum\limits_{i = 1,i \ne k}^K {{{\mathbf{W}}_i}} } \right\} + {\rm{tr}}\left\{ {{{\mathbf{H}}_k}{{\mathbf{W}}_v}} \right\}$. 
It should be noted that both $R_{p,k}^1$ and $R_{p,k}^2$ are concave functions with respect to ${\mathbf W}$.
Similar to (\ref{Rck2up}), the upper bound of the convex approximation to $R_{p,k}^2 $ is obtained as
\begin{align}
	R_{p,k}^2 & \le  \frac{1}{{\ln 2}}\left( { {{{\left( {A_3^{\left( j \right)}} \right)}^{ - 1}}{\chi_3}} - {{{\left( {A_3^{\left( j \right)}} \right)}^{ - 1}}\chi_3^{\left( j \right)}} } \right) +{\log _2}\left(A_3^{\left( j \right)}\right) \nonumber\\
	& \buildrel \Delta \over = R_{p,k}^{2, {\rm{ub}}},
\end{align}
where 
$\chi_3^{\left( j \right)} = {\rm{tr}}\left\{ {{{\mathbf{H}}_k}\sum\limits_{i = 1,i \ne k}^K {{\mathbf{W}}_i^{\left( j \right)}} } \right\} + {\rm{tr}}\left\{ {{{\mathbf{H}}_k}{\mathbf{W}}_v^{\left( j \right)}} \right\}$ 
and 
$A_3^{\left( j \right)} = \chi_3^{\left( j \right)} + \sigma _k^2$. 


With the same method as (\ref{Rck22}), $R_{p,k,m}^{\rm{E}}$ is rewritten as
\begin{align}
	R_{p,k,m}^{\rm{E}} &= \underbrace {{{\log }_2}\left( {{\rm{tr}}\left\{ {{{\mathbf{G}}_m}{{\mathbf{W}}_k}} \right\} + {\chi_4} + \sigma _m^2} \right)}_{ \buildrel \Delta \over = R_{p,k,m}^{{\rm{E}},1}} \nonumber\\
	& - \underbrace {  {{\log }_2}\left( {{\chi_4} + \sigma _m^2} \right)}_{ \buildrel \Delta \over = R_{p,k,m}^{{\rm{E}},2}},
\end{align}
where 
${\chi_4} = {\rm{tr}}\left\{ {{{\mathbf{G}}_m}{{\mathbf{W}}_c}} \right\} + {\rm{tr}}\left\{ {{{\mathbf{G}}_m}\sum\limits_{i = 1,i \ne k}^K {{{\mathbf{W}}_i}} } \right\} + {\rm{tr}}\left\{ {{{\mathbf{G}}_m}{{\mathbf{W}}_v}} \right\}$.
Then, the lower bound of the ${R_{p,k,m}^{{\rm{E}},1}}$ is obtained as
\begin{align}
	{R_{p,k,m}^{{\rm{E}},1}} &\le \frac{1}{{\ln 2}} \left({ {{{\left( {A_4^{\left( j \right)}} \right)}^{ - 1}} {{\chi_4}} }  - {{{\left( {A_4^{\left( j \right)}} \right)}^{ - 1}}\chi_4^{\left( j \right)}} } \right) +{\log _2}\left(A_4^{\left( j \right)}\right) \nonumber\\
	& \buildrel \Delta \over = R_{p,k,m}^{{\rm{E}}, 1, {\rm{ub}}},	
\end{align}
where 
$\chi_4^{\left( j \right)} = {\rm{tr}}\left\{ {{{\mathbf{G}}_m}{\mathbf{W}}_c^{\left( j \right)}} \right\} + {\rm{tr}}\left\{ {{{\mathbf{G}}_m}\sum\limits_{i = 1,i \ne k}^K {{\mathbf{W}}_i^{\left( j \right)}} } \right\} + {\rm{tr}}\left\{ {{{\mathbf{G}}_m}{\mathbf{W}}_v^{\left( j \right)}} \right\}$ 
and
$A_4^{\left( j \right)} = {\rm{tr}}\left\{ {{{\mathbf{G}}_m}{\mathbf{W}}_k^{\left( j \right)}} \right\} + \chi_4^{\left( j \right)}$.
Then, (\ref{P1e}) and (\ref{P1f}) are reformulated as 
\begin{align}
	&R_{p,k}^1 - R_{p,k}^{2, {\rm{ub}}} - (R_{p,k,m}^{{\rm{E}}, 1, {\rm{ub}}} - R_{p,k,m}^{{\rm{E}},2}) \ge R_{\sec }^{\rm th}, \forall k, m	\label{p1.2e}
\end{align}
and 
\begin{align}
	c_k+R_{p,k}^1 - R_{p,k}^{2, {\rm{ub}}}  \ge {R_{\rm{U}}^{{\rm{th}}}}, \forall k,	\label{p1.2f}
\end{align}
respectively.




Finally, by introducing the slack variable $t$, $\mathcal{P}_{1.1}$ is rewritten as
\begin{subequations}
	\begin{align}
		\mathcal{P}_{1.2} \,:\, & \mathop {\max }\limits_{{\mathbf{W}}, {\mathbf{C}},t} t\\
		{\mathrm{s.t.}}\; 
		&\hat f\left( {\mathbf{W}}, {\mathbf{C}} \right) - \lambda_1 P  \ge t,    \label{p1.2b}		\\
		&({\rm \ref{P1b}}),({\rm \ref{P1g}})-({\rm \ref{P1j}})		\nonumber			\\
		& ({\rm \ref{p1.2c}}), ({\rm \ref{p1.2d}}), ({\rm \ref{p1.2e}}), ({\rm \ref{p1.2f}}), 			\nonumber	
	\end{align} 
\end{subequations}	
where $\hat f\left( {\mathbf{W}}, {\mathbf{C}} \right) = \min \left( {{c_k} + \left( {R_{p,k}^1 - R_{p,k}^{2, {\rm{ub}}}} \right)} \right) $.
By ignoring the Rank-1 constraint (\ref{P1j}), $\mathcal{P}_{1.2}$ is a convex problem that can be solved to obtain ${\mathbf{W}}$.

For (\ref{P1j}), the rank-1 of ${\mathbf{W}}_q$ means that the matrix ${\mathbf{W}}_q$  has only one non-zero eigenvalue, which is equivalent to the fact that the trace of ${\mathbf{W}}_q$ is equal to its largest eigenvalue, which is expressed as \cite{LiuZ2024TWC}
\begin{align}
	{\mathrm{rank}}\left( {{{\mathbf{W}}_q}} \right) = 1 \Leftrightarrow  {\mathrm{tr}}\left( {{{\mathbf{W}}_q}} \right) = {\chi _{{q}}},
	\label{Eq41}
\end{align}
where $\chi _{q}$ denotes the maximum eigenvalue obtained from the eigen decomposition of ${{\mathbf{W}}_q}$.   
(\ref{Eq41}) is non-convex and the following iterative algorithm is utilized  
\begin{align}
	{\mathrm{tr}}\left( {{{\mathbf{W}}_q}} \right) = {\chi _q} \Rightarrow {\mathrm{tr}}\left( {{{\mathbf{W}}_q}} \right) = {\left( {{\bf{u}}_q^{\left( {j } \right)}} \right)^H}{{\mathbf{W}}_q}{\bf{u}}_q^{\left( {j } \right)},
	\label{Eq46}
\end{align}
where 
${{\bf{u}}_q}$ is the eigenvector corresponding to the largest eigenvalue $\chi _q$ of ${{\mathbf{W}}_q}$. 
Then, by utilizing a penalty function in the objective function, the optimization problem is expressed as \cite{LiuZ2024TWC}
\begin{subequations}
	\begin{align}
		\mathcal{P}_{1.3} & \mathop {\max }\limits_{{\mathbf{W}}, {\mathbf{C}},t} t - {\rho _1}\left( { {\mathrm{tr}}\left( {{{\mathbf{W}}_c}} \right) - {{\left( {{\bf{u}}_c^{\left( {j } \right)}} \right)}^H}{{\mathbf{W}}_c}{\bf{u}}_c^{\left( {j } \right)}} \right) \nonumber\\ 
		& \qquad - {\rho _1}\sum\limits_{k = 1}^K {\left( { {\mathrm{tr}}\left( {{{\mathbf{W}}_k}} \right) - {{\left( {{\bf{u}}_k^{\left( {j } \right)}} \right)}^H}{{\mathbf{W}}_k}{\bf{u}}_k^{\left( {j } \right)}} \right)} \nonumber\\ 
		&  \qquad- {\rho _1}\left( { {\mathrm{tr}}\left( {{{{\mathbf{W}}_v}}} \right) - {{\left( {{\bf{u}}_v^{\left( {j } \right)}} \right)}^H}{{{{\mathbf{W}}_v}}}{\bf{u}}_v^{\left( {j } \right)}} \right)\\
		{\mathrm{s.t.}}\; 
		& ({\rm \ref{P1b}}), ({\rm \ref{P1g}})-({\rm \ref{P1i}}),  										\nonumber	\\
		& ({\rm \ref{p1.2c}}), ({\rm \ref{p1.2d}}), ({\rm \ref{p1.2e}}), ({\rm \ref{p1.2f}}), ({\rm \ref{p1.2b}}),		\nonumber			
	\end{align} 
\end{subequations}	
where $\rho _1$ denotes the penalty factor.

$\mathcal{P}_{1.3}$ is a standard convex problem that can be solved using the CVX toolbox. The algorithm is summarized as \textbf{Algorithm 1}, where $j \le J_{\max}$ denotes the maximum number of iterations.

\begin{algorithm}[t]
\caption{Iterative Procedure of $\mathcal{P}_{1.3}$}
\KwIn{Initialize ${P_{\max }}$, $R_{\rm U}^{\rm th}$, $R_{\sec }^{\rm th}$, $\rho_1$, $\tau$, $\vartheta$, ${\mathbf{W}}_q^{\left( 0 \right)}$, ${\bf{u}}_q^{\left( 0 \right)}$, $\lambda_1^{\left( 0 \right)}$, $j \leftarrow 0$}
\Do{$\| opt^{(j+1)}-opt^{(j)}\| > \tau$ {\rm or} $j < J_{\max}$}
{   1. Solve $\mathcal{P}_{1.3}$ and obtain ${\mathbf W}_q^{\left( j+1 \right)}$;\\
	2. Obtain ${{{\bf{u}}_q}^{\left( j + 1 \right)}}$ by decomposing  ${\mathbf{W}}_q^{\left( j+1 \right)}$;\\     
	3. $\lambda _1^{\left( {j + 1} \right)} = \frac{{{{\left( {\mathop {\min }\limits_k R_k^{\rm{total}}} \right)}^{\left( j + 1 \right)}}}}{{{P^{\left( j + 1 \right)}}}}$;\\
	4. $j = j + 1$;
}
\KwOut{${\mathbf W}_q^{\left( j \right)}$}

\end{algorithm}

\begin{algorithm}[t]
	\caption{Iterative Procedure of $\mathcal{P}_{2.1}$}
	\KwIn{Initialize ${P_{\max }}$, $R_{\sec }^{\rm th}$, $\rho_2$, $\tau$, $\vartheta$,
		${\mathbf{W}}_q^{\left( 0 \right)}$, ${\bf{u}}_q^{\left( 0 \right)}$, $\lambda_2^{\left( 0 \right)}$, $j \leftarrow 0$.}
		\Do{$\| opt^{(j+1)}-opt^{(j)}\| > \tau$ {\rm or} $j < J_{\max}$}
		{   1. Solve $\mathcal{P}_{2.1}$ and obtain ${\mathbf W}_q^{\left( j+1 \right)}$;\\
			2. Obtain ${{{\bf{u}}_q}^{\left( j+1 \right)}}$ by decomposing  ${\mathbf{W}}_q^{\left( j+1 \right)}$;\\   
			3. $\lambda _2^{\left( {j + 1} \right)} = \frac{R_k^{\sec ,{\rm{lb,}}\left( j + 1 \right)}}{P^{\left( j + 1 \right)}}$;\\
			4. $j = j + 1$;	
		}
	\KwOut{${\mathbf W}_q^{\left( j \right)}$}
\end{algorithm}	

\subsection{Maximizing the Minimum User's Secrecy Rate to BS's Power Ratio}

{In this subsection, it is assumed that the confidential messages are transmitted in both common and private streams. 
We define $c_{c,k}^{\sec }$ as the non-negative common secrecy rate for $U_k$ is allocated. }
Then we have \cite{GaoY2023CL}
\begin{align}
	\sum\limits_{k = 1}^K {c_{c,k}^{\sec }} \le \left( {{R_c} - \mathop {\max }\limits_{1 \le m \le M} R_{c,m}^{\rm{E}}} \right).
	\label{commSR}
\end{align}

The achievable secrecy rate of $U_k$ is obtained as
\begin{align}
	R_k^{\sec } = c_{c,k}^{\sec } + {\left[ {{R_{p,k}} - \mathop {\max }\limits_{1 \le m \le M} {R_{p,k,m}^{\rm{E}}}} \right]^ + }.
\end{align}	


{We consider the problem of minimizing the transmit power at $S$ and maximizing the minimum secrecy rate among all the LUs by constraining the security requirement and sensing constraint.} 
The following optimization problem is formulates
\begin{subequations}
	\begin{align}	
		\mathcal{P}_{2} \,:\, &\mathop {\max }\limits_{{\mathbf{W}}, {\mathbf{\tilde C}}} \mathop {\min }\limits_{k}\,\,\, {\eta _k^{\sec }}     \label{p02_a} \\
		{\mathrm{s.t.}}\;
		&	c_{c,k}^{\sec } \ge 0,  \forall k,                    				\label{p02_b} \\
		&{	\sum\limits_{k = 1}^K {c_{c,k}^{\sec }} \le \left( {{R_c} - \mathop {\max }\limits_{1 \le m \le M} R_{c,m}^{\rm{E}}} \right), }												\label{p02_c} \\
		&{	{R_{p,k}} - \mathop {\max }\limits_{1 \le m \le M} R_{p,k,m}^{\rm{E}} \ge 0, \forall k,} \label{p02_d}\\
		& {{{R_k^{\sec }}}} \ge R_{\sec }^{\rm th}, 	\forall k,						\label{p02_e}	\\
		& {\rm (\ref{P1g})} - {\rm (\ref{P1j})}, 								\nonumber
	\end{align}
\end{subequations}
where {
$\eta _k^{\sec } = \frac{{R_k^{\sec }}}{P}$ denotes the USRPR of $U_k$ and 
${\mathbf{\tilde C}} = \left\{ {c_{c,k}^{\sec }}, k = 1, 2, ..., K \right\}$. }
(\ref{p02_b})-(\ref{p02_c}) are secrecy constraint for the common stream 
and 
(\ref{p02_d}) is secrecy constraint for the private stream.
$\mathcal{P}_{2}$ is challenging to solve because of the non-convexity of (\ref{p02_b})-(\ref{p02_e}) and (\ref{P1g})-(\ref{P1j}).

Firstly, to deal with $R_k^{\sec }$ in (\ref{p02_e}), its lower bound is utilized and expressed as
\begin{align}
	R_k^{\sec } &\ge c_{c,k}^{\sec } + R_{p,k}^1 - R_{p,k}^{2, {\rm{ub}}} - {R_{p,k,m}^{{\rm{E}}, 1, {\rm{ub}}} + R_{p,k,m}^{{\rm{E}},2}} \nonumber \\
	&\buildrel \Delta \over= R_k^{\sec, {\rm {lb}}}.
\end{align}
By introducing the slack variable $t_2$, the optimization objective function of $\mathcal{P}_{2}$ is rewritten as
\begin{align}
	R_k^{\sec, {\rm {lb}}} - {\lambda _2}P \ge {t_2}, \forall k, \label{eq46}
\end{align}
where $\lambda _2$ is obtained as
\begin{align}	
	\lambda _2^{\left( {j + 1} \right)} = \frac{R_k^{\sec ,{\rm{lb,}}\left( j \right)}}{P^{\left( j \right)}}.
\end{align} 
Then, with the same method as $\mathcal{P}_{1}$, $ \mathcal{P}_{2}$ is relaxed as
\begin{subequations}
	\begin{align}
		\mathcal{P}_{2.1} \,:\, &\mathop {\max }\limits_{{\mathbf{W}}, {\mathbf{\tilde C}},t_2} t_2 - {\rho _2}\left( { {\mathrm{tr}}\left( {{{\mathbf{W}}_c}} \right) - {{\left( {{\bf{u}}_c^{\left( {j } \right)}} \right)}^H}{{\mathbf{W}}_c}u_c^{\left( {j } \right)}} \right) \nonumber\\ 
		& \qquad - {\rho _2}\sum\limits_{k = 1}^K {\left( { {\mathrm{tr}}\left( {{{\mathbf{W}}_k}} \right) - {{\left( {{\bf{u}}_k^{\left( {j } \right)}} \right)}^H}{{\mathbf{W}}_k}{\bf{u}}_k^{\left( {j } \right)}} \right)} \nonumber\\ 
		&  \qquad- {\rho _2}\left( { {\mathrm{tr}}\left( {{{{\mathbf{W}}_v}}} \right) - {{\left( {{\bf{u}}_v^{\left( {j } \right)}} \right)}^H}{{{{\mathbf{W}}_v}}}{\bf{u}}_v^{\left( {j } \right)}} \right)\\
		{\mathrm{s.t.}}\;
		&\sum\limits_{k = 1}^K {c_{c,k}^{\sec } \le \left( {R_{c,k}^1 - R_{c,k}^{2, {\rm{ub}}}} \right) - } \left( {R_{c,m}^{1, {\rm{ub}}} - R_{c,m}^2} \right), 	\forall k, m,				\\
		&\left( {R_{p,k}^1 - R_{p,k}^{2, {\rm{ub}}}} \right) - \left( {R_{p,k,m}^{{\rm{E}}, 1, {\rm{ub}}} - R_{p,k,m}^{{\rm{E}},2}} \right) \ge 0,	\forall k, m,									\\
		&R_k^{\sec, {\rm {lb}}} \ge R_{\sec }^{\rm th},	\forall k,	\\
		& {\rm (\ref{P1g})} - {\rm (\ref{P1i})}, ({\rm \ref{p02_b}}), ({\rm \ref{eq46}}), 		\nonumber
	\end{align}
\end{subequations}
where $\rho _2$ represents the penalty factor.

$ \mathcal{P}_{2.1}$ is a standard convex problem that can be solved by an iterative optimization algorithm, which is summarized in \textbf{Algorithm 2}.

\begin{algorithm}[t]
	\caption{Iterative Procedure of $\mathcal{P}_{3.1}$}
	\KwIn{ Initialize ${P_{\max }}$, $R_{\rm U}^{\rm th}$, $\rho_3$, $\tau$, $\vartheta$,
		${\mathbf{W}}_q^{\left( 0 \right)}$, ${\bf{u}}_q^{\left( 0 \right)}$, $j \leftarrow 0$.}
	\Do{$\| opt^{(j+1)}-opt^{(j)}\| > \tau$ {\rm or} $j < J_{\max}$}
	{
		1. Solve $\mathcal{P}_{3.1}$ and obtain ${\mathbf W}_q^{\left( j+1 \right)}$;\\
		2. Obtain ${{{\bf{u}}_q}^{\left( j+1 \right)}}$ by decomposing  ${\mathbf{W}}_q^{\left( j+1 \right)}$;\\    
		3. $j = j + 1$;	
	}
	\KwOut{${\mathbf W}_q^{\left( j \right)}$}
\end{algorithm}

\section{The Scenarios Without Eavesdropping CSI}
\label{sec:WithoutECSI}

When the eavesdropper's CSI is unknown, on the premise of ensuring the communication and sensing performance, we use all the remaining energy to send the omni-directional AN to improve the security of communication, like refs. \cite{ChuJJ2023TVT} and \cite{SuN2024TWC}.
The transmitted signal at $S$ is expressed as
\begin{align}
	{\mathbf{x}} = {{\mathbf{w}}_c}{{{s}}_c} + \sum\limits_{k \in K} {{{\mathbf{w}}_k}{{{s}}_k}}  + {{\mathbf{w}}_{v}}{{{s}}_v} + {{\mathbf{w}}_{\rm{AN}}}{{{s}}_{\rm{AN}}}
\end{align}	
where 
${{{s}}_{\rm{AN}}}$ is the AN symbol which is assumed to be zero mean and unit power and 
${{\mathbf{w}}_{\rm{AN}}}$ is the transmission vector with ${\rm{diag}}\left( {{{\mathbf{W}}_{\rm{AN}}}} \right) = \frac{{\mathbf{I}}}{{{N_t}}}\left( {{P_{\max }} - P} \right)$ 
and ${\mathbf{W}}_{\rm{AN}}={\mathbf w}_{\rm{AN}}{\mathbf w}_{\rm{AN}}^H$.
It is assumed that $U_k$ and $S$ can perfectly eliminate ${{{s}}_{\rm{AN}}}$, like \cite{LiuZ2024TWC}.
Consequently, the BF matrices are designed to minimize the NPC for communication and sensing, thereby improving the system's secrecy performance. \color{black}
The formulated problem is expressed as	
\begin{subequations}
	\begin{align}
		\mathcal{P}_{3} \,:\, &\mathop {\min }\limits_{{\mathbf{W}}, {\mathbf{C}}} P   			\label{p03_a}\\
		{\mathrm{s.t.}}\;
		&{c_k} \ge 0, \forall k,     															\label{p03_b}\\
		&\sum\limits_{i = 1}^K {{c_i}}  \le {R_{c,k}},  \forall k,						  		\label{p03_c}\\		
		&{ {R_k^{{\rm{total}}}} \ge {R_{\rm{U}}^{{\rm{th}}}}, \forall k,}			\label{p03_d}\\
		& {\rm (\ref{P1g})}, {\rm (\ref{P1i})}, {\rm (\ref{P1j})}. 		\nonumber
	\end{align}
\end{subequations}



Based on the results in Section III.A, $\mathcal{P}_{3}$ is rewritten as 
\begin{subequations}

	\begin{align}
		\mathcal{P}_{3.1} \,:\, &\mathop {\min }\limits_{{\mathbf{W}}, {\mathbf{C}}} {\mathrm{tr}}\left( {{{\mathbf{W}}_c}} \right) + \sum\limits_{k = 1}^K {{\mathrm{tr}}\left( {{{\mathbf{W}}_k}} \right)} + {\mathrm{tr}}\left( {{{{{{\mathbf{W}}_v}}}}} \right)  \nonumber\\ 
		& \qquad+ {\rho _3}\left( {{\mathrm{tr}}\left( {{{\mathbf{W}}_c}} \right) - {{\left( {{\bf{u}}_c^{\left( {j } \right)}} \right)}^H}{{\mathbf{W}}_c}{\bf{u}}_c^{\left( {j } \right)}} \right) \nonumber\\ 
		& \qquad+ {\rho _3}\sum\limits_{k = 1}^K {\left( {{\mathrm{tr}}\left( {{{\mathbf{W}}_k}} \right) - {{\left( {{\bf{u}}_k^{\left( {j } \right)}} \right)}^H}{{\mathbf{W}}_k}{\bf{u}}_k^{\left( {j } \right)}} \right)}\nonumber\\ 
		&  \qquad+ {\rho _3}\left( { {\mathrm{tr}}\left( {{{{\mathbf{W}}_v}}} \right) - {{\left( {{\bf{u}}_v^{\left( {j } \right)}} \right)}^H}{{{{\mathbf{W}}_v}}}{\bf{u}}_v^{\left( {j } \right)}} \right)\\
		{\mathrm{s.t.}}\;
		&\sum\limits_{k = 1}^K {{c_k}}  \le R_{c,k}^1 - R_{c,k}^{2, {\rm{ub}}}, \forall k,\\
		&{c_k} + R_{p,k}^1 - R_{p,k}^{2, {\rm{ub}}} \ge {R_{\rm{U}}^{{\rm{th}}}}, \forall k,\\
		& {\rm (\ref{P1g})}, {\rm (\ref{P1i})}, ({\rm \ref{p03_b}}),		\nonumber
	\end{align}
\end{subequations}
where $\rho _3$ represents the penalty factor.

$\mathcal{P}_{3.1}$ is a standard convex problem that can be solved iteratively using the CVX toolbox.  The relevant algorithm is summarized as \textbf{Algorithm 3}.


The algorithm complexity analysis is as follows. 
$\mathcal{P}_{1.2}$  and $\mathcal{P}_{2.1}$ are composed of $K+2$ linear matrix inequality (LMI) constraints of size $N_t$ and $2KM+4K+3$ LMI constraints of size 1.
With the given convergence accuracy $\tau$ and the number of iterations ${J_{\max}}$, the computational complexity of algorithm 1 and algorithm 2 are expressed as  $O\left( {J_{\max}}{\sqrt {2KM + K{N_t}} {K^3}N_t^6} \log \left( {\frac{1}{\tau }} \right)\right)$.
$\mathcal{P}_{3.1}$ is composed by $K + 2$ LMI constraints of size $N_t$, ${4K + {N_t} + 2}$ LMI constraints of size 1, the computational complexity is $O\left( {{{J_{\max}}}\left( {{K^{3.5}}N_t^{6.5}} \right)} \log \left( {\frac{1}{\tau }} \right)\right)$.

