\begin{figure}[htbp]
	\centering
	\subfloat[The chain-like structure]{\includegraphics[width=0.35\columnwidth]{chain.png}\label{fig:chain}}
	\hspace{0.05\linewidth}
	\subfloat[The pendent structure]{\includegraphics[width=0.27\columnwidth]{pendent.png} \label{fig:pendent}}
	\caption{Worst(chain-like) and optimal-case(pendent) scenarios, the red region represents the algorithm-determined qubits and edges, the blue region represents the neighboring qubits and adjacent edges expanded through community expansion at k=1, and the gray region represents other areas in the coupling graph.}
	\label{fig:two-structure}
\end{figure}

Most superconducting quantum computers adopt 2D structures, and the grid coupling graph being a commonly used and highly connected configuration. To avoid underestimating the complexity, we analyze the worst-case scenario on this structure, represented by a chain-like physical qubit region (Figure \ref{fig:two-structure}\subref{fig:chain}), which maximizes the number of qubits and physical edges. The red region represents the algorithm-determined qubits and edges, with $n_q$ qubits. The number of adjacent qubits does not exceed $n_q (d_{max}-1)+1$. The total number of physical qubits in the final mapped graph is equal to the sum of the quantities mentioned above: 

\begin{equation}
	\label{equ:np-worst}
	n_P^{w}\leq n_qd_{max}+1.
\end{equation}

Given $n_E^w$ and $d_{max}$, the upper bound of $n_E^{w}$ can be calculated as follows:

\begin{equation}
	\label{equ:ne-worst}
	n_E^{w}\leq \frac{d_{max}}{2}(n_qd_{max}+1).
\end{equation}

In the optimal scenario, the algorithm identifies a pendent subgraph of the entire coupling graph, characterized by minimal adjacent qubits and edges. A representative configuration is illustrated in Figure \ref{fig:two-structure}\subref{fig:pendent}. With the number of qubits in the final region $n_P^b$, we have $n_P^b = n_q + 1$. The edge number in the final region satisfies:

\begin{equation}
	\label{equ:ne-best}
	n_E^{b}\leq \frac{n_qd_{max}}{2}+1.
\end{equation}

Since the final coupling graph is a subset of the overall graph, we can assume the node degrees are similar:

\begin{equation}
	\label{equ:dmax}
	d_{max}^b = d_{max}^w = d_{max}
\end{equation}

\begin{equation}
	\label{equ:dmin}
	d_{min}^b = d_{min}^w = d_{min}
\end{equation}

Using the qubit numbers and edge counts derived from both the optimal and worst-case scenarios, we can compute the complexity of the improved method relative to different baselines. For the enhanced Qsynth-v2, the number of variables in the optimal and worst cases,  $n_{vars,qs-v2}^b$, $n_{vars,qs-v2}^w$ are:

\begin{equation}
	\label{equ:1}
	n_{vars,qs-v2}^b\leq O(T(n_q(n_q+1)+n_{El}+n_G))
\end{equation}

\begin{equation}
	\label{equ:2}
	n_{vars,qs-v2}^w\leq O(T(n_q(n_qd_{max}+1)+n_{El}+n_G))
\end{equation}

For the enhanced Qsynth-v2, the number of clauses in the optimal and worst cases,  $n_{clause,qs-v2}^b$, $n_{clause,qs-v2}^w$ are calculated as (\ref{equ:3}) and (\ref{equ:4}).

\begin{align}
	\label{equ:3}
	n_{clause,qs\text{-}v2}^b &\leq O\Big(T\Big(n_q(n_q + 1) + n_q\Big(\frac{n_q d_{max}}{2} + 1\Big) \notag \\
	&\quad + n_{El}(n_q + 1)^2 + n_G\Big)\Big) \\
	\label{equ:4}
	n_{clause,qs\text{-}v2}^w &\leq O\Big(T\Big(n_q(n_q d_{max} + 1) + n_q\Big(\frac{d_{max}}{2}(n_q d_{max} + 1)\Big) \notag \\
	&\quad + n_{El}(n_q d_{max} + 1)^2 + n_G\Big)\Big)
\end{align}


For the enhanced TB-OLSQ2, the number of variables in the optimal and worst cases,  $n_{vars,tbolsq2}^b$, $n_{vars,tbolsq2}^w$ are:

\begin{equation}
	\label{equ:tbolsq2-numvar-best}
	n_{var,tbolsq2}^b \leq T(\frac{n_qd_{max}}{2}+n_q+1)+n_G
\end{equation}

\begin{equation}
	\label{equ:tbolsq2-numvar-worst}
	n_{var,tbolsq2}^b \leq T(\frac{d_{max}}{2}(n_qd_{max}+1)+n_q)+n_G
\end{equation}

For the enhanced TB-OLSQ2, the number of constraints in the optimal and worst cases,  $n_{cons,tbolsq2}^b$, $n_{cons,tbolsq2}^w$ are calculated as (\ref{equ:tbolsq2-numcons-best}) and (\ref{equ:tbolsq2-numcons-worst}).

\begin{align}
	\label{equ:tbolsq2-numcons-best}
	n_{cons,tbolsq2}^b &\leq O\Big(T\Big(n_q^2 + (n_G + d_{max} + n_q)\Big(\frac{n_q d_{max}}{2} + 1\Big) \notag \\
	&\quad + n_q(n_q + 1)\Big) + B\Big) \\
	\label{equ:tbolsq2-numcons-worst}
	n_{cons,tbolsq2}^w &\leq O\Big(T\Big(n_q^2 + (n_G + d_{max} + n_q)\Big(\frac{d_{max}(n_q d_{max} + 1)}{2}\Big) \notag \\
	&\quad + n_q(n_q d_{max} + 1)\Big) + B\Big)
\end{align}


We define the predicted average number of physical qubits after improvement, denoted as $n_P^{avg}$, as the mean of its upper and lower bounds. Similarly, the predicted average number of edges after improvement, denoted as $n_E^{avg}$, is defined as the mean of its corresponding bounds:

\begin{equation}
	\label{equ:nq-avg}
	n_P^{avg} = \frac{n_P^b + n_P^w}{2}\leq \frac{n_q(d_{max}+1)}{2}+1
\end{equation}

\begin{equation}
	\label{equ:ne-avg}
	n_E^{avg} = \frac{n_E^b + n_E^w}{2}
\end{equation}

Based on $n_P^{avg}$ and $n_E^{avg}$, we introduce two performance indicators:

\begin{enumerate}
	\item{\textbf{Average Qubit Pruning Ratio ($r_{aq}$):}
		\begin{equation}
			\label{equ:aqpr}
			r_{aq}=\frac{n_P}{n_P^{avg}}
		\end{equation}
	}
	\item{\textbf{Average Edge Pruning Ratio ($r_{ae}$):}
		\begin{equation}
			\label{equ:aepr}
			r_{ae}=\frac{n_E}{n_E^{avg}}
		\end{equation}
	}
\end{enumerate}


Using $r_{aq}$ and $r_{ae}$, the variable and clause counts for Qsynth-v2 after applying HAQA can be expressed as (\ref{equ:haqa-var-qsv2}) and (\ref{equ:haqa-clause-qsv2}), the variable and clause counts for TB-OLSQ2 after applying HAQA can be expressed as (\ref{equ:haqa-var-tbolsq2}) and (\ref{equ:haqa-cons-tbolsq2}).

\begin{equation}
	\begin{aligned}
		\label{equ:haqa-var-qsv2}
		n_{var,qs\text{-}v2}^{\text{HAQA}} &= O\Big(T\Big(\frac{n_q n_P}{r_{aq}} + n_{El} + n_G\Big)\Big)
	\end{aligned}
\end{equation}

\begin{equation}
	\begin{aligned}
		\label{equ:haqa-clause-qsv2}
		n_{clause,qs\text{-}v2}^{\text{HAQA}} = O\Big(T\Big(\frac{n_q n_P}{r_{aq}} + \frac{n_q n_E}{r_{ae}} \quad + \frac{n_{El} (n_P)^2}{r_{aq}^2} + n_G\Big)\Big)
	\end{aligned}
\end{equation}

\begin{equation}
	\begin{aligned}
		\label{equ:haqa-var-tbolsq2}
		n_{var,tbolsq2}^{\text{HAQA}} = T\Big(n_q + \frac{n_E}{r_{ae}}\Big) + n_G
	\end{aligned}
\end{equation}

\begin{equation}
	\begin{aligned}
		\label{equ:haqa-cons-tbolsq2}
		n_{cons,tbolsq2}^{\text{HAQA}} = O\Big(T\Big(n_q^2 + \frac{(n_G + d_{max} + n_q) n_E}{r_{ae}} \quad + \frac{n_q n_P}{r_{aq}}\Big) + B\Big)
	\end{aligned}
\end{equation}


Fundamentally, HAQA reduces the coupling graph-related parameters $n_E$ and $n_P$ to the order of logical qubit count $n_q$ in quantum circuits, thereby significantly improving the solution efficiency. Based on (\ref{equ:haqa-var-qsv2})-(\ref{equ:haqa-cons-tbolsq2}), $r_{aq}$ and $r_{ae}$ enable a comprehensive assessment of HAQA's impact on variable, clause, and constraint complexity. For Qsynth-v2, HAQA reduces the first term of variable complexity to a first-order polynomial level. Regarding clause complexity, the algorithm achieves a first-order polynomial reduction in the first and second term and a second-order polynomial reduction in the third term of the complexity formula. Similarly, for TB-OLSQ2, HAQA reduces the second term of variable complexity to a first-order polynomial level, and reduces the second and third terms of constraint complexity to a first-order polynomial level. The complexity analysis methodology presented here offers a generalizable framework for evaluating solver-based qubit mapping methods, applicable to various quantum architectures and mapping strategies. This analytical approach provides quantitative insights into the performance gains of optimization techniques, establishing a foundation for objective assessment and continuous improvement of qubit mapping methodologies in quantum compilation workflows.

Through theoretical analysis, HAQA demonstrates its effectiveness in addressing the key challenges in solver-based qubit mapping. The method establishes hardware-aware mapping regions through \textbf{Recursive Community Fusion}, with \textbf{Community Expansion} ensuring solution quality by adaptively incorporating auxiliary qubits. This approach reduces computational complexity to a polynomial level by controlling both variable expansion and constraint proliferation, while enabling quantum fidelity optimization through hardware-characteristic-based region selection. The subsequent numerical experiments provide further validation of the method's practical performance improvements.


\section{Experimental Investigation and Analysis}
\subsection{Experimental Setup}
\textbf{Metrics}:
We evaluate the efficiency and mapping performance of HAQA using the following metrics. First, solving efficiency is assessed by recording and comparing the runtime of various circuits across different qubit mapping methods. A time limit of 3600 seconds (1 hour) is set for each sample, with any method exceeding this limit considered a failure to solve, denoted as TO in experiment results.
Hellinger Fidelity is used as the primary performance indicator for the post-mapping circuit. Using Qiskit\cite{qiskit}, we simulate two scenarios:
\begin{enumerate}
	\item Noisy Circuit: The circuit after qubit mapping, simulated in an environment with two-qubit gate errors, using noise data provided by IBM.
	\item Ideal Circuit: The original circuit (prior to qubit mapping), simulated in a noise-free environment.
\end{enumerate}
In both scenarios, the circuits are executed 1024 times, and the resulting distributions are used to compute the Hellinger Fidelity.
Circuit depth and SWAP count are critical evaluation metrics for solver-based qubit mapping methods. Comparing these indicators allows us to determine whether HAQA retains the inherent advantages of the baseline mapping approaches.

\textbf{Baselines}:
Our baselines are two state-of-the-art solver-based qubit mapping methods: QSynth-v2 and TB-OLSQ2. QSynth-v2 focuses on parallel plans and domain-specific information for mapping circuits to platforms with over 100 qubits, while TB-OLSQ2 emphasizes scalability through concise SMT formulations and iterative optimizations.

\textbf{Benchmark Circuits}:
We utilize 25 quantum circuits from QSynth-v2\cite{Shaik2024} and TB-OLSQ2\cite{Lin2023}, with circuit depths ranging from 8 to 136. Due to memory constraints, we focus on quantum circuits with 3 to 10 qubits.

\textbf{Quantum Computer Setup}:
To evaluate the solution efficiency and quality of our method, we use hardware information (coupling graph and fidelity data) from IBM Eagle and IBM Heron for testing. IBM Eagle consists of 127 qubits, while IBM Heron has 133 qubits, both featuring a heavy hex lattice coupling graph. In terms of fidelity, IBM Heron has a slightly lower two-qubit gate error compared to IBM Eagle. The coupling graphs of IBM Eagle and IBM Heron is shown in Appendix \ref{apdix}.

\textbf{Hardware/Software Setup}:
All of our experiments were run on a Ryzen7 5700G CPU running at 3.8 GHz with 32 GB of RAM. HAQA was implemented using Networkx (v3.4.2). Due to different environment requirements for the two baselines, the experiments for TB-OLSQ2 and its application of the HAQA algorithm were conducted in Python 3.9, using the Z3 solver (v4.12.5.0) and Pysat (v0.1.8.dev12). The experiments for QSynth v2 and its application of HAQA were conducted in Python 3.10, using Qiskit (v0.46.3) and Pysat (v1.8.dev13).


%\subsection{Expansion Factor Determination}
\textbf{Expansion Factor Determination}:
As mentioned in subsection \ref{community-expansion}, the selection of expansion factor k directly impacts both the efficiency and success rate of the mapping process. A series of preliminary experiments were conducted to determine the optimal k value, with results presented in Table \ref{tab:determine-k}.

\begin{table}[htbp]
	\small
	\renewcommand{\arraystretch}{1}
