\begin{definition}\label{def:dualdeductions}
    Let $\Pi$ be an atomic deduction. Its dual $(\Pi)^{\mathbb{D}}$ is defined as follows:

    \begin{enumerate}
       \item ($\Pi$ has $0$ rule applications). If $\Pi$ consists in a single proof assumption with shape $p$ then $(\Pi)^{\mathbb{D}}$ consists in a single refutation assumption with shape $p$, and if $\Pi$ consists in a single refutation assumption with shape $p$ then $(\Pi)^{\mathbb{D}}$ consists in a single proof assumption with shape $p$.

       \medskip

       \item ($\Pi$ has $n > 0$ rule application). If $R+$ is the last rule applied in $\Pi$ and has the deductions $\Pi^{1}, \ldots, \Pi^n$ above its premises then $(R+)^{\mathbb{D}}$ is the last rule applied in $(\Pi)^{\mathbb{D}}$, which has the deductions $(\Pi^{1})^{\mathbb{D}}, \ldots, (\Pi^n)^{\mathbb{D}}$ above its premises (in the same order). If $R-$ is the last rule applied in $\Pi$ and has the deductions $\Pi^{1}, \ldots, \Pi^n$ above its premises then $(R-)^{\mathbb{D}}$ is the last rule applied in $(\Pi)^{\mathbb{D}}$, which has the deductions $(\Pi^{1})^{\mathbb{D}}, \ldots, (\Pi^n)^{\mathbb{D}}$ above its premises (in the same order).

        %\item ($\Pi$ has no rule applications). If $\Pi$ consists in a single proof assumption with shape $p$ then    Every proof assumption with shape $p$ is replaced by a refutation assumption with shape $p$ for every $p \in \At$, and every refutation assumption with shape $q$ is replaced by a proof assumption with shape $q$ for every $q \in \At$.

     %   \medskip

    %    \item Every application of a atomic rule is replaced by an application of its dual.
    \end{enumerate}
\end{definition}


\begin{definition}\label{def:dualbases}
    Let $\mathcal{B}$ be any atomic base. Then $(\mathcal{B})^{\mathbb{D}} = \{(R)^{\mathbb{D}} | R$ is an atomic rule of $\mathcal{B} \}$.
\end{definition}



From Definitions \ref{def:bilateralbase}, \ref{def:dualrules} and \ref{def:dualbases} it follows that the duals of rules are rules and the duals of bases are bases. We quickly show that the same holds for duals of deductions:


\begin{proposition} \label{prop:dualsdeductionsaredeductions}
If $\Pi$ is proof deduction with conclusion $p$ then $(\Pi)^{\mathbb{D}}$ is a refutation deduction with conclusion $p$, and if $\Pi$ is a refutation deduction with conclusion $p$ then $(\Pi)^{\mathbb{D}}$ is a proof deduction with conclusion $p$.
\end{proposition}

\begin{proof}
 The result is shown by induction on the length of $\Pi$. If $\Pi$ is of length $0$ the result is immediate by Definitions \ref{def:dualdeductions}, \ref{def:deducatomicproofs} and \ref{def:deducatomicrefs}. If $\Pi$ has length $n >0$, let $R*$ be the last rule applied in it and $\Pi^{1}, \ldots , \Pi^{n}$ be the deductions occurring above its premises, which have shape $p_{1}, \ldots, p_{n}$. By the induction hypothesis we have that $(\Pi^{1})^{\mathbb{D}}, \ldots , (\Pi^{n})^{\mathbb{D}}$ are deductions with conclusions $p_{1}, \ldots, p_{n}$.  Since by Definition \ref{def:dualrules} the rule $(R*)^{\mathbb{D}}$ has premises with the same shape $p_{1}, \ldots, p_{n}$ of the rule $R*$ but requires a proof deduction of the premise whenever $R*$ required a refutation deduction of the premise (and vice-versa), the application of $(R*)^{\mathbb{D}}$ with premises $(\Pi^{1})^{\mathbb{D}}, \ldots , (\Pi^{n})^{\mathbb{D}}$ yields a valid deduction, hence from the definition of $(R*)^{\mathbb{D}}$ and Definitions \ref{def:deducatomicproofs} and \ref{def:deducatomicrefs} if follows that if $\Pi$ was a proof deduction then $(\Pi)^{\mathbb{D}}$ is a refutation deduction and if $\Pi$ was a refutation deduction then $(\Pi)^{\mathbb{D}}$ is a proof deduction.


\end{proof}


