\begin{proposition} \label{remark}
    $((R*)^{\mathbb{D}} ) ^{\mathbb{D}} = R*$, $((\Pi)^{\mathbb{D}} ) ^{\mathbb{D}} = \Pi$ and $((\mathcal{B})^{\mathbb{D}} ) ^{\mathbb{D}} = \mathcal{B}$.
\end{proposition}


The involutive character of duality is immediate for rules an bases, and in the case of deductions (which is not required for the proofs that follow) it can be proved inductively though a straightforward adaptation of the proof of Proposition \ref{prop:dualsdeductionsaredeductions}.


\begin{corollary}\label{cor:maincorollary}
   $\Vdash^{*}_{\mathcal{B}} p$ iff $\Vdash^{(*)^{\mathbb{D}}}_{(\mathcal{B})^{\mathbb{D}}} p$ for any $p \in \At$.
\end{corollary}


\begin{proof}
    Assume $\Vdash^{+}_{\mathcal{B}} p$. By \ref{c:at+} we conclude that there must be an atomic proof $\Pi$ showing $\vdash^{+}_{\mathcal{B}} p$, hence by Lemma \ref{lemma:fundamentalatomicdualitylemma} we conclude that $(\Pi)^{\mathbb{D}}$ shows  $\vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} p$, whence $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} p$ by \ref{c:at-}. A similar argument shows that if $\Vdash^{-}_{\mathcal{B}} p$ then $\Vdash^{+}_{(\mathcal{B})^{\mathbb{D}}} p$. For the converse, assume $\Vdash^{+}_{(\mathcal{B})^{\mathbb{D}}} p$. By \ref{c:at+} we conclude that there must be an atomic proof $\Pi$ showing $\vdash^{+}_{(\mathcal{B})^{\mathbb{D}}} p$, hence by Lemma \ref{lemma:fundamentalatomicdualitylemma} we conclude that $(\Pi)^{\mathbb{D}}$ shows $\vdash^{-}_{((\mathcal{B})^{\mathbb{D}})^{\mathbb{D}}} p$. But  $((\mathcal{B})^{\mathbb{D}} ) ^{\mathbb{D}} = \mathcal{B}$ by Proposition \ref{remark}, hence by \ref{c:at-} we conclude $\Vdash^{-}_{\mathcal{B}} p$. A similar argument shows that if $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} p$ then $\Vdash^{+}_{\mathcal{B}} p$.
\end{proof}



\begin{definition} \label{def:dualityformulas}
    Given any formula $\chi$, its dual $(\chi)^{\mathbb{D}}$ is defined inductively as follows:

    \begin{enumerate}
        \item $(p)^{\mathbb{D}} = p$, for $p \in \At$;
        \item $(\bot)^{\mathbb{D}} = \top$;
        \item $(\top)^{\mathbb{D}} = \bot$;
        \item $(\phi \lor \psi)^{\mathbb{D}} = (\phi)^{\mathbb{D}} \land (\psi)^{\mathbb{D}}$;
         \item $(\phi \land \psi)^{\mathbb{D}} = (\phi)^{\mathbb{D}} \lor (\psi)^{\mathbb{D}}$;
          \item $(\phi \to \psi)^{\mathbb{D}} = (\psi)^{\mathbb{D}} \mapsfrom (\phi)^{\mathbb{D}}$;
          \item $(\phi \mapsfrom \psi)^{\mathbb{D}} = (\psi)^{\mathbb{D}} \to (\phi)^{\mathbb{D}}$;
    \end{enumerate}
\end{definition}




\begin{lemma}\label{lemma:involutivenessformulas}
    $((\chi)^{\mathbb{D}})^{\mathbb{D}} = \chi$.

    \begin{proof}
    We prove the result by induction on the complexity of $\chi$.

    \begin{enumerate}
        \item $(\chi = p$ for some $p \in \At)$. Since $(p)^{\mathbb{D}} =p$ we have $((p)^{\mathbb{D}})^{\mathbb{D}} = (p)^{\mathbb{D}}$ and $((p)^{\mathbb{D}})^{\mathbb{D}} = p$.

        \medskip

        \item $(\chi = \bot)$. Since $(\bot)^{\mathbb{D}} = \top$ we have $((\bot)^{\mathbb{D}})^{\mathbb{D}} = (\top)^{\mathbb{D}}$ and since $(\top)^{\mathbb{D}} = \bot$ we have $((\bot)^{\mathbb{D}})^{\mathbb{D}} = \bot$.

\medskip

 \item $(\chi = \top)$. Since $(\top)^{\mathbb{D}} = \bot$ we have $((\top)^{\mathbb{D}})^{\mathbb{D}} = (\bot)^{\mathbb{D}}$ and since $(\bot)^{\mathbb{D}} = \top$ we have $((\top)^{\mathbb{D}})^{\mathbb{D}} = \top$.

 \medskip

 \item $(\chi = \phi \lor \psi)$. Since $(\phi \lor \psi)^{\mathbb{D}} = (\phi)^{\mathbb{D}} \land (\psi)^{\mathbb{D}}$ we have $((\phi \lor \psi)^{\mathbb{D}})^{\mathbb{D}} = ((\phi)^{\mathbb{D}} \land (\psi)^{\mathbb{D}})^{\mathbb{D}}$. Since $((\phi)^{\mathbb{D}} \land (\psi)^{\mathbb{D}})^{\mathbb{D}} = ((\phi)^{\mathbb{D}})^{\mathbb{D}} \lor ((\psi)^{\mathbb{D}})^{\mathbb{D}}$ and the induction hypothesis yields $((\phi)^{\mathbb{D}})^{\mathbb{D}} \lor ((\psi)^{\mathbb{D}})^{\mathbb{D}} = \phi \lor \psi$ we conclude $((\phi \lor \psi)^{\mathbb{D}})^{\mathbb{D}} = \phi \lor \psi$.


 \medskip

 \item $(\chi = \phi \land \psi)$. Since $(\phi \land \psi)^{\mathbb{D}} = (\phi)^{\mathbb{D}} \lor (\psi)^{\mathbb{D}}$ we have $((\phi \land \psi)^{\mathbb{D}})^{\mathbb{D}} = ((\phi)^{\mathbb{D}} \lor (\psi)^{\mathbb{D}})^{\mathbb{D}}$. Since $((\phi)^{\mathbb{D}} \lor (\psi)^{\mathbb{D}})^{\mathbb{D}} = ((\phi)^{\mathbb{D}})^{\mathbb{D}} \land ((\psi)^{\mathbb{D}})^{\mathbb{D}}$ and the induction hypothesis yields $((\phi)^{\mathbb{D}})^{\mathbb{D}} \land ((\psi)^{\mathbb{D}})^{\mathbb{D}} = \phi \land \psi$ we conclude $((\phi \land \psi)^{\mathbb{D}})^{\mathbb{D}} = \phi \land \psi$.

 \medskip

  \item $(\chi = \phi \to \psi)$. Since $(\phi \to \psi)^{\mathbb{D}} = (\psi)^{\mathbb{D}} \mapsfrom (\phi)^{\mathbb{D}}$ we have $((\phi \to \psi)^{\mathbb{D}})^{\mathbb{D}} = ((\psi)^{\mathbb{D}} \mapsfrom (\phi)^{\mathbb{D}})^{\mathbb{D}}$. Since $((\psi)^{\mathbb{D}} \mapsfrom (\phi)^{\mathbb{D}})^{\mathbb{D}} = ((\phi)^{\mathbb{D}})^{\mathbb{D}} \to ((\psi)^{\mathbb{D}})^{\mathbb{D}}$ and the induction hypothesis yields $((\phi)^{\mathbb{D}})^{\mathbb{D}} \to ((\psi)^{\mathbb{D}})^{\mathbb{D}} = \phi \to \psi$ we conclude $((\phi \to \psi)^{\mathbb{D}})^{\mathbb{D}} = \phi \to \psi$.


   \medskip

  \item $(\chi = \phi \mapsfrom \psi)$. Since $(\phi \mapsfrom \psi)^{\mathbb{D}} = (\psi)^{\mathbb{D}} \to (\phi)^{\mathbb{D}}$ we have $((\phi \mapsfrom \psi)^{\mathbb{D}})^{\mathbb{D}} = ((\psi)^{\mathbb{D}} \to (\phi)^{\mathbb{D}})^{\mathbb{D}}$. Since $((\psi)^{\mathbb{D}} \to (\phi)^{\mathbb{D}})^{\mathbb{D}} = ((\phi)^{\mathbb{D}})^{\mathbb{D}} \mapsfrom ((\psi)^{\mathbb{D}})^{\mathbb{D}}$ and the induction hypothesis yields $((\phi)^{\mathbb{D}})^{\mathbb{D}} \mapsfrom ((\psi)^{\mathbb{D}})^{\mathbb{D}} = \phi \mapsfrom \psi$ we conclude $((\phi \mapsfrom \psi)^{\mathbb{D}})^{\mathbb{D}} = \phi \mapsfrom \psi$.



    \end{enumerate}
    \end{proof}
\end{lemma}


\begin{lemma}\label{lemma:baseinversion}
For any $\mathcal{B}$, if $\mathcal{C} \supseteq (\mathcal{B})^{\mathbb{D}}$ then $(\mathcal{C})^{\mathbb{D}} \supseteq \mathcal{B}$.
\end{lemma}

\begin{proof}
    Pick any $\mathcal{B}$ and any $\mathcal{C} \supseteq (\mathcal{B})^{\mathbb{D}}$. By Definition \ref{def:dualbases} we conclude that, for any rule $R$, $R \in \mathcal{B}$ implies $(R)^{\mathbb{D}} \in (\mathcal{B})^{\mathbb{D}}$, and since  $\mathcal{C} \supseteq (\mathcal{B})^{\mathbb{D}}$ by the definition of extensions also $(R)^{\mathbb{D}} \in \mathcal{C}$. By Definition \ref{def:dualbases} we also conclude that, for any $R$, $R \in \mathcal{C}$ implies $(R)^{\mathbb{D}} \in (\mathcal{C})^{\mathbb{D}}$. Now let $R$ be any rule with $R \in \mathcal{B}$. Then $(R)^{\mathbb{D}} \in \mathcal{C}$ and  $((R)^{\mathbb{D}})^{\mathbb{D}} \in (\mathcal{C})^{\mathbb{D}}$, so since $((R)^{\mathbb{D}})^{\mathbb{D}} = R$ we conclude $R \in (\mathcal{C})^{\mathbb{D}}$, whence by the definition of extensions and arbitrariness of $R$ we obtain  $(\mathcal{C})^{\mathbb{D}} \supseteq \mathcal{B}$.

\end{proof}

\begin{theorem}[Weak bilateral semantic harmony]\label{the:semanticharmony}
    $\Vdash^{*}_{\mathcal{B}} \chi$ iff $\Vdash^{(*)^{\mathbb{D}}}_{(\mathcal{B})^{\mathbb{D}}} (\chi)^{\mathbb{D}}$
\end{theorem}

\begin{proof}
    We prove the result by induction on the complexity of $\chi$.

    \begin{enumerate}
        \item $(\chi = p$ for $p \in \At)$.

        \medskip

    \noindent    The result follows immediately from Definition \ref{def:dualityformulas} and Corollary \ref{cor:maincorollary}.


 \medskip

   \item $(\chi = \top, * = +)$.

        \medskip


    \noindent    Immediate from \ref{c:top+}, \ref{c:bot-} and the fact that $(\top)^{\mathbb{D}} = \bot$.


     \medskip

   \item $(\chi = \bot, * = +)$.

        \medskip

\begin{enumerate}
    \item[$(\Rightarrow)$] Assume $\Vdash^{+}_{\mathcal{B}} \bot$. By \ref{c:bot+} we conclude $\Vdash^{+}_{\mathcal{B}} p$ and $\Vdash^{-}_{\mathcal{B}} p$ for all $p \in \At$. The induction hypothesis yields $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (p)^{\mathbb{D}}$ and $\Vdash^{+}_{(\mathcal{B})^{\mathbb{D}}} (p)^{\mathbb{D}}$ for all $p \in \At$. By Definition \ref{def:dualityformulas} we have $(p)^{\mathbb{D}} = p$ for every $p \in \At$, so $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} p$ and $\Vdash^{+}_{(\mathcal{B})^{\mathbb{D}}} p$ hold  for all $p \in \At$, whence $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} \top$ by \ref{c:top-}, thence since $(\bot)^{\mathbb{D}} = \top$ we conclude $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\bot)^{\mathbb{D}}$.

    \medskip

    \item [$(\Leftarrow)$] Assume $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\bot)^{\mathbb{D}}$, which is equivalent to $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} \top$ by Definition \ref{def:dualityformulas}. By \ref{c:top-} we conclude $\Vdash^{+}_{(\mathcal{B})^{\mathbb{D}}} p$ and $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} p$ for all $p \in \At$, so also $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (p)^{\mathbb{D}}$ and $\Vdash^{+}_{(\mathcal{B})^{\mathbb{D}}} (p)^{\mathbb{D}}$ for all $p \in \At$ by Definition \ref{def:dualityformulas}. The induction hypothesis yields $\Vdash^{+}_{\mathcal{B}} p$ and $\Vdash^{-}_{\mathcal{B}} p$ for all $p \in \At$, whence $\Vdash^{+}_{\mathcal{B}} \bot$ by \ref{c:top+}.
\end{enumerate}

\medskip

    \item $(\chi = \phi \lor \psi, * = +)$.

    \medskip


\begin{enumerate}
    \item[$(\Rightarrow)$]  Assume $\Vdash^{+}_{\mathcal{B}} \phi \lor \psi$. We have to show $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi)^{\mathbb{D}} \land (\psi)^{\mathbb{D}}$, which by Definition \ref{def:dualityformulas} is equivalent to $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi \lor \psi)^{\mathbb{D}}$.  Pick any $\mathcal{C} \supseteq (\mathcal{B})^{\mathbb{D}}$ such that $\emptyset ; (\phi)^{\mathbb{D}} \Vdash^{+}_{\mathcal{C}} p$ and $\emptyset ; (\psi)^{\mathbb{D}} \Vdash^{+}_{\mathcal{C}} p$ for some $p \in \At$.  First we show that $ \phi; \emptyset \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ and $\psi ; \emptyset \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ hold. Pick any $\mathcal{D} \supseteq (\mathcal{C})^{\mathbb{D}}$ such that $\Vdash^{+}_{\mathcal{D}} \phi$. The induction hypothesis yields $\Vdash^{-}_{(\mathcal{D})^{\mathbb{D}}} (\phi)^{\mathbb{D}}$. Since $\mathcal{D} \supseteq (\mathcal{C})^{\mathbb{D}}$ by Lemma \ref{lemma:baseinversion} we have $(\mathcal{D})^{\mathbb{D}} \supseteq \mathcal{C}$, hence since $\emptyset ; (\phi)^{\mathbb{D}} \Vdash^{+}_{\mathcal{C}} p$ and $\Vdash^{-}_{(\mathcal{D})^{\mathbb{D}}} (\phi)^{\mathbb{D}}$ we conclude  $ \Vdash^{+}_{(\mathcal{D})^{\mathbb{D}}} p$ by \ref{c:inf+}. The induction hypothesis yields  $ \Vdash^{-}_{((\mathcal{D})^{\mathbb{D}})^{\mathbb{D}}} (p)^{\mathbb{D}}$, which by Definition \ref{def:dualityformulas} and Proposition \ref{remark} is equivalent to $\Vdash^{-}_{\mathcal{D}} p$. Since $\mathcal{D}$ is an arbitrary extension of $(\mathcal{C})^{\mathbb{D}}$ with $\Vdash^{+}_{\mathcal{D}} \phi$ we conclude $ \phi; \emptyset \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ by \ref{c:inf-}. A similar argument yields $ \psi; \emptyset \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$. Since $\mathcal{C} \supseteq (\mathcal{B})^{\mathbb{D}}$ by Lemma \ref{lemma:baseinversion} we have $(\mathcal{C})^{\mathbb{D}} \supseteq \mathcal{B}$. Since $ \phi; \emptyset \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ and $ \psi; \emptyset \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ both hold and $\Vdash^{+}_{\mathcal{B}} \phi \lor \psi$ also holds we conclude $\Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ by \ref{c:or+}, hence $\Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} (p)^{\mathbb{D}}$ by Definition \ref{def:dualityformulas} and $\Vdash^{+}_{\mathcal{C}} p$ by the induction hypothesis. This means that, for any $\mathcal{C} \supseteq (\mathcal{B})^{\mathbb{D}}$ and any $p \in \At$, if $\emptyset ; (\phi)^{\mathbb{D}} \Vdash^{+}_{\mathcal{C}} p$ and $\emptyset ; (\psi)^{\mathbb{D}} \Vdash^{+}_{\mathcal{C}} p$ then $\Vdash^{+}_{C} p$. A similar argument shows that, for any $\mathcal{C} \supseteq (\mathcal{B})^{\mathbb{D}}$ and any $p \in \At$, if $\emptyset ; (\phi)^{\mathbb{D}} \Vdash^{-}_{\mathcal{C}} p$ and $\emptyset ; (\psi)^{\mathbb{D}} \Vdash^{-}_{\mathcal{C}} p$ then $\Vdash^{-}_{C} p$, thence by \ref{c:and-} and arbitrariness of $\mathcal{C}$ we finally conclude $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi)^{\mathbb{D}} \land (\psi)^{\mathbb{D}}$.

 \medskip


   \item[$(\Rightarrow)$]  Assume $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi \lor \psi)^{\mathbb{D}}$. By Definition \ref{def:dualityformulas} we conclude $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi)^{\mathbb{D}} \land (\psi)^{\mathbb{D}}$, and we have to show $\Vdash^{+}_{\mathcal{B}} \phi \lor \psi$. Pick any $\mathcal{C} \supseteq \mathcal{B}$ such that $\phi ; \emptyset \Vdash^{+}_{\mathcal{C}} p$ and $\psi; \emptyset \Vdash^{+}_{\mathcal{C}} p$ for some $p \in \At$. First we show that $\emptyset ; (\phi)^{\mathbb{D}} \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ and $\emptyset ; (\psi)^{\mathbb{D}} \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ hold. Pick any $\mathcal{D} \supseteq (\mathcal{C})^{\mathbb{D}}$ such that $\Vdash^{-}_{\mathcal{D}} (\phi)^{\mathbb{D}}$. The induction hypothesis yields $\Vdash^{+}_{(\mathcal{D})^{\mathbb{D}}} ((\phi)^{\mathbb{D}})^{\mathbb{D}}$, which by Lemma \ref{lemma:involutivenessformulas} is equivalent to $\Vdash^{+}_{(\mathcal{D})^{\mathbb{D}}} \phi$.  Since $\mathcal{D} \supseteq (\mathcal{C})^{\mathbb{D}}$ by Lemma \ref{lemma:baseinversion} we have $(\mathcal{D})^{\mathbb{D}} \supseteq \mathcal{C}$, hence since $\phi ; \emptyset \Vdash^{+}_{\mathcal{C}} p$ and $ \Vdash^{+}_{(\mathcal{D})^{\mathbb{D}}} \phi$  we conclude  $ \Vdash^{+}_{(\mathcal{D})^{\mathbb{D}}} p$ by \ref{c:inf+}.  The induction hypothesis yields  $ \Vdash^{-}_{((\mathcal{D})^{\mathbb{D}})^{\mathbb{D}}} (p)^{\mathbb{D}}$, which by Definition \ref{def:dualityformulas} and Proposition \ref{remark} is equivalent to $\Vdash^{-}_{\mathcal{D}} p$.   Since $\mathcal{D}$ is an arbitrary extension of $(\mathcal{C})^{\mathbb{D}}$ with $\Vdash^{-}_{\mathcal{D}} (\phi)^{\mathbb{D}}$ we conclude $ \emptyset; (\phi)^{\mathbb{D}} \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ by \ref{c:inf-}. A similar argument yields $ \emptyset; (\psi)^{\mathbb{D}} \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$. Since $\mathcal{C \supseteq \mathcal{B}}$ and $\mathcal{B} = ((\mathcal{B})^{\mathbb{D}})^{\mathbb{D}}$ we conclude $\mathcal{C} \supseteq ((\mathcal{B})^{\mathbb{D}})^{\mathbb{D}}$, hence by Lemma \ref{lemma:baseinversion} also $(\mathcal{C})^{\mathbb{D}} \supseteq (\mathcal{B})^{\mathbb{D}}$.  Since $\emptyset ; (\phi)^{\mathbb{D}} \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ and $\emptyset ; (\psi)^{\mathbb{D}} \Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ both hold and $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi)^{\mathbb{D}} \land (\psi)^{\mathbb{D}}$ holds we conclude $\Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} p$ by \ref{c:and-}, hence $\Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} (p)^{\mathbb{D}}$ by Definition \ref{def:dualityformulas} and $\Vdash^{+}_{\mathcal{C}} p$ by the induction hypothesis.  This means that, for any $\mathcal{C} \supseteq \mathcal{B}$ and any $p \in \At$, if $\phi ; \emptyset \Vdash^{+}_{\mathcal{C}} p$ and $\psi; \emptyset \Vdash^{+}_{\mathcal{C}} p$ then $\Vdash^{+}_{C} p$. A similar argument shows that, for any $\mathcal{C} \supseteq \mathcal{B}$ and any $p \in \At$, if $\phi ; \emptyset \Vdash^{-}_{\mathcal{C}} p$ and $\psi; \emptyset \Vdash^{-}_{\mathcal{C}} p$ then $\Vdash^{-}_{\mathcal{C}} p$, thence by \ref{c:or+} and arbitrariness of $\mathcal{C}$ we finally conclude $\Vdash^{+}_{\mathcal{B}} \phi \lor \psi$.
\end{enumerate}




\medskip

  \item $(\chi = \phi \land \psi, * = +)$.
  \medskip


\begin{enumerate}
 \item[$(\Rightarrow)$] Assume $\Vdash^{+}_{\mathcal{B}} \phi \land \psi$. Then by \ref{c:and+} we have $\Vdash^{+}_{\mathcal{B}} \phi$ and $\Vdash^{+}_{\mathcal{B}} \psi$. The induction hypothesis yields $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi)^{\mathbb{D}}$ and $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}}$, hence $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi)^{\mathbb{D}} \lor (\psi)^{\mathbb{D}}$ by \ref{c:or-}, whence $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi \land \psi)^{\mathbb{D}}$ by Definition \ref{def:dualityformulas}.


 \medskip

  \item[$(\Leftarrow)$] Assume $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi \land \psi)^{\mathbb{D}}$. Then $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi)^{\mathbb{D}} \lor (\psi)^{\mathbb{D}}$  by Definition \ref{def:dualityformulas}, hence $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi)^{\mathbb{D}}$ and $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}}$ by \ref{c:or-}. The induction hypothesis yields $\Vdash^{+}_{\mathcal{B}} \phi$ and $\Vdash^{+}_{\mathcal{B}} \psi$, thence by \ref{c:and+} we conclude $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi \land \psi)^{\mathbb{D}}$.

\end{enumerate}


\medskip

 \item $(\chi = \phi \to \psi, * = +)$.

    \medskip

\begin{enumerate}
    \item[$(\Rightarrow)$] Assume $\Vdash^{+}_{\mathcal{B}} \phi \to \psi$. We have to show  $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi \to \psi)^{\mathbb{D}}$, which is equivalent to $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}} \mapsfrom (\phi)^{\mathbb{D}}$ by Definition \ref{def:dualityformulas}. Pick any $\mathcal{C} \supseteq (\mathcal{B})^{\mathbb{D}}$ such that $\Vdash^{-}_{\mathcal{C}} (\phi)^{\mathbb{D}}$. The induction hypothesis yields $\Vdash^{+}_{(\mathcal{C})^{\mathbb{D}}} ((\phi)^{\mathbb{D}})^{\mathbb{D}}$, which by Lemma \ref{lemma:involutivenessformulas} is equivalent to $\Vdash^{+}_{(\mathcal{C})^{\mathbb{D}}} \phi$. Since $\mathcal{C} \supseteq (\mathcal{B})^{\mathbb{D}}$ by Lemma \ref{lemma:baseinversion} we conclude $(\mathcal{C})^{\mathbb{D}} \supseteq \mathcal{B}$. Since $\Vdash^{+}_{\mathcal{B}} \phi \to \psi$ we conclude $\phi; \emptyset \Vdash^{+}_{\mathcal{B}} \psi$ by \ref{c:to+}. Since $\phi; \emptyset \Vdash^{+}_{\mathcal{B}} \psi$, $(\mathcal{C})^{\mathbb{D}} \supseteq \mathcal{B}$ and $\Vdash^{+}_{(\mathcal{C})^{\mathbb{D}}} \phi$  we conclude $\Vdash^{+}_{(\mathcal{C})^{\mathbb{D}}} \psi$ by \ref{c:inf+}. The inductive hypothesis yields $\Vdash^{-}_{((\mathcal{C})^{\mathbb{D}})^{\mathbb{D}}} (\psi)^{\mathcal{D}}$, which by Proposition \ref{remark} is equivalent to $\Vdash^{-}_{\mathcal{C}} (\psi)^{\mathcal{D}}$. But then for every $\mathcal{C} \supseteq (\mathcal{B})^{\mathbb{D}}$ with $\Vdash^{-}_{\mathcal{C}} (\phi)^{\mathbb{D}}$ we have $\Vdash^{-}_{\mathcal{C}} (\psi)^{\mathbb{D}}$,  so we conclude $\emptyset ; (\phi)^{\mathbb{D}} \Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}}$ by \ref{c:inf-}, thence $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathcal{D}} \mapsfrom (\phi)^{\mathbb{D}}$ by \ref{c:mapsfrom-}.

    \medskip

    \item[$(\Leftarrow)$] Assume $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi \to \psi)^{\mathbb{D}}$, which is equivalent to $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}} \mapsfrom (\phi)^{\mathbb{D}}$ by Definition \ref{def:dualityformulas} . We have to show $\Vdash^{+}_{\mathcal{B}} \phi \to \psi$. Pick any $\mathcal{C} \supseteq \mathcal{B}$ such that $\Vdash^{+}_{\mathcal{C}} \phi$. The induction hypothesis yields $\Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} (\phi)^{\mathbb{D}}$. Since $\mathcal{C} \supseteq \mathcal{B}$ and $\mathcal{B} =((\mathcal{B})^{\mathbb{D}})^{\mathbb{D}}$ by Proposition \ref{remark}, we have $\mathcal{C} \supseteq ((\mathcal{B})^{\mathbb{D}})^{\mathbb{D}}$, hence $(\mathcal{C})^{\mathbb{D}} \supseteq (\mathcal{B})^{\mathbb{D}}$ by Lemma \ref{lemma:baseinversion}. Since $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}} \mapsfrom (\phi)^{\mathbb{D}}$ we conclude $\emptyset ;(\phi)^{\mathbb{D}} \Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}}$ by \ref{c:mapsfrom-}. Since $\emptyset ;(\phi)^{\mathbb{D}} \Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}}$, $(\mathcal{C})^{\mathbb{D}} \supseteq (\mathcal{B})^{\mathbb{D}}$ and $\Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} (\phi)^{\mathbb{D}}$ we conclude $\Vdash^{-}_{(\mathcal{C})^{\mathbb{D}}} (\psi)^{\mathbb{D}}$ by \ref{c:inf-}. The inductive hypothesis yields $\Vdash^{+}_{((\mathcal{C})^{\mathbb{D}})^{\mathbb{D}}} ((\psi)^{\mathbb{D}})^{\mathbb{D}}$, which by Proposition \ref{remark} and Lemma \ref{lemma:involutivenessformulas} is equivalent to $\Vdash^{+}_{\mathcal{C}} \psi$. But then for every $\mathcal{C} \supseteq \mathcal{B}$ with $\Vdash^{+}_{\mathcal{C}} \phi$ we have $\Vdash^{+}_{\mathcal{C}} \psi$, hence we conclude $\phi ; \emptyset \Vdash^{+}_{\mathcal{B}} \psi$ by \ref{c:inf-}, thence $\Vdash^{+}_{\mathcal{B}} \phi \to \psi$ by \ref{c:to+}.
\end{enumerate}



\medskip

  \item $(\chi = \phi \mapsfrom \psi, * = +)$.
  \medskip


\begin{enumerate}
 \item[$(\Rightarrow)$] Assume $\Vdash^{+}_{\mathcal{B}} \phi \mapsfrom \psi$. Then by \ref{c:mapsfrom+} we have $\Vdash^{+}_{\mathcal{B}} \phi$ and $\Vdash^{-}_{\mathcal{B}} \psi$. The induction hypothesis yields $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi)^{\mathbb{D}}$ and $\Vdash^{+}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}}$, hence $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}} \to (\phi)^{\mathbb{D}}$ by \ref{c:to-}, whence $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi \to \psi)^{\mathbb{D}}$ by Definition \ref{def:dualityformulas}.


 \medskip

  \item[$(\Leftarrow)$] Assume $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi \mapsfrom \psi)^{\mathbb{D}}$. Then $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}} \to (\phi)^{\mathbb{D}}$  by Definition \ref{def:dualityformulas}, hence $\Vdash^{+}_{(\mathcal{B})^{\mathbb{D}}} (\psi)^{\mathbb{D}}$ and $\Vdash^{-}_{(\mathcal{B})^{\mathbb{D}}} (\phi)^{\mathbb{D}}$ by \ref{c:to-}. The induction hypothesis yields $\Vdash^{+}_{\mathcal{B}} \phi$ and $\Vdash^{-}_{\mathcal{B}} \psi$, thence by \ref{c:mapsfrom+} we conclude $\Vdash^{+}_{\mathcal{B}} \phi \mapsfrom \psi$.

\end{enumerate}


\medskip

\item The inductive steps for $(\chi = \bot, *= -)$, $(\chi = \top, *= -)$, $(\chi = \phi \lor \psi, * = -)$, $(\chi = \phi \land \psi, * = -)$, $(\chi = \phi \to \psi, * = -)$ and $(\chi = \phi \mapsfrom \psi, * = -)$  are symmetrical with the ones for  $(\chi = \top, *= +)$, $(\chi = \bot, *= +)$, $(\chi = \phi \land \psi, * = +)$, $(\chi = \phi \lor \psi, * = +)$, $(\chi = \phi \mapsfrom \psi, * = +)$ and $(\chi = \phi \to \psi, * = +)$, respectively, so their proofs are omited. 
   \end{enumerate}




\end{proof}




\begin{definition}\label{def:dualitysets} 
  For any set $\Gamma$ of formulas we define  $(\Gamma)^{\mathbb{D}} = \{(\chi)^{\mathbb{D}} | \chi \in \Gamma \}$.


  %Notice that by Lemma \ref{lemma:involutivenessformulas}, $((\Gamma)^\mathbb{D})^{\mathbb{D}} = \Gamma$.
\end{definition}



\begin{corollary}[Strong bilateral semantic harmony]\label{cor:strongharmony}
    $\Gamma ; \Delta \Vdash^{*}_{\mathcal{B}} \chi$ iff $(\Delta)^{\mathbb{D}}; (\Gamma)^{\mathbb{D}} \Vdash^{(*)^{\mathbb{D}}}_{(\mathcal{B})^{\mathbb{D}}} (\chi)^{\mathbb{D}}$.
\end{corollary}


\begin{proof}
    For $\Gamma \cup \Delta$ empty the result follows from Theorem \ref{the:semanticharmony}. For non-empty $\Gamma \cup \Delta$, assume  $\Gamma ; \Delta \Vdash^{*}_{\mathcal{B}} \chi$. Pick any extension $\mathcal{C}$ of $(\mathcal{B})^{\mathbb{D}}$ with $\Vdash^{+}_{C} (\psi)^{\mathbb{D}}$ for all $(\psi)^{\mathbb{D}} \in (\Delta)^{\mathbb{D}}$ and $\Vdash^{-}_{C} (\phi)^{\mathbb{D}}$ for all $(\phi)^{\mathbb{D}} \in (\Gamma)^{\mathbb{D}}$. Theorem \ref{the:semanticharmony} yields $\Vdash^{+}_{(C)^{\mathbb{D}}} ((\phi)^{\mathbb{D}})^{\mathbb{D}}$ and $\Vdash^{-}_{(C)^{\mathbb{D}}} ((\psi)^{\mathbb{D}})^{\mathbb{D}}$ for all $(\psi)^{\mathbb{D}} \in (\Delta)^{\mathbb{D}}$ and all $(\phi)^{\mathbb{D}} \in (\Gamma)^{\mathbb{D}}$, which by Lemma \ref{lemma:involutivenessformulas} and Definition \ref{def:dualitysets} means that $\Vdash^{+}_{(C)^{\mathbb{D}}} \phi$ holds for all $\phi \in \Gamma$ and $\Vdash^{-}_{(C)^{\mathbb{D}}} \psi$ holds for all $\psi \in \Delta$. Since $\mathcal{C} \supseteq (\mathcal{B})^{\mathbb{D}}$ we conclude $(\mathcal{C})^{\mathbb{D}} \supseteq \mathcal{B}$ by Lemma \ref{lemma:baseinversion}, hence since $\Gamma ; \Delta \Vdash^{*}_{\mathcal{B}} \chi$ and both $\Vdash^{+}_{(C)^{\mathbb{D}}} \phi$ holds for all $\phi \in \Gamma$ and $\Vdash^{-}_{(C)^{\mathbb{D}}} \psi$ hold for all $\psi \in \Delta$, by either \ref{c:inf+} or \ref{c:inf-} we conclude $\Vdash^{*}_{(\mathcal{C})^{\mathbb{D}}} \chi$. Theorem \ref{the:semanticharmony} thus yields $\Vdash^{(*)^{\mathbb{D}}}_{((\mathcal{C})^{\mathbb{D}})^{\mathbb{D}}} (\chi)^{\mathbb{D}}$, so by Proposition \ref{remark} we have $\Vdash^{(*)^{\mathbb{D}}}_{\mathcal{C}} (\chi)^{\mathbb{D}}$. Since $\mathcal{C}$ was an arbitrary extension of $(\mathcal{B})^{\mathbb{D}}$ with  $\Vdash^{+}_{C} (\psi)^{\mathbb{D}}$ for all $(\psi)^{\mathbb{D}} \in (\Delta)^{\mathbb{D}}$ and $\Vdash^{-}_{C} (\phi)^{\mathbb{D}}$ for all $(\phi)^{\mathbb{D}} \in (\Gamma)^{\mathbb{D}}$ (which are the totality of formulas in $(\Gamma)^{\mathbb{D}}$ and $(\Delta)^{\mathbb{D}}$ due to Definition \ref{def:dualitysets}) and we have shown $\Vdash^{(*)^{\mathbb{D}}}_{\mathcal{C}} (\chi)^{\mathbb{D}}$ we conclude $(\Delta)^{\mathbb{D}}; (\Gamma)^{\mathbb{D}} \Vdash^{(*)^{\mathbb{D}}}_{(\mathcal{B})^{\mathbb{D}}} (\chi)^{\mathbb{D}}$ by either \ref{c:inf+} or \ref{c:inf-}. For the  converse, assume $(\Delta)^{\mathbb{D}}; (\Gamma)^{\mathbb{D}} \Vdash^{(*)^{\mathbb{D}}}_{(\mathcal{B})^{\mathbb{D}}} (\chi)^{\mathbb{D}}$. Pick any $\mathcal{C} \supseteq \mathcal{B}$ with $\Vdash^{+}_{C} \phi$ for all $\phi \in \Gamma$ and $\Vdash^{-}_{\mathcal{C}} \psi$ for all $\psi \in \Delta$. Theorem \ref{the:semanticharmony} yields $\Vdash^{-}_{(C)^{\mathbb{D}}} (\phi)^{\mathbb{D}}$ for all $\phi \in \Gamma$ and $\Vdash^{+}_{(\mathcal{C})^{\mathbb{D}}} (\psi)^{\mathbb{D}}$ for all $\psi \in \Delta$. Since $\mathcal{C} \supseteq \mathcal{B}$ and $\mathcal{B} = ((\mathcal{B)^{\mathbb{D}}})^{\mathbb{D}}$ we have $\mathcal{C} \supseteq ((\mathcal{B)^{\mathbb{D}}})^{\mathbb{D}}$, so also $(\mathcal{C})^\mathbb{D} \supseteq (\mathcal{B)^{\mathbb{D}}}$ by Lemma \ref{lemma:baseinversion}. Since $(\Delta)^{\mathbb{D}}; (\Gamma)^{\mathbb{D}} \Vdash^{(*)^{\mathbb{D}}}_{(\mathcal{B})^{\mathbb{D}}} (\chi)^{\mathbb{D}}$, $(\mathcal{C})^\mathbb{D} \supseteq (\mathcal{B)^{\mathbb{D}}}$ and both $\Vdash^{-}_{(C)^{\mathbb{D}}} (\phi)^{\mathbb{D}}$ for all $\phi \in \Gamma$ and $\Vdash^{+}_{(\mathcal{C})^{\mathbb{D}}} (\psi)^{\mathbb{D}}$ for all $\psi \in \Delta$ (thus for the totality of formulas  $(\phi)^{\mathbb{D}}$ in $ (\Gamma)^{\mathbb{D}}$ and $(\psi)^{\mathbb{D}} $ in $ (\Delta)^{\mathbb{D}}$ by Definition \ref{def:dualitysets}) we conclude $\Vdash^{(*)^{\mathbb{D}}}_{\mathcal{(C)^{\mathbb{D}}}} (\chi)^{\mathbb{D}}$ by either \ref{c:inf+} or \ref{c:inf-}, whence Theorem \ref{the:semanticharmony} yields $\Vdash^{*}_{\mathcal{C}} \chi$. Since $\mathcal{C}$ is an arbitrary extension of $\mathcal{B}$ with $\Vdash^{+}_{C} \phi$ for all $\phi \in \Gamma$ and $\Vdash^{-}_{\mathcal{C}} \psi$ for all $\psi \in \Delta$ we finally conclude  $\Gamma ; \Delta \Vdash^{*}_{\mathcal{B}} \chi$ by either \ref{c:inf+} or \ref{c:inf-}.



