\def\act{\Gamma}
\begin{definition}[Active states]\label{Def:Sigma_t}
    For any time $t \geq 0$, we define the set of active states in the greedy policy at time $t$ as $
    \act_t: = \{w  | \start(w) \leq t \leq \endd(w) \} $. 
\end{definition}
Observe that $\act_t$ consists of all possible states that the greedy policy may  be in at time $t$ (if it has not already terminated). 
The following lemma is immediate from the definition of active states. For notational convenience, we use $V_w$ to denote $V(w)$ in the rest of this paper. 
\begin{lemma}\label{partition}
    For any time $t$, the sets $\{V_w : w\in \act_t\}$ are   disjoint and  
    $$\sum_{w\in \act_t}p(V_w) =\Pr(\alg \geq t)= a_t .$$
\end{lemma}

\begin{definition}[Score] \label{score}For any time $t$ and active state $w\in \act_t$, we define 
    $$
\mathrm{Score}(t,w) = \max_{e\in E} \frac{\Delta(e|w)}{c(e) ( V_w -1)} .
$$

Moreover, for any time $t$, define the random quantity 

$$\st_t =\left\{ \begin{array}{ll}
     0 & \mbox{if greedy terminates before time $t$} \\
     \mathrm{Score}(t,w) & \mbox{where $w\in \act_t$ is the state at time $t$ in greedy} 
\end{array} \right. . $$
\end{definition}
Note that the score is  a scaled version of the greedy criterion.  
Our main technical result is the following lower bound. 
%We will prove two key lemmas in the following. 


\begin{lemma}\label{lemma-lower bnd}
For any time $t$ and $L\ge 0$, we have  
$$
\E_{h^*\sim D }[\st_t] \geq   \frac{L}{2t} (a_t - o_{t/L}) . 
$$
\end{lemma}

Before proving this lemma, we introduce some intermediate results. Below, we fix time $t$ and $L$ as in the lemma.

\begin{definition}[Heavy part]\label{def:heavy part}
Fix a state $w\in \act_t$ and a query $e$. Let $B_w^e$ denote the part in $\{S_i(e,w):i\in R\}$ with the largest size. We call $B_w^e$ the heavy part of $V_w$ with respect to $e$; also define $J_w^e = V_w \setminus B_w^e$.
\end{definition}

\def\Stem(w){\mathsf{Stem}(w)}

In the following, we will associate an active state $w$ with a particular path $\Stem(w)$ in the optimal decision tree. We will use this association to argue that our greedy policy is competitive with the optimal policy.

\paragraph{Finding a path in the optimal tree.} Given an active state $w \in \act_t$, we construct a path $\Stem(w)$ in the optimal tree starting at the root as follows. At any node labeled with query $e$, we follow the branch corresponding to the heavy part $B_w^e$. This process continues as long as the total cost of queries on the path remains \emph{at most} $\frac{t}{L}$. With a slight abuse of notation, let $\Stem(w)$ denote the set of queries along this path. By construction, we have the total cost in $\Stem(w)$ is:
\begin{equation}\label{eq:I}
\sum_{e \in \Stem(w)} c(e) \leq \frac{t}{L}.
\end{equation}

\begin{lemma}\label{score low bnd}
For any state $w \in \act_t$ and $e \in \Stem(w)$, we have
$$
\frac{\Delta(e|w)}{V_w-1} \,\,\geq\,\, \frac{p(J_w^e)}{2 p(V_w)} \,+\, \frac{p(B_w^e)}{p(V_w)}\frac{J_w^e}{V_w-1}.
$$     
\end{lemma}
\begin{proof}
Fix $w\in \act_t$ and $e \in \Stem(w)$. Suppose that $e$ partitions $V_w$ into $q$ disjoint parts, i.e.,
$V_w = \bigcup_{i=1}^q S_i$. 
Without loss of generality, assume that $S_1$ has the largest size. So we have $B_w^e = S_1$ and $J_w^e = \bigcup_{i\geq2}S_i$. Then,
\begin{equation}\label{eq:half_V}
    V_w - S_i \stackrel{}{\geq} V_w - \frac{S_1 + S_i}{2} \stackrel{}{\geq} V_w - \frac{V_w}{2} = \frac{V_w}{2}, \quad \forall i \geq 2.
\end{equation}

Above, the first inequality follows because $S_1 \geq S_i$ (i.e., $S_1$ has the largest size). The second inequality follows because $S_1$ and $S_i$ are disjoint, which implies $S_1 + S_i \leq V_w$.
Now, we have

\begin{align}
\frac{\Delta(e|w)}{V_w-1} &\stackrel{}{=} \frac{1}{V_w-1}\sum_{ i=1}^q  \frac{p(S_i)}{p(V_w)}\left(V_w - S_i\right) \label{eq:a} \\
&= \frac{p(B_w^e)}{p(V_w)} \frac{V_w - S_1}{V_w-1} + \frac{1}{V_w-1}\sum_{i=2}^q  \frac{p(S_i)}{p(V_w)} \left(V_w - S_i\right) \nonumber \\
&\stackrel{}{\geq} \frac{p(B_w^e)}{p(V_w)} \frac{V_w - S_1}{V_w-1} + \frac{V_w}{2(V_w-1)} \sum_{i=2}^q  \frac{p(S_i)}{p(V_w)} \label{eq:b}  
 \stackrel{}{=} \frac{p(B_w^e)}{p(V_w)} \frac{J_w^e}{V_w-1} + \frac{p(J_w^e)}{2p(V_w)}. %\label{eq:c}
\end{align}
The equality in \eqref{eq:a} uses the definition of $\Delta(e|w)$ from Equation~\eqref{eq:delta def}. The inequality in \eqref{eq:b} follows from Equation~\eqref{eq:half_V}. Finally, the equality in \eqref{eq:b} is due to the definition $J_w^e = \bigcup_{i\geq2}S_i = V_w \setminus S_1$. %, which implies $V_w - S_1 = J_w^e$ and $\sum\limits_{2 \leq i\leq q}p(S_i) \geq p(J_w^e)$.
\end{proof}

\begin{definition}\label{terminalstate}
For any active state $w\in\act_t$, we define:
\begin{equation}\label{V and I} 
  I_w := V_w \backslash \bigcup_{e \in \Stem(w)} J_w^e.
\end{equation}
 We further partition the  active states $\act_t$ based on this. Define 
    \begin{equation}\label{def:pos act}
            \act_t^-  := \{ w \in \act_t | \, |I_w| \leq 1 \} \quad \text{and} \quad \act_t^+ := \act_t \backslash \act_t^- = \{w \in \act_t | \, |I_w| \geq 2 \}. 
    \end{equation}

\end{definition}


In other words, $I_w\sse V_w$ are those hypotheses in $V_w$ that are compatible at the end of $\Stem(w)$ in the optimal policy. Moreover, if $w\in \act_t^+$ then the optimal policy does {\em not} identify any $h\in I_w$ before time $\frac{t}{L}$. (For $w\in \act_t^-$ there is a unique hypothesis  $h\in I_w$ which means that the optimal policy   identifies $h$  before time $\frac{t}{L}$.)  
 In particular, only the hypotheses corresponding to $\act_t^+$ help us establish a lower bound on the optimal cost. We formalize this in the following lemma.


\begin{lemma}\label{lemma:I_w}
For any $w \in \act_t^+$, we have
$$\sum_{w \in \act_t^+}p(I_w) \leq \Pr\left[\opt \geq \frac{t}{L}\right] = o_{t/L}.$$
\end{lemma}

\begin{proof}
We can bound the sum of probabilities as follows:
$$
\sum_{w \in \act_t^+}p(I_w) \stackrel{}{=} p\left(\bigcup_{w \in \act_t^+} I_w\right) \stackrel{}{\leq} \Pr\left(\opt \geq \frac{t}{L}\right) = o_{\frac{t}{L}}.
$$ 

For the first equality, note that the sets $\{I_w\}_{w \in \act_t}$ are disjoint since $I_w \subseteq V_w$ for each $w \in \act_t$ (Definition~\ref{terminalstate}) and the sets $\{V_w\}_{w \in \act_t}$ are disjoint by Lemma~\ref{partition}. For the inequality, we use that none of the hypotheses in $\bigcup_{w\in \act^+_t} I_w$ is identified before time $t/L$ in the optimal policy.  
\end{proof} 
%add words

\begin{lemma}\label{keylemma 1}
For any time $t$, 
$$
\mathrm{Score}(t,w) \geq
\begin{cases}
\frac{L}{2t}\frac{p(V_w) - p(I_w)}{p(V_w)} & \text{if } w \in \act_t^+ \\
\frac{L}{2t} & \text{if } w \in \act_t^- 
\end{cases} .
$$
\end{lemma}

\begin{proof}  

Recall that $\mathrm{Score}(t,w) = \max\limits_{e\in E}\frac{\Delta(e|w)}{(V_w-1) c(e)}$ from the greedy criterion. We will prove the lower bound for the $\mathrm{Score}(t,w)$ by an averaging argument. That is 
$$
\mathrm{Score}(t,w) \geq \max_{e\in \Stem(w)} \frac{\Delta(e|w)}{c(e) (V_w-1) } \ge   \frac{1}{\sum\limits_{e\in \Stem(w)} c(e)}\sum_{e\in \Stem(w)}\frac{\Delta(e|w)}{V_w-1} \geq \frac{L}{t}\sum_{e\in \Stem(w)}\frac{\Delta(e|w)}{V_w-1}.
$$
The last inequality uses equation~\eqref{eq:I}.
It now suffices to show that 
\begin{equation}\label{eq:4}
\sum_{e\in \Stem(w)}\frac{\Delta(e|w)}{V_w-1} \geq
\begin{cases}
\frac{p(V_w) - p(I_w)}{2p(V_w)} & \text{if } w \in \act_t^+ \\
\frac{1}{2} & \text{if } w \in \act_t^-
\end{cases}.     
\end{equation}
We have
\begin{align}
\sum_{e\in \Stem(w)}\frac{\Delta(e|w)}{V_w-1} &\stackrel{}{\geq} \sum_{e \in \Stem(w)} \left(\frac{p(J_w^e)}{2 p(V_w)} + \frac{p(B_w^e)}{p(V_w)}\frac{J_w^e}{V_w-1}\right) \label{eq:1}\\
&\stackrel{}{\geq} \frac{p(V_w) - p(I_w)}{2p(V_w)} + \sum_{e \in \Stem(w)}\frac{p(B_w^e)}{p(V_w)} \frac{J_w^e}{V_w-1} \label{eq:2} \\
&\stackrel{}{\geq} \frac{p(V_w) - p(I_w)}{2p(V_w)} + \sum_{e \in \Stem(w)}\frac{p(I_w)}{p(V_w)} \frac{J_w^e}{V_w-1} := RHS 
 \label{eq:3}.
\end{align}

The inequality in \eqref{eq:1} follows from Lemma~\ref{score low bnd}. For the inequality in \eqref{eq:2}, we use the definition of $I_w$, see~\eqref{V and I}, which implies that
$$
\sum_{e \in \Stem(w)} p(J_w^e) \geq p(V_w) - p(I_w).
$$ 
The inequality in \eqref{eq:3} holds because $I_w \subseteq B_w^e$ for any $w \in \act_t$ and $e \in \Stem(w)$. %, which means $p(B_w^e) \geq p(I_w)$.

For any $w \in \act_t^-$, we have $|I_w| \leq 1$, which implies $\sum\limits_{e \in \Stem(w)} J_w^e \geq V_w - 1$. Hence, 
$$
RHS = \frac{p(V_w) - p(I_w)}{2p(V_w)} + \frac{p(I_w)}{p(V_w)} \sum_{e \in \Stem(w)} \frac{J_w^e}{V_w-1} \geq \frac{p(V_w) - p(I_w)}{2p(V_w)} + \frac{p(I_w)}{p(V_w)}  \geq \frac{1}{2},\quad \forall w\in \act^-_t.
$$

For any $w \in \act^+$, we only keep the first term in \eqref{eq:3}. This proves \eqref{eq:4} and hence completes the proof of the lemma.
\end{proof}



\begin{proof}[Proof of Lemma~\ref{lemma-lower bnd}]
We are now ready to provide a lower bound for $\mathop{\mathbb{E}}\limits_{h^*\sim D}[\st_t]$. Recall that $\st_t$ is a random variable from Definition~\ref{score}. We have:
\begin{align}
\mathop{\mathbb{E}}_{h^*\sim D}[\st_t] &= \Pr[ \alg < t] \cdot 0 + \Pr[\alg \geq t]\cdot  \mathop{\mathbb{E}} \left[\st_t| \alg \geq t \right] \nonumber \\
&= \Pr[\alg \geq t] \sum_{w \in \act_t} \mathrm{Score}(t,w)\frac{\Pr[\text{\{$w$ observed at $t$\} $\cap$ \{$\alg \geq t$\}}]}{\Pr[ \alg \geq t]} \nonumber \\
&= \sum_{w \in \act_t} \mathrm{Score}(t,w) \Pr[\text{$w$ observed at $t$}]  = \sum_{w \in \act_t} \mathrm{Score}(t,w)\cdot p(V_w) \label{eq:reduce to act}.
\end{align}

The first equality in $\eqref{eq:reduce to act}$ holds because if state $w$ is observed  at time $t$ then the greedy algorithm won't terminate before time $t$, i.e., $\text{\{$w$ observed at $t$\}} \subseteq \{\alg \geq t\}$. For the last equality, we observe that $p(V_w)$ is exactly the probability that $w$ is observed at time $t$. 
Now,
\begin{align}
\sum_{w \in \act_t} \mathrm{Score}(t,w)p(V_w) &= \sum_{w \in \act_t^+} \mathrm{Score}(t,w) p(V_w) + \sum_{w \in \act_t^-} \mathrm{Score}(t,w) p(V_w) \nonumber \\
&\stackrel{}{\geq} \frac{L}{2t} \left(\sum_{w \in \act_t^+} \frac{p(V_w) - p(I_w)}{p(V_w)} \cdot p(V_w) + \sum_{w \in \act_t^-}p(V_w)\right) \label{eq:5} \\
&= \frac{L}{2t} \left(\sum_{w \in \act_t^+} \left(p(V_w) - p(I_w)\right) + \sum_{w \in \act_t^-}p(V_w)\right) \nonumber \\
&= \frac{L}{2t} \left(\sum_{w \in \act_t} p(V_w) - \sum_{w \in \act_t^+} p(I_w) \right) \quad  \stackrel{}{\geq} \quad  \frac{L}{2t} (a_t - o_{\frac{t}{L}}) . \label{eq:6} 
\end{align}
The inequality in \eqref{eq:5} is by  Lemma~\ref{keylemma 1}. For the inequality in \eqref{eq:6}, we use two results:
  $\sum\limits_{w \in \act_t} p(V_w) = a_t$ by Lemma~\ref{partition} and   $\sum\limits_{w \in \act_t^+} p(I_w) \leq o_{t/L}$ by  Lemma~\ref{lemma:I_w}. %This completes the proof of the lower bound. 
\end{proof}

We now turn to proving an upper bound on the score, which is almost identical to a similar lemma in \cite{althani2024}.
We provide the proof for completeness. 
\begin{lemma}\label{lem:upper-bnd}
For any $t \geq 0$, we have the upper bound
$$
\int_{z\geq t} \quad \mathop{\mathbb{E}}_{h^* \sim D}[\st_z] dz \leq (1+ \ln m) a_t.
$$
\end{lemma}

\begin{proof}
For any state $w$, query $e$  and hypothesis $h\in H$, let $\Delta_h(e|w)=V_w-S_i(e,w)$ where $i=e(h)$ is the response of $e$ under $h$.  So, $\Delta(e|w)=\E_{h\sim D|w}[\Delta_h(e|w)]$.
We now express  the score in terms of the true hypothesis. For any time $z$ and hypothesis $h$, define
$$G_h(z) :=\left\{ \begin{array}{ll}
     0 & \mbox{if greedy terminates before time $z$ when true hypothesis is $h$} \\
     \frac{\Delta_h(e|w)}{c(e)(V_w-1)} & \substack{  \mbox{where $w\in \act_z$ is the state at time $z$ in greedy}\\ \mbox{ when true hypothesis is $h$, and $e$ is the query at state $w$} }  
\end{array} \right. . $$
Using Definition~\ref{score}, we obtain  $\E[\st_z] = \E_{h\sim D}[G_h(z)]$ for any time $z$. Hence,
\begin{align}
&\int_{z\geq t}  \E[\st_z] dz  = \int_{z\ge t} \E_{h^* }[ G_{h^*}(z)] dz = \E_{h^*}\left[\int_{z\ge t} G_{h^*}(z) dz\right] \notag\\
&= \Pr[\mbox{greedy terminates after time $t$}] \cdot \E_{h^*}\left[\int_{z\ge t} G_{h^*}(z) dz \big| \mbox{greedy terminates after time $t$}\right].\label{eq:score-ub-cases}
\end{align}
The equality in \eqref{eq:score-ub-cases} uses the fact that if greedy terminates before $t$ then $G_{h*}(z)=0$ for all $z\ge t$. 

  We will now show that 
  \begin{equation}\label{eq:harmonic}
\int_{z\ge 0} G_{h}(z) dz \le 1+\ln m,\quad \forall h\in H.      
  \end{equation}
  Fix any $h\in H$. 
Let $e_1, \dots, e_n$ be the query sequence in the greedy tree conditioned on $h^* = h$. For each $i\in [n]$   let $w_i$ be the state at which query $e_i$ is performed; let  $w_{n+1}$ be the state associated with the leaf node for $h$. The time interval during which state $w_i$ is active is $[\sum_{j=1}^{i-1} c(e_j) , \sum_{j=1}^{i} c(e_j)]$; note that the width of this interval  is $c(e_i)$. Moreover, $G_h(z)$ is a step function w.r.t.  $z$, and 
$$\int_{z\ge 0} G_{h}(z) dz =\sum_{i=1}^n c(e_i)\cdot  \frac{\Delta_h(e_i|w_i)}{c(e_i)(V_{w_i}-1)}  =  \sum_{i=1}^n \frac{V_{w_i} - V_{w_{i+1}}}{V_{w_i}-1}  \leq  1 + \ln m.
$$
To justify the last inequality, we first observe that $\{V_{w_i}\}_{i=1}^{n+1}$ is a strictly decreasing sequence of integers with values in $[1,m]$. We then use the following fact.
\begin{quote}
If  $\{a_i\}_{i=1}^{n+1}$ is a strictly decreasing sequence of integers with values in $[1, m]$ then: 
\[
\sum_{i=1}^{n} \frac{a_i - a_{i+1}}{a_i - 1} \le 1+ \ln m.
\]
\end{quote}
The proof is now complete by combining \eqref{eq:score-ub-cases} and \eqref{eq:harmonic}.
\end{proof}


We are ready to prove our main theorem.
\begin{proof}[Proof of Theorem~\ref{thm:main}]
Recall $\E\left[\alg\right] =\int_0^{\infty} a_t dt $ and $\E\left[\opt\right]=\int_0^{\infty} o_t dt$ from Equation~\eqref{eq:ALG and at}. So,
$$
\begin{aligned}
   & (1+ \ln m)\E\left[\alg\right]\stackrel{\text{(Eq.~\eqref{eq:ALG and at})}}{=} (1 + \ln m ) \int_0^{\infty} a_t dt \stackrel{\text{(Lemma~\ref{lem:upper-bnd})}}{\geq} \int_0^{\infty}\int_{z\geq t} \E_{h^* \sim D}[\st_z] dzdt \\
   &\stackrel{(\text{Lemma~\ref{lemma-lower bnd}})}{\geq} \int_0^{\infty} \int_{z\geq t} \frac{L}{2z} (a_z - o_{\frac{z}{L}}) dz dt  \stackrel{(\text{Fubini's Theorem})}{=}  \int_0^{\infty} \int_0^z  \frac{L}{2z} (a_z - o_{\frac{z}{L}}) dt dz \\
   &= \int_0^{\infty} \frac{L}{2} (a_z -o_{\frac{z}{L}} )dz \stackrel{(\text{Equation~\eqref{eq:ALG and at}})}{=}  \frac{L}{2} (\E\left[\alg\right] -  L \cdot \E\left[\opt\right]).
\end{aligned}
$$
Now, choosing $L = 4\cdot(1+\ln m)$, we get  $8 \cdot (1+\ln m) \E\left[\opt\right] \geq \E\left[\alg\right]$.
\end{proof}



