\subsection{The Insulated Wall Panel Scenario}
\label{scenario}

\begin{figure*}[ht!]
  \centering 
  \includegraphics[scale=0.55, trim=4cm 0.95cm 2cm 11cm, clip]{IWP_EoL_Scenario-2.pdf} 
  \caption{IWP Scenario}
  \vspace{-3ex}
