	\begin{theorem}[adapted from Theorems 1 and 4 and Lemmas 33 and 37 of {\cite{CompanionPaperC11}}] \label{lemma:embeddedManifoldPositiveReachThenC1Embedded}
		Let $\M$ be a topologically embedded $n$-manifold in $\R^d$ with reach larger than $R>0$, and $p\in \M$ a point in $\M$. Then:
		\begin{enumerate}
			\item There exists an open neighbourhood $U_p\subset T_p\M$ of $p$ containing $B^\circ(p,\rch(\M))$, and a map $f: U_p \rightarrow N_p\M$, such that the map
			\begin{align*}
				\Phi:U_p \to\M, \qquad x\mapsto\Phi(x) \defunder{=} p + x + f(x),
			\end{align*}
			is a $C^{1,1}$ map from $U_p$ to $\M$. 
			\item For every $\delta >0$, there exists an $\alpha >0$ such that on the restricted domain $U_p \cap B(0, \alpha)^\circ$, the derivative of $f$ is $\frac{1}{(R - \delta)}$-Lipschitz. In other words, for all points $y_1,y_2\in U_p \cap B(0, \alpha)^\circ$, the difference between the derivatives at the points $y_1$ and $y_2$ with respect to the operator 2-norm is bounded by
			\[
			\big\|Df(y_2)  - Df(y_1)  \big\|_{2}  \leq \frac{1}{(R - \delta)}  | y_2 - y_1 |.
			\]
			\item If $\delta$ satisfies $ \delta \leq R/2$, then we can choose $\alpha = \sqrt{\delta R}$.
		\end{enumerate}
	\end{theorem}


