	\subsection{Results from differential topology}\label{subsec:DifTop}
	In this section we {recall} three {elementary} tools from differential topology: partition of unity functions, the smoothing process, and operator norms. We adopt the formulation and notation used by Hirsch~\cite[Chapter 2]{Hirsch1976}. 

	\paragraph*{Partition of unity functions}
	Partition of unity functions allow us to localize constructions and proofs in differential topology. They are defined as follows:
	\begin{definition}\label{def:partition_of_unity}
		Let $M$ be a $C^k$ manifold, with $0 \leq k\leq \infty$, and $\mathcal{U} = \{ U_i\}_ {i \in I}$, with an index set $I$, an open cover of $M$. A $C^k$ \emph{partition of unity} subordinate to $\mathcal{U}$ is a family of $C^k$ maps $\psi_i: M \to [0,1]$, $i \in I$, with the following properties: 
		\begin{itemize} 
			\item For every $i \in I$, the support\footnote{The support of a function $\psi$ is the closure of the set $\psi^{-1} (\mathbb{R}\setminus \{0\})$.} $\supp(\psi_i)$ of $\psi_i$ is contained in the set $U_i$. 
			\item The collection $\{\supp(\psi_i)\}_{i\in I}$ of the supports of $\psi_i$ is locally finite. 
			\item The maps $\psi_i$ sum to the function that is identically equal to $1$, that is,
			\[ \sum_i \psi_i (x) =1 .\] 
		\end{itemize} 
	\end{definition} 
	\begin{figure}[h!]
		\centering
		\includegraphics[width=.5\textwidth]{part_unity3}
		\caption{A cover $\{U_1\cup U_2, U_2\cup U_3\}$ of a set $U\subseteq \R^n$, and the corresponding family $\left\{\psi,\tilde{\psi}\right\}$ of partition of unity functions.}
		\label{fig:part_unity}
	\end{figure}
	We illustrate the concept for our setting in Figure~\ref{fig:part_unity}. We can find a partition of unity for any open cover:
	\begin{theorem}[Theorem 2.1 of {\cite{Hirsch1976}}] Let $M$ be a $C^k$ manifold with $1\leq k \leq \infty$. Every open cover of $M$ has a subordinate $C^k$ partition of unity. 
	\end{theorem}  

	\paragraph*{Kernel smoothing} 
	Kernel smoothing is, broadly speaking, a process that averages a map using a \textit{kernel} function, making the result at least as smooth as the kernel itself. The kernel is defined as follows:
	\begin{definition}[Smoothing kernel]\label{def:kernel}
		A (smooth) map $\varphi : \mathbb{R}^n \to \mathbb{R}$ is called a \emph{convolution} or a \emph{smoothing kernel} if it is non-negative, has compact support, and $\int_{\mathbb{R}^n} \varphi =1$.

		The \emph{support radius} of the smoothing kernel $\varphi$ is the smallest value $\sigma\in\mathbb{R}_{\geq 0}$, for which the support $\supp(\varphi)$ of $\varphi$ is contained in the closed ball of radius $\sigma$ centred at the origin: \[\supp(\varphi)\subset B(0,\sigma)\subset \mathbb{R}^n.\]
	\end{definition}
	We illustrate the smoothing radius in Figure~\ref{fig:support_radius}.
	\begin{figure}[h!]
		\centering
		\includegraphics[width=\textwidth]{support_radius}
		\caption{The support radius of the smoothing kernel $\varphi$. %\Andre{[Does this figure help ?]}
		}
		\label{fig:support_radius}
	\end{figure}

	Smoothing relies on neighbourhoods, determined by the support radius of the kernel. For smoothing of a map on a given set to be well-defined, the map itself must be well-defined on a sufficiently thick neighborhood surrounding the set. Consequently, it is sometimes necessary to shrink the domain of the map where the smoothing will be applied: 
	\begin{definition}\label{def:shrinking} 
		Consider a smoothing kernel with support radius $\sigma$. Given an open set $U\subset \mathbb{R}^n$, the \emph{shrinking} $U_\sigma$ of $U$ is defined as
		\[U_\sigma = \{ x \in U| B(x, \sigma) \subset U \}. \] 
	\end{definition} 
	\begin{figure}[h!]
		\centering
		\includegraphics[width=0.45\textwidth]{shrinking}
		\caption{The shrinking of a set as defined in Definition \ref{def:shrinking}.}
		\label{fig:shrinking}
	\end{figure}
	The smoothing process, or in other words, the \textit{convolution}, is carried out through integration:
	\begin{definition}[Convolution]\label{def:convolution}
		Let $\varphi : \mathbb{R}^n \to \mathbb{R}$ be a smoothing kernel with support radius $\sigma$, $U \subset \mathbb{R}^n$ an open set, and $f: U \to \mathbb{R}^{d-n}$ a continuous map. The \emph{convolution} of $f$ by $\varphi$ is the map 
		\begin{align}
			&\varphi \ast f : U_\sigma \to \mathbb{R}^{d-n},
			\nonumber 
			& x\mapsto\varphi \ast f(x) =\int_{\mathbb{R}^n} \varphi (y) f(x-y) \ud y.%, 
		\end{align} 
	\end{definition}
	Smoothing improves the smoothness of the map, and commutes with differentiation: 
	\begin{theorem}[{\cite[Theorem 2.3 (a) and (b)]{Hirsch1976}}]\label{Th23abHirsch}
		Let $\varphi: \mathbb{R}^n \to \mathbb{R}$ be a smoothing kernel with support radius $\sigma>0$, $U \subset \mathbb{R}^n$ an open set and $f: U\to \mathbb{R}^{d-n}$ a continuous map. The convolution $\varphi  \ast f: U_\sigma  \to \mathbb{R}^{d-n}$ has the following properties: 
		\begin{itemize} 
			\item If $\varphi$ is $C^k$, with $1 \leq k\leq \infty$, then so is $\varphi \ast f$, and for each finite $\ell\leq k$,
			\[ D^\ell (\varphi \ast  f ) = D^\ell (\varphi) \ast  f \] 
			on $U_\sigma$.  
			\item If $f$ is $C^{k}$, with $1 \leq k\leq \infty$, then so is $\varphi \ast f$, and for each finite $\ell\leq k$,
			\[ 
			D^\ell (\varphi \ast f)= \varphi \ast (D^\ell f).
			\] 
		\end{itemize} 
	\end{theorem} 
	%\Andre{[In fact we use only the second statement of this theorem in the paper, why keep both ? 
	%If it is to give some insight, one could also simply informally recall that, in a slightly less constrained context (where the two functions  play a symmetrical role), convolution operator $\ast$ is commutative and associative (since it is commutative,  both statements of the theorem are the same) ?? ]}. {\color{red} We definitely use the first statement to conclude that the manifold $\M'$ is in fact $C^{\infty}$, I agree that this is only one instance, but a rather central one. The statements only differ with regard to the domain of definition. I took the text literally from Hirsch.  } 
	\paragraph*{Operator norms}
	The last result we need is the convergence of smoothed maps to the original map. We consider convergence of the map itself as well as its first $k$ derivatives with respect to the so-called \textit{$C^k$ norm}. We define this norm in two steps:
	\begin{definition}\label{def:norm_linear_maps}
		The norm $\| .\|$ of a $k$-linear map 
		\[
		S: \mathbb{R}^n \times  \dots \times \mathbb{R}^n \to \mathbb{R}^m, \qquad (u_1,\dots,u_k)\mapsto S(u_1 , \dots , u_k),
		\] 
		is defined as 
		\[ \| S \| = \max_{|u_i |=1 }   | S (u_1 , \dots , u_k) |  .\] 
	\end{definition} 
	Consider a $C^k$ map $f: U  \to \mathbb{R}^{d-n}$, and its $r$th order derivative $D^r  f$.
	For $r \geq 1$, the map $D^r  f (x)$ is an $r$-linear map at each point $x\in U$, and we use the above definition to measure the norm $\| D^r  f (x) \|$ of $D^r  f$ at $x$. For $r=0$, the notation $\| D^r  f (x) \| = \| D^0  f (x) \| $ should be understood as $|f(x)|$. 

	\begin{definition}[$C^k$ norm]\label{def:Ck_norm}
		Let $f :U \to \mathbb{R}^{d-n}$ be a $C^k$ map, $U \subset \mathbb{R}^n$ an open set, and $C \subset U$ any subset of $U$. The $C^k$ norm of $f$ {on $C$} is defined as 
		\[ \|f \| _{k,C} = \sup \{ \| D^r  f (x) \| \mid x\in C ,  0 \leq r \leq k\}. 
		\]
	\end{definition} 
	We can now define the convergence we will use: 
	\begin{theorem}[{\cite[Theorem 2.3 (c)]{Hirsch1976}}]\label{Th:Hirsch23c}
		Let $U \subset \mathbb{R}^n$ be an open set with a compact subset $C \subset U$, and $f: U\to \mathbb{R}^{d-n}$ a $C^k$ map, with $ 0 \leq k \leq \infty$.
		For any $\varepsilon> 0$ there exists a value $\sigma >0$ such that $C \subset U_\sigma$, and any $C^k$ smoothing kernel $\varphi$ with support radius $\sigma $ satisfies
		\[ \| \varphi \ast f - f \| _{k, C} \leq \varepsilon. \]   
	\end{theorem} 
	\begin{remark} \label{remark:operator_2-norm}
		The operator $2$-norm of a matrix $A$ is defined as 
		\begin{align} 
			\|A \|_2 =\sup_{v \neq 0} \frac{|A v | }{|v|}= \max_{|v|=1} |A v |  ,  
			\nonumber
		\end{align} 
		where $| \cdot |$ denotes the usual Euclidean ($2$-)norm. 
%			\Andre{[I would remove the index $2$ for the norm]} {\color{red} I kind of see the point, but I adopted Hirsch' notation for the general $k$-linear norm and wanted something to emphasize that this is really a the standard matrix norm. If you want to do this I think we need to find another notation for the $k$-linear norm. One not so good argument against changing it is that it takes a lot of time and is liekly to lead to errors. }

		For the first derivative of a function $f$, evaluated at a point $x$, the norm from Definition~\ref{def:norm_linear_maps} coincides with the operator $2$-norm, that is, $\|D^1  f (x) \| = \|D^1  f (x) \|_2$.
		In particular,
		\[\|Df \| _{0,C} = { \sup }\{ \|Df (x) \|_2 \mid x\in C \} \qquad \text{and}\qquad \|f \| _{1,C} = {\max} \{\|f \| _{0,C}, \|Df \| _{0,C} \}. \]
	\end{remark} 

	In this paper, we primarily focus on the case where $k=1$, as estimating the first derivative proves to be the main challenge in our proofs. Consequently, much of our work involves dealing with operator 2-norms.

	In addition, we often make a choice of the map $f$ on which we perform the smoothing. The lemma below implies that our choice does not depend on the map $f$ itself, but only on its Lipschitz constant.
	\begin{lemma}[Folklore] \label{lemma:norm_of_smoothing_depends_on_Lipschitz_const_only}
		We adapt the settings from Theorem~\ref{Th:Hirsch23c}. If the map $f$ is $L$-Lipschitz, then for any point $x\in U_\sigma$ and $y \in B(0, \sigma)$ it holds that $ | f(x-y) -f(x)| \leq L\sigma $.
		As a consequence,
			\begin{align}   
					\| \varphi \ast f - f \| _{0, C}\leq  L \sigma.\nonumber
				\end{align}  
	\end{lemma}


	\section{On the control over Lipschitz constants while smoothing and using partition of unity functions}\label{sec:section_3}
	This section consists of three parts, in which we
	\begin{itemize}
		\item {recall} that smoothing by convolution does not affect Lipschitz constants;
		\item set the stage to define the function $F$ that locally describes our smoothed manifold $\M'$, and determine the Lipschitz constant of $F$ and its derivative;
		\item establish two bounds on the distance between the affine tangent space of a point on the graph of $F$, and another point in $\M'$.
	\end{itemize}

	\subsection{Lipschitz constants for smoothings by convolution}\label{sec:lipschitz_consts_for_smoothings}
	In this section we focus on Lipschitz constants. %{\color{red} [I find that the place of the following is a little bit strange, I personally don't feel like we need it, but I can see why one would differ on this, however given the formulation of what is now Theorem 4, it would be more natural to recall what a Lipschitz constant is before the statement of that theorem]} 
	To this end, we denote the Lipschitz constant of a function $g$ by $L_g$.
	We recall that a function $g: \mathbb{R}^n \to \mathbb{R}^m$ is Lipschitz with constant $L_g$ if for all points $y_1,y_2\in \R^n,$
	\begin{align}\label{eq:Lipschitz_cont}
		\abs{g(y_2) - g(y_1)}\leq L_g \abs{y_2-y_1}.
	\end{align}
	Similarly, if $g$ is differentiable, the derivative $Dg$ of $g$ is Lipschitz with constant $L_{Dg}$ if for all points $y_1,y_2\in \R^n,$
	\begin{align}\label{eq:Lipschitz_cont_derivative}
		\big\|Dg(y_2)  - Dg(y_1)  \big\|_{2}  \leq L_{Dg} | y_2 - y_1 |.
	\end{align}
%	\Andre{[I would remove the index $2$ for the operator norm, but if you prefer to keep it, it is allright.]}
	We first {recall}  that smoothing does not influence the Lipschitz constant of a function or its derivative. 
