	\begin{lemma}[Folklore] \label{lem:SmoothingConservesLipschitzConstants} 
		Let $g: \mathbb{R}^n \to \mathbb{R}^{d-n}$ be an $L_g$-Lipschitz map and $\varphi: \mathbb{R}^n \to \mathbb{R}$ a smoothing kernel. Then the smoothing by convolution $\varphi \ast g$ is also $L_g$-Lipschitz.
	\end{lemma} 
%	\sout{A similar statement can be made about the first derivative: }
