	\begin{lemma}[Folklore] \label{lem:smoothingPreservesLipschitzConstantDerivative}
		Let $g:\mathbb{R}^n \to \mathbb{R}^{d-n}$ be a function whose \emph{first derivative} is $L_{Dg}$-Lipschitz. 
		Let further $\varphi: \mathbb{R}^n \to \mathbb{R}$ be a smoothing kernel. 
		Then the first derivative of the smoothing by convolution $\varphi \ast g$ is also $L_{Dg}$-Lipschitz.
	\end{lemma}

	\subsection{Interpolation between a Lipschitz function and its smoothing by convolution}\label{sec:interpolation_and_universal_settings}
	In this section, we consider an interpolation $F$ between a map $f$ locally describing our manifold, and its convolution $\varphi\ast f$, using a partition of unity function $\psi$. A formal definition of the function $F$ will follow shortly. We illustrate this construction in Figure~\ref{fig:F_construction}.

	\begin{figure}[h!]
		\centering
		\includegraphics[width=0.6\textwidth]{F_construction}
		\caption{The superposed graphs of $f, F$, and $\psi$ show that $F$ is smooth on $U_1$ and $F=f$ on $U_3$.}
		\label{fig:F_construction}
	\end{figure}

	To be able to use local arguments, we need to prove that the Lipschitz constants of $F$ and its first derivative are close to the Lipschitz constants of $f$ and its first derivative.

The Lipschitz constants of the function $F$ were studied in \cite{SmoothingOnManifolds2007}, leading to a result similar to our Lemma \ref{Lem:LipschitzWithoutDer}. Our key contribution lies in determining the Lipschitz constant of the \textit{derivative} of $F$, a significantly more intricate task and one that is crucial for proving the main result.

	\noindent\textbf{Throughout the rest of this paper, we operate under the following settings:}
	\begin{itemize}
		\item We consider a function $f:U\subseteq\mathbb{R}^n \to \mathbb{R}^{d-n}$ whose graph is (locally) the manifold $\M$. Such a map exists due to Theorem~\ref{lemma:embeddedManifoldPositiveReachThenC1Embedded}. Moreover, both $f$ and its derivative $Df$ are Lipschitz, and we denote their Lipschitz constants by $L_f$ and $L_{Df}$, respectively.
		\item We cover the domain $U$ with two sets $\{U_1\cup U_2, U_2\cup U_3\}$ and consider a partition of unity subordinate to this cover. We denote the partition of unity function corresponding to the set $U_1\cup U_2$ by $\psi$, and the closure of its support by
		\[\overline{\supp{\psi}} = C.\]
		We assume $C$ to be compact. We denote the Lipschitz constants of $\psi$ and its derivative $D\psi$ by $L_{\psi}$ and $L_{D\psi}$, respectively, write
		\begin{align}
			L_{\psi,D \psi}= \max \{L_{\psi} , L_{D\psi} \},
			\label{eq:LipschitzpsiDpsi} 
		\end{align}
		and note that
		\begin{align} 
			\sup_{y\in C} \| D \psi  (y) \|_2 =  \| D \psi \|_{0,C} \leq L_{\psi} \leq L_{\psi,D \psi}.
			\label{eq:boundDpsi} 
		\end{align} 
		\item For $\varepsilon>0$ we choose a smoothing kernel $\varphi_\varepsilon:U\to \R$  such that
		\begin{align} 
			\| \varphi_{\varepsilon}  \ast f - f \| _{1, C}  \leq \varepsilon.
			\label{eq:AssumptionSmoothing1} 
		\end{align} 
		Such kernel exists due to Theorem \ref{Th:Hirsch23c}. 
		We recall (see Remark~\ref{remark:operator_2-norm}) that inequality~\eqref{eq:AssumptionSmoothing1} holds if and only if both of the following inequalities hold:
		\begin{align} 
			\sup_{y\in C}\| (\varphi_{\varepsilon}  \ast Df - Df)(y) \|_2=\| \varphi_{\varepsilon}  \ast Df - Df \| _{0, C}  \leq \varepsilon,
			\label{eq:AssumptionSmoothing2} 
		\end{align} 
		and 
		\begin{align} 
			\sup_{y\in C}\abs{(\varphi_{\varepsilon}  \ast f - f)(y) }=\| \varphi_{\varepsilon}  \ast f - f \| _{0, C}  \leq \varepsilon.
			\label{eq:AssumptionSmoothing3} 
		\end{align}
		\item The (locally) smoothed manifold $\M'$ is then locally described by the graph of the function
		\begin{align}\label{eq:smoothed_mfld_function}
			F:U\to\R^{d-n}, \qquad x\mapsto F(x)= (1- \psi(x))  f (x) + \psi (x)(\varphi_\varepsilon \ast f(x)).
		\end{align}
	\end{itemize}

