	\subsection{On bounding the reach of $\M'$ in terms of Lipschitz constants}\label{sec:bounds_on_tangent_spaces}
	Let $\M'$ denote the manifold that 
	\begin{itemize}
		\item equals the graph of the function $p+F$ inside the neighbourhood of the point $p$;
		\item equals $\M$ outside of this neighbourhood. 
	\end{itemize}

	Our next goal is to bound the reach of $\M'$. To this end, we use a result by Federer~\cite{Federer} that characterizes the reach of a manifold through the distance from a point on it to a tangent space of another point on it. We recalled this result in Theorem~\ref{th418Federer}.
	We provide two different bounds on this distance. In order to prove the latter, we also establish bounds on the angle between tangent spaces of the graphs of $f$ and $F$.

	\begin{figure}[h!]
		\centering
		\includegraphics[width=.75\textwidth]{setting_3.3}
		\caption{Illustration of the setup for this section.}
		\label{fig:setting_3.3}
	\end{figure}

	\noindent\textbf{We adapt the following settings, in addition to the ones established in Section~\ref{sec:interpolation_and_universal_settings}:}
	We fix two points $y_1,y_2\in C, y_1\neq y_2$, and label their graphs by
	\[p_1 = (y_1, f(y_1)), \quad p_2 = (y_2, f(y_2)) \qquad \text{and} \qquad p'_1 = (y_1, F(y_1)), \quad p'_2 = (y_2, F(y_2)).\]
	We write $G_f$ and $G_F$ for the graph of $f$ and $F$, respectively, and $T_{p_1}G_f$ and $\Tan_{p_1}G_f$ (resp. $T_{p_1'}G_F$ and $\Tan_{p_1'}G_F$) for the tangent and affine tangent space of $f$ at $p_1$ (resp. of $F$ at $p_1'$).

	We illustrate this setup in Figure~\ref{fig:setting_3.3}.
	\begin{lemma} \label{lem:ErrorLipschitzDer}
		The distance between the point $p_2'$ and the affine tangent space $\Tan_{p_1'}G_F$ is bounded by
		\begin{align}\label{eq:reach-tangent-cone-compatibility}
			d(p_2' , \Tan_{p_1'}G_F)\leq \tfrac{1}{2}(3 L_{\psi,D \psi} \varepsilon   +L_{Df})\abs{p_2'-p_1'}^2.
		\end{align}
		This has the following consequence: Let $\rho>0$ be small enough that the $\rho$-neighbourhood of $y_1$ is contained in $C$, $B(y_1, \rho)\subseteq C$. Then the graph $G_F$ of the function $F$ in this neighbourhood is contained in the union of balls
		\[ 
		\bigcup_{v\in\R^n :  |v| = r\leq \rho} B \left(p_1'+\begin{pmatrix} 
			v \\ DF( y_1 ) v
		\end{pmatrix} , \tfrac{1}{2}(3 L_{\psi,D \psi} \varepsilon   +L_{Df}) \:r^2 \right).
		\]  
	\end{lemma}
	We illustrate the settings of Lemma~\ref{lem:ErrorLipschitzDer} in Figure~\ref{fig:lemma_24}.

	\begin{figure}[h!]
		\centering
		\includegraphics[width=.65\textwidth]{lemma_24}
		\caption{Illustration of the settings of Lemma~\ref{lem:ErrorLipschitzDer}.
		}
		\label{fig:lemma_24}
	\end{figure}

	As an auxiliary result needed to prove Proposition~\ref{prop:pointsFarAway}, we obtain a bound on the angle between the affine tangent spaces $\Tan_{p_1} G_f$ and $\Tan_{p_1'} G_F$, as well as a bound on the Hausdorff distance between two neighbourhoods contained in these spaces.
	We note that the angle between two affine spaces is equal to the angle between the corresponding vector spaces. The angle between two vector subspaces $A$ and $B$ is defined as
	\begin{align*}
		\angle A, B \defunder{=} \max_{a\in A\setminus \{0\}} \min_{b \in B \setminus \{0\}}
		\angle a,b = \max_{b \in B\setminus \{0\}} \min_{a \in A \setminus \{0\}} \angle a,b.
	\end{align*} 
	\begin{lemma}\label{boundangleTangentSpace} 
		Assume that $\varepsilon\leq\tfrac{1}{L_{\psi,D \psi}+1}$. Then the angle between the affine tangent spaces $\Tan_{p_1} G_f$ and $\Tan_{p'_1} G_F$  is bounded by
		\[
		\angle (\Tan_{p_1}G_f , \Tan_{p'_1} G_F) \leq \arcsin\left( L_{\psi,D \psi}  \varepsilon  +  \varepsilon\right).
		\] 
	\end{lemma}

	\begin{figure}[h!]
		\centering
		\includegraphics[width=.5\textwidth]{cor_27}
		\caption{The 3$R$-neighbourhoods of the points $p_1$ (in dark blue) and $p_1'$ (in pink) in the corresponding affine tangent spaces.}
		\label{fig:cor_27}
	\end{figure}
	\begin{corollary}\label{CorHD}
		Let $R>0$ denote the reach of the manifold $\M$, and consider the $n$-dimensional neighbourhood of size $3R$ of the point $p_1$ in the affine tangent space $\Tan_{p_1}G_f$: 
		\begin{align*}
 {\mathcal{A} = p_1 + \{T \in T_{p_1}G_f \mid |T| \leq 3R \}.}
		\end{align*}
		Similarly, consider a $3R$-neighbourhood of the point $p_1'$ in the affine tangent space $\Tan_{p_1'}G_F$:
		\begin{align*}
 {\mathcal{B} = p_1' + \{T \in T_{p_1'}G_F \mid |T| \leq 3R \}.}
		\end{align*}
		Assume that $\varepsilon\leq\tfrac{1}{L_{\psi,D \psi}+1}$. Then the Hausdorff distance between the two neighbourhoods is upper bounded: 
		\[ 
		d_H {(\mathcal{A}, \mathcal{B})}\leq \varepsilon\left( 6R L_{\psi,D \psi}+6R+1 \right).
		\] 
	\end{corollary} 
	The settings of Corollary~\ref{CorHD} are illustrated in Figure~\ref{fig:cor_27}.


	At last, we bound the distance between the affine tangent space $p+\Tan_{p_1'} G_F$ and a point $q'\in\M'$ that does not lie on the graph of $p+F$. We illustrate the settings in Figure~\ref{fig:proposition}.
	\begin{figure}[h!]
		\centering
		\includegraphics[width=\textwidth]{proposition}
		\caption{Illustration of the setup of Proposition~\ref{prop:pointsFarAway}.}
		\label{fig:proposition}
	\end{figure}
	\begin{proposition} \label{prop:pointsFarAway} 
		Let $q'\in\M'\backslash(p+G_F)$, and assume that $\varepsilon\leq\tfrac{1}{L_{\psi,D \psi}+1}$.
Write $p+p_1' = p'$. Then the distance between the point $q'$ and the affine tangent space $\Tan_{p'}\M' = p+\Tan_{p_1'}G_F$ is bounded by
		\begin{align}\label{eq:distance_ala_Federer_with_epsilons}
			d(q' , \Tan_{p'}\M')  \leq  \frac{|q'-p'|^2}{2R} + \frac{\varepsilon^2}{2R}   + \varepsilon\left(6R L_{\psi,D \psi}+6R+4\right).
		\end{align}
		Therefore, if $\varepsilon<R$ and $\abs{q'-p'}\geq \beta$, then 
		\[  d(q' , \Tan_{p'} \M')   \leq  \frac{|q'-p'|^2}{2R'} ,
		\] 
		with 
		\begin{align}  R'= 
\frac{R}{1+\frac{12\varepsilon R}{\beta^2}\left(R L_{\psi,D \psi}+R+1\right)}.
			\nonumber
		\end{align} 
	\end{proposition} 




	\section{Proof of the main theorem} \label{sec:proof_main_theorem}

	We now have all the necessary tools to prove our main result. Before proceeding, let us restate the theorem:
	\MainTheorem*

	\begin{proof}
		This proof brings together all results from the previous sections. Roughly speaking, we split the manifold $\M$ into neighbourhoods, which we smooth iteratively one by one. Each smoothing process decreases the reach of the manifold; after each iteration, we check that the reach has not been altered `too much', so that after visiting all the neighbourhoods, we can ensure that the reach has not been decreased by more than $\varepsilon$. Let us dive in.
		\subparagraph{Step 1.}	
		In the first step we select a sample $\P$ of the manifold $\M$ (see also Figure~\ref{fig:main_proof}, right). To this end, we choose a parameter $0<\delta\leq R/2$, and let $\P$ be a $\sqrt{\delta R}/16$-net\footnote{The factor $16$ in $\sqrt{\delta R}/16$ is almost certainly suboptimal. However, it simplifies the proof by a margin.
		} on $\M$, meaning that
		\begin{itemize}
			\item for every point $x \in \M$ one can find a point $\p \in \P$, such that $|x-\p| \leq \sqrt{\delta R}/16$, %\hanka{ \sqrt{\delta R}/16}?
%and {\color{red} Indeed 16 and 32 were interchanged, it should be 32 below as well. }
			\item for all $\p,\q\in\P$, $|\p-\q| \geq \sqrt{\delta R}/16$.
		\end{itemize}
		Such a net exists thanks to \cite[Lemma 5.2, Section 5.1.1]{JDbook}.

		Due to these properties, the $\sqrt{\delta R}/16$-balls centred at the points of the sample $\P$ cover $\M$. In addition, we consider balls of radius $\sqrt{\delta R}/2$ centred at the points of $\P$, and write $N_C$ for the maximal number of such balls that intersect in {a given ball of  a ball of radius $\sqrt{\delta R}/2$}.
		By a standard packing argument (see e.g. %such as {\color{red} I find the such as a bit strange? why not see e.g. , or just the citation} 
\cite[Lemma 5.3, Section 5.1.1]{JDbook}), $N_C \leq \mathcal{O}(8^d)$, and in fact $N_C \leq \mathcal{O}(8^n)$ where $n$ is the dimension of the manifold. 

%		\Andre{[Also, should we not add a small margin on the net in order to insure that it remains a covering as both the point sample and the manifold are ``moving'' ?] } {\color{red} A massive margin is already there to take care of this kind of stuff. }

		We need one more ingredient before we start iteratively visiting neighbourhoods of each point $\p\in\P$ --- a fixed partition of unity function, which we rescale at every iteration. To this end, we split the ball $B(0,4)\subseteq\R^n$ into three sets,
		\[
		V_1 = B(0, 1), \quad V_2 = \{x\in\R^n\mid 1\leq\abs{x}< 2\}, \quad V_3 = \{x\in\R^n\mid 2\leq\abs{x}\leq 4\}.
		\]
		The two sets $\{V_1\cup V_2, V_2\cup V_3\}$ then cover the ball $B(0,4)$, and we let $\psi_0$ be the partition of unity function corresponding to the set $V_1\cup V_2$. Then $\psi_0\equiv 1$ on $V_1$, and $\psi_0\equiv 0$ on $V_3$.	

		Next, we select a point $\p\in\P$, and restrict our attention to the ball $B(\p,\sqrt{\delta R}/2)$ of radius $\sqrt{\delta R}/2$ centred at $\p$.
		\subparagraph{Step 2.}	
		Let $f$ be a function whose graph describes the manifold $\M$ in the ball $B(\p,\sqrt{\delta R}/2)$. To be more concrete, choose $f:T_\p\M\cap B(0,\sqrt{\delta R}/2)\to N_\p\M $ as in Theorem~\ref{lemma:embeddedManifoldPositiveReachThenC1Embedded}. Due to this theorem and our choice of $\delta$, the derivative of $f$ is $\frac{1}{R-\delta}$-Lipschitz on the whole domain $T_\p\M\cap B(0,\sqrt{\delta R}/2)$.

		\begin{figure}[h!]
			\centering
			\includegraphics[width=\textwidth]{main_proof}
			\caption{The point sample $\P$ at a piece of the manifold $\M$, and the neighbourhoods $U_1, U_2$, and $U_3$.}
			\label{fig:main_proof}
		\end{figure}

		We apply the smoothing construction described in Section~\ref{sec:interpolation_and_universal_settings}. As ingredients, we need a partition of unity function, and a smoothing kernel.

		\noindent\emph{Partition of unity function:} We map the neighbourhood $T_\p\M\cap B(0,\sqrt{\delta R}/2)$ diffeomorphically to the ball $B(0,4)\subseteq \R^n$ using the canonical identification of the tangent space $T_\p\M$ with $\R^n$ and the map $x\mapsto \frac{8}{\sqrt{\delta R}}\cdot x$. The preimages of the sets $V_1, V_2$, and $V_3$ under this map are, respectively,
		\begin{align*}
			&U_1 = \left\{ x\in T_\p\M \mid \abs{x}<\sqrt{\delta R}/8 \right\}, \\
			&U_2 = \left\{ x\in T_\p\M \mid \sqrt{\delta R}/8\leq \abs{x}<\sqrt{\delta R}/4 \right\}, \\
			&U_3 = \left\{ x\in T_\p\M \mid \sqrt{\delta R}/4\leq \abs{x}\leq\sqrt{\delta R}/2 \right\}.
		\end{align*}
		The sets $U_1, U_2,$ and $U_3$ are illustrated in Figure~\ref{fig:main_proof}, on the left.
		We define $\psi$ by {scaling} the partition of unity function $\psi_0$: $\psi(x) = \psi_0 \left(\frac{8x}{\sqrt{\delta R}}\right )$. Then $\psi$ is the partition of unity function corresponding to the set $U_1\cup U_2$ in the cover $\{U_1\cup U_2, U_2\cup U_3\}$ of $T_\p\M\cap B(0,\sqrt{\delta R}/2)$, and thereby, $\psi\equiv 1$ on $U_1$, and $\psi\equiv 0$ on $U_3$. Furthermore:

		%\Andre{[I would not make Lemma \ref{lemma:Lipschitz_conts_psi}
		 %as a lemma. I would just say, ``observe that ..." , without any proof, as if, really,  it is not obvious to the reader, it means that he needs to think a little bit harder by himself to improve its ``vision'', while, in this case, a step by step proof of an obvious result may obscure things. Also,  it may be a bad (but not uncommon) bias, but, as a reviewer, if I see a formal proof for such an obvious claim, I tend to think that the paper is weak. Same remark for Lemmas \ref{lem:SmoothingConservesLipschitzConstants} 
%and \ref{lem:smoothingPreservesLipschitzConstantDerivative}] } 



		\begin{lemma}[Folklore]\label{lemma:Lipschitz_conts_psi}
			The Lipschitz constants of $\psi$ and its derivative are bounded by
			\begin{align*}
				L_{\psi}\leq\frac{8}{\sqrt{\delta R}} L_{\psi_0} \qquad \text{and} \qquad L_{D\psi}\leq\frac{64}{\delta R} L_{D\psi_0}.
			\end{align*}
		\end{lemma}



		By decreasing $\delta$ if necessary, we can also assume that $\frac{8}{\sqrt{\delta R}} L_{\psi_0}\leq \frac{64}{\delta R} L_{D\psi_0}$. Thus:
		\begin{align}\label{eq:Lipschitz_const_final_psi}
			L_{\psi, D\psi} = \max \{L_\psi, L_{D\psi} \}\leq \frac{64}{\delta R} L_{D\psi_0}.
		\end{align}

		\noindent\emph{Smoothing kernel:} Let $C = \overline{\supp \psi}$. For $0<\rho<\frac{1}{1+\frac{64}{\delta R} L_{D\psi_0}}$ we choose a smoothing kernel $\varphi_\rho:T_\p\M\cap B(0,\sqrt{\delta R}/2)\to \R$  such that
		\begin{align} 
			\| \varphi_{\rho}  \ast f - f \| _{1, C}  \leq \rho.
			\tag{\ref{eq:AssumptionSmoothing1}}
		\end{align} 
		Such kernel exists due to Theorem \ref{Th:Hirsch23c}.
		With these choices we define 
		\begin{align}
			F:T_\p\M\cap B(0,\sqrt{\delta R}/2)\to N_\p\M, \qquad x\mapsto F(x)= (1- \psi(x))  f (x) + \psi (x)(\varphi_\rho \ast f(x)).\tag{\ref{eq:smoothed_mfld_function}}
		\end{align}



		\subparagraph{Step 3.}	
		We write $\M'$ for the manifold that coincides with $\M$ outside of the ball of radius $\sqrt{\delta R}/2$ centred at the point $p$, and is the graph of $\p+F$ inside this ball.

		To be more concrete, we recall that we can write each point $p\in\M\cap B(\p, \sqrt{\delta R}/2)$ as $p = \p + y + f(y)$, with $y\in T_\p\M$. With this in mind we define, for each $p\in\M$:
		\begin{align*}
			p' \defunder{=}  \begin{cases}
				\p + y + F(y), & \text{if } p\in B(\p, \sqrt{\delta R}/2),\\
				p, & \text{otherwise},
			\end{cases}
		\end{align*}
	and let $\M' = \{p'\mid p\in\M\}$.
%
