	\begin{proof}[Proof of Lemma \ref{lem:SmoothingConservesLipschitzConstants}] 
		By definition of a smoothing kernel, $\int  \varphi(z) =1$. Therefore,
{
\allowdisplaybreaks
		\begin{align} 
			\left |\varphi \ast g (y_2) -  \varphi \ast g(y_1) \right| &= \left| \int_z \varphi (z) g(y_2-z) \ud z  -  \int_z \varphi (z) g(y_1-z) \ud z \right | 
			\nonumber 
			\\
			&=  \left | \int_z \varphi (z) (g(y_2-z)  - g(y_1-z)) \ud z \right | 
			\nonumber
			\\
			&\leq   \int_z \varphi (z) |(g(y_2-z)  - g(y_1-z)) |\ud z  
			\tag{because $\varphi$ is non-negative}
			\\
			& \leq  L | y_2-y_1| \int _z \varphi (z) \ud z
			\tag{by the definition of the Lipschitz constant} 
			\\
			& = L  | y_2-y_1|.  
			\tag{because $\int  \varphi(z) =1$} 
		\end{align}}
	\end{proof} 

