	\begin{proof}[Proof of Lemma \ref{lem:smoothingPreservesLipschitzConstantDerivative}] 
		Let $v\in \mathbb{R}^{d-n}$ and $w\in \mathbb{R}^n$ be two vectors with $|v|=|w|=1$.


		Because for every pair of points $y_1,y_2\in\R^n$ holds $\big\|Dg(y_2)  - Dg(y_1)  \big\|_{2}  \leq L | y_2 - y_1 |$, the function $y \mapsto \langle v , D(g(y))(w) \rangle$ is $L$-Lipschitz. In other words,
		\[\langle v , D(g(y_2) )(w) \rangle   -\langle v ,   D(g(y_1))(w)  \rangle = \langle v , (D(g(y_2))-D(g(y_1)))(w) \rangle  \leq L |y_2 - y_1| .\]
		Therefore,
		\begin{align} 
			\langle v ,D (\varphi \ast g(y_2) )(w) \rangle   -\langle v , D (\varphi \ast g(y_1))(w)  \rangle  &= \langle v , \varphi \ast D(g(y_2) )(w) \rangle   -\langle v , \varphi \ast  D(g(y_1))(w)  \rangle 
			\tag{because $g$ is $C^1$}  
			\\
			&=  \varphi \ast \langle v , D(g(y_2) )(w) \rangle   - \varphi \ast \langle v ,   D(g(y_1))(w)  \rangle 
			\tag{by exchanging the order of the integral and the inner product}
			\\ 
			&\leq  L |y_2 - y_1|  .
			\tag{by Lemma \ref{lem:SmoothingConservesLipschitzConstants}} 
		\end{align} 
		Thus, by definition of the operator norm,
		\[ \big\|D (\varphi \ast g(y_2))  - D(\varphi \ast g(y_1))   \big\|_{2}  \leq L | y_2 - y_1 |.\]
	\end{proof} 

