				y_2- y_1 \\ DF( y_1 + (y_2-y_1) t ) (y_2-y_1)
			\end{pmatrix}
			\ud t
			\nonumber 
			\\ 
			&= \int_0^1 
			\begin{pmatrix} 
				y_2- y_1 \\ DF( y_1 ) (y_2-y_1) + DF( y_1 + (y_2-y_1) t ) (y_2-y_1) - DF( y_1 ) (y_2-y_1) 
			\end{pmatrix}
			\ud t
			\tag{by adding $0= DF(y_1) (y_2-y_1) -DF(y_1) (y_2-y_1)$}
			\\ 
			&= \begin{pmatrix} 
				y_2- y_1 \\ DF( y_1 ) (y_2-y_1) 
			\end{pmatrix} 
			+ \int_0^1  
			\begin{pmatrix}
				0 \\  \left(DF( y_1 + (y_2-y_1) t )- DF( y_1 )\right) (y_2-y_1) 
			\end{pmatrix} \ud t.
			\nonumber
		\end{align} 
		We set 
		\begin{align*}
			&T= \begin{pmatrix} 
				y_2- y_1 \\ DF( y_1 ) (y_2-y_1) 
			\end{pmatrix}, &\Delta V= 
			\int_0^1
			\begin{pmatrix}
				0 \\ \left(DF( y_1 + (y_2-y_1) t )- DF( y_1 )\right) (y_2-y_1) 
			\end{pmatrix} \ud t.
		\end{align*}
		As one can see from Figure~\ref{fig:lemma_24_proof}, the distance $d(p_2', \Tan_{p_1'}G_F) = d(p_2'-p_1', T_{p_1'}G_F) $ is the height at vertex $p_2'-p_1'$ of the triangle with vertices $0, T$, and $p_2'-p_1'=T+\Delta V$, and thus
		\begin{align} 
			d(p_2', \Tan_{p_1'}G_F)  \leq |\Delta V|.
			\label{eqDistTanS1} 
		\end{align} 
		Using the Lipschitz assumption on the derivative of $F$ and the triangle inequality for integrals, we further estimate
		\begin{align} \label{eq:delta_V_estimate}
			|\Delta V| \leq  
			\int_0^1 L_{DF} |y_2-y_1|^2 t \: \ud t  =\tfrac{1}{2} L_{DF} |y_2-y_1|^2 .
		\end{align} 
		Finally, by the triangle inequality,
		\begin{align} 
			|y_2-y_1| \leq  |(y_2, F(y_2))-(y_1, F(y_1))| = \abs{p_2'-p_1'}.
			\label{TriangInequal} 
		\end{align} 
		Combining \eqref{eqDistTanS1}, \eqref{eq:delta_V_estimate}, \eqref{TriangInequal}, and the bound on the Lipschitz constant from Lemma~\ref{lem:SmoothingWithPartition} yields equation \eqref{eq:reach-tangent-cone-compatibility}:
		\begin{align*} 
			d(p_2', \Tan_{p_1'}G_F)   \leq \tfrac{1}{2} L_{DF}\abs{p_2'-p_1'}^2\leq \tfrac{1}{2} (3 L_{\psi,D \psi} \varepsilon   +L_{Df})\abs{p_2'-p_1'}^2.
		\end{align*}
		To see that $p_2'\in B \left(p_1'+T , \frac{1}{2} L_{DF} |y_1-y_2|^2 \right)$, notice that this is equivalent to $p_2'-p_1' = T+\Delta V$ being contained in the ball $B \left(T , \frac{1}{2} L_{DF} |y_1-y_2|^2 \right)$, which follows from inequality \eqref{eq:delta_V_estimate}.
	\end{proof}

	We need the following lemma to prove Lemma~\ref{boundangleTangentSpace}:
	\begin{lemma}\label{lemma:angle_between_tangent_spaces}
		Consider two maps $g, \tilde{g} : \mathbb{R}^n \to \mathbb{R}^{d-n}$, whose derivatives are close in a neighbourhood of a point $y\in\R^n$ --- more concretely, there exists a $\delta <1$ such that
		\[
		\| (Dg- D\tilde{g})(y)\|_2 \leq  \delta.
		\]
		Let $G_g$ and $G_{\tilde{g}}$ denote the graph of $g$ and $\tilde{g}$, respectively, and $T_{(y,g (y))}G_g $ and $ T_{(y,\tilde{g}(y))} G_{\tilde{g}}$ their respective tangent spaces at the graph of the point $y$. Then the angle between $T_{(y,g (y))}G_g $ and $ T_{(y,\tilde{g}(y))} G_{\tilde{g}}$ satisfies
		\begin{align}\label{eq:angle_between_tangent_spaces}
			\angle (T_{(y,g (y))}G_g , T_{(y,\tilde{g}(y))} G_{\tilde{g}} ) \leq \arcsin \delta.
		\end{align}
	\end{lemma}
	The settings of Lemma~\ref{lemma:angle_between_tangent_spaces} are illustrated in Figure~\ref{fig:lemma_26}.
	\begin{figure}[h!]
		\centering
		\includegraphics[width=0.5\textwidth]{lemma_26}
		\caption{Illustration of the settings of Lemma~\ref{lemma:angle_between_tangent_spaces}.}
		\label{fig:lemma_26}
	\end{figure}

	\begin{proof}	
		Because the graph $G_g$ of $g$ is parametrized by $(y, g(y))$, its derivative is 
		\begin{align} 
			J_{g(y)}= 
			\begin{pmatrix}
				\textrm{Id} 
				\\ 
				Dg (y) 
			\end{pmatrix} ,
			\nonumber
		\end{align} 
		where $\textrm{Id}$ denotes the entries of the identity matrix and $Dg (y) $ the entries of the Jacobian at $y$. Similarly, the derivative of the graph $G_{\tilde{g}}$ of $\tilde{g}$ is 
		\begin{align} 
			J_{\tilde{g}(y)}= 
			\begin{pmatrix}
				\textrm{Id} 
				\\ 
				D\tilde{g} (y) 
			\end{pmatrix} ,
			\nonumber
		\end{align}

		\begin{figure}[h!]
			\centering
			\includegraphics[width=0.5\textwidth]{lemma_26_proof}
			\caption{Notation in the proof of Lemma~\ref{lemma:angle_between_tangent_spaces}.}
			\label{fig:lemma_26_proof}
		\end{figure}

		For a vector $v\in\R^n\backslash\{0\}$, let $J_{g(y)}  v\in T_{(y, g(y))} G_g$ and $J_{\tilde{g}(y)}  v\in T_{(y, \tilde{g}(y))} G_{\tilde{g}}$  be its images under the linear maps $J_{g(y)}$ and $J_{\tilde{g}(y)}$. We illustrate the notation in Figure~\ref{fig:lemma_26_proof}.

		We rescale the vector $v$ in such a way that its image $J_{g(y)} v = \left(v,Dg(y) v\right)$ is a unit vector. This implies in particular that $|v|\leq 1$: $1 = |J_{g(y)} v|^2 = |v|^2 + |Dg(y)(v)|^2\geq |v|^2$.
		Then, since $ \| (Dg- D\tilde{g})(y)\|_2 \leq  \delta$,
		\begin{align*}
			| J_{g(y)} v -J_{\tilde{g} (y) }  v | = | ((Dg- D\tilde{g})(y)) (v) |\leq \delta |v| \leq \delta. 
		\end{align*}
		Finally, since $\delta<1$ and $|J_{g(y)} v|=1$,
		$\angle (J_{g(y)} v, J_{\tilde{g} (y) }  v) \leq\arcsin \delta.$
		(We illustrate this inequality in Figure~\ref{fig:lemma_26_proof2}.)

		\begin{figure}[h!]
			\centering
			\includegraphics[width=0.4\textwidth]{lemma_26_proof2}
			\caption{Since $\delta<1$ and $|J_{g(y)} v|=1$, the angle $\angle (J_{g(y)} v, J_{\tilde{g} (y) }  v)$ cannot be larger than $\arcsin \delta.$}
			\label{fig:lemma_26_proof2}
		\end{figure}
		Thus, $\min_{w \in T_{(y, \tilde{g}(y))} G_{\tilde{g}} \setminus \{0\}}
		\angle (J_{g(y)} v,w) \leq\arcsin \delta$. Since the choice of the vector $v$ was arbitrary,
		\[
		\angle (T_{(y, g(y))} G_{g},T_{(y, \tilde{g}(y))} G_{\tilde{g}}) = \max_{v\in \R^n\setminus \{0\}} \min_{w \in T_{(y, \tilde{g}(y))} G_{\tilde{g}} \setminus \{0\}}
		\angle (J_{g(y)} v,w) \leq\arcsin \delta.
		\]
	\end{proof}

	\begin{proof}[Proof of Lemma~\ref{boundangleTangentSpace}] 
		Recall that $F = f + \psi \cdot(\varphi_\varepsilon \ast f - f)$. 
		Due to Theorem \ref{Th23abHirsch},
		\begin{align*}
			DF-Df = D(F-f) = D(\psi \cdot(\varphi_\varepsilon \ast f - f)) = D\psi \cdot (\varphi_\varepsilon \ast f-f ) + \psi  \cdot(\varphi_\varepsilon \ast D f- D f ),
		\end{align*}
		and thus at any point $y\in C,$ we can use bounds \eqref{eq:boundDpsi}, \eqref{eq:AssumptionSmoothing2}, and \eqref{eq:AssumptionSmoothing3}, and the fact that $|\psi| \leq 1$, to bound the norm of $(DF-Df)(y)$:
		\begin{align*} 
			\| (DF- Df)(y)\|_2 &\leq \|  D\psi(y)  \|_2 \cdot |  (\varphi_\varepsilon \ast f-f )(y)|  + |\psi(y)| \cdot \|  (\varphi_\varepsilon \ast D f- D f )(y)  \|_2
			\\
			&\leq  L_{\psi,D \psi} \cdot \varepsilon  + 1 \cdot  \varepsilon.
		\end{align*} 
		Lemma~\ref{lemma:angle_between_tangent_spaces} then directly yields that
		\[
		\angle (\Tan_{(y,f (y))}G_f , \Tan_{(y,F(y))} G_F) = \angle (T_{(y,f (y))}G_f , T_{(y,F(y))} G_F) \leq\arcsin \left( L_{\psi,D \psi}  \varepsilon  +  \varepsilon\right) .
		\] 
	\end{proof} 

	\begin{proof}[Proof of Corollary \ref{CorHD}] 
		\begin{figure}[h!]
			\centering
			\includegraphics[width=.4\textwidth]{cor_27_proof}
			\caption{Illustration of the settings in the proof of Corollary \ref{CorHD}.}
