		Let $A = \{T \in T_{p_1}G_f \mid |T| \leq 3R \}$ and $B = \{T \in T_{p_1'}G_F \mid |T| \leq 3R \}$, as illustrated in Figure~\ref{fig:cor_27_proof}.
		We first observe that
		\begin{align}\label{eq:cor_27_first_step}
			d_H(\mathcal{A}, \mathcal{B} )\leq |p_1'-p_1| + 	d_H(A,B).
		\end{align}	
		By assumption \eqref{eq:AssumptionSmoothing3}, and because $\abs{\psi}\leq 1$,
		\begin{align} 
			|p_1'-p_1| = | (y, F(y))- (y, f(y)) | = |F(y)-f(y) | = |\psi(y) \cdot (\varphi_{\varepsilon} \ast f-f)(y)| \leq 1 \cdot \varepsilon.
			\label{eq:trivialBoundPQ} 
		\end{align}
		To estimate the latter summand of equation~\eqref{eq:cor_27_first_step}, choose a vector $T \in T_{p_1}G_f \backslash \{0\}$, and let $T' \in  T_{p_1'}G_F \backslash \{0\}$ be a vector minimizing the angle between $T$ and $T_{p_1'}G_F$, that is, $\angle T, T' = \min_{U \in T_{p_1'}G_F \setminus \{0\}} \angle T,U$. Without loss of generality, we may assume that $T\in A$ and $T'\in B$. Then
		\begin{align*}
			d(T,B)\leq d(T,T') \leq 3R \:\angle (T, T') = 3R \min_{U \in T_{p_1'}G_F \setminus \{0\}}\angle (T,U),
		\end{align*}
		and thus, thanks to Lemma \ref{boundangleTangentSpace}, the one-sided Hausdorff distance $d(A,B)$ between $A$ and $B$ is bounded by
		\begin{align*}
			d(A,B) = \max_{T\in A\setminus \{0\}} d(T,B) \leq 3R \underbrace{\max_{T\in A\setminus \{0\}} \min_{U \in T_{p_1'}G_F \setminus \{0\}}\angle (T,U)}_{= \angle(T_{p_1}G_f,T_{p_1'}G_F)}\leq 3R\arcsin \left( L_{\psi,D \psi}  \varepsilon  +  \varepsilon\right).
