		Using the same argument, we obtain the same bound for the one-sided Hausdorff distance between $B$ and $A$. Thus, $d_H(A,B)\leq 3R\arcsin \left( L_{\psi,D \psi}  \varepsilon  +  \varepsilon\right).$ 

		To obtain the final bound, we use the fact that $ L_{\psi,D \psi}  \varepsilon  +  \varepsilon\leq 1$, and thus
		\[3R\arcsin \left( L_{\psi,D \psi}  \varepsilon  +  \varepsilon\right)\leq 3R\cdot  2\left( L_{\psi,D \psi}  \varepsilon  +  \varepsilon\right).\]
	\end{proof} 

		We need the following technical lemma to prove Proposition~\ref{prop:pointsFarAway}:
	\begin{lemma}\label{lemma:technical_rewrite}
		For two constants $R,\xi\in\R$, $R\neq 0$, the expression $\frac{1}{2R} + \xi$ can be rewritten as
		\[\frac{1}{2R}+\xi = \frac{1}{2R-z},\]
		with $z = \frac{4R^2\xi}{1+2R\xi}$.
	\end{lemma}
	\begin{proof}
		\begin{align*}
			&0 = 4R^2\xi - z - 2Rz\xi \nonumber\\
			\iff 		&0 = \frac{1}{2R} \left( 4R^2\xi - z - 2Rz\xi \right)  \nonumber\\
			\iff & 1 =   2R\xi - \frac{z}{2R} - z\xi   + 1 = \left(\frac{1}{2R}+\xi\right)\left(2R-z\right)
			\nonumber 
			\\
			\iff & \frac{1}{2R}+\xi = \frac{1}{2R-z}.
		\end{align*}
	\end{proof}


