	\begin{proof}[Proof of Lemma~\ref{lemma:Lipschitz_conts_psi}]
		Choose two points $x,y\in B(0,\sqrt{\delta R}/2)\cap T_\p\M$. Then
		\begin{align*} 
			|\psi(x)- \psi(y) | &=  \left | \psi_0 \left( \frac{ 8 x}{\sqrt{\delta R}} \right)  -  \psi_0 \left( \frac{ 8 y}{\sqrt{\delta R}} \right) \right|\\ 
			& \leq L_{\psi_0} \left | \frac{ 8 x}{\sqrt{\delta R}} - \frac{ 8 y}{\sqrt{\delta R}} \right | \\
			& = L_{\psi_0} \frac{ 8 }{\sqrt{\delta R}} \left |  x-y \right |.
		\end{align*} 
		For a vector $u \in \mathbb{R}^n$, the difference between directional derivatives $\partial_u \psi(x)- \partial_u \psi(y)$ can be bound as 
		\begin{align*} 
			|\partial_u \psi(x)- \partial_u \psi(y) |&=  \left |  \partial_u  \psi_0 \left( \frac{ 8 x}{\sqrt{\delta R}} \right)  - \partial_u   \psi_0 \left( \frac{ 8 y}{\sqrt{\delta R}} \right) \right| 
			\\
			&= \frac{ 8 }{\sqrt{\delta R}} \left|  \partial_u  \psi_0 ( x')|_{x'= \frac{ 8 x}{\sqrt{\delta R}}}     - \partial_u   \psi_0  (y')|_{y'=  \frac{ 8 y}{\sqrt{\delta R} }}  \right| 
			\tag{by the chain rule}
			\\
			&\leq \frac{ 8 }{\sqrt{\delta R}} L_{D\psi_0} \left | \frac{ 8 x}{\sqrt{\delta R}} - \frac{ 8 y}{\sqrt{\delta R}} \right |  
			\\
			&= \frac{64}{\delta R} L_{D\psi_0} |x-y|
		\end{align*} 
	\end{proof}

\begin{proof}[Proof of Lemma~\ref{lemma:final_approximation_distance_between_q'_and_tangent_space_of_p'}]
	We distinguish between two cases: $p'\notin B(\p, \sqrt{\delta R}/4)$ and $p'\in B(\p, \sqrt{\delta R}/4)$.


	\subparagraph{\emph{The case $p'\notin B(\p, \sqrt{\delta R}/4)$:}}
	If $p'\notin B(\p, \sqrt{\delta R}/4)$, then $p'=p$ and $ \Tan_{p'}\M' = \Tan_{p}\M$.

	If also $q'\notin B(\p, \sqrt{\delta R}/4)$, then $q'=q$, and Theorem~\ref{th418Federer} yields
	\[d(q', \Tan_{p'}\M') = d(q, \Tan_{p}\M) \leq \frac{\abs{p'-q'}^2}{2R}.\]

	If, on the other hand, $q'\in B(\p, \sqrt{\delta R}/4)$, then we distinghish two cases. Either $p'\in B(\p, \sqrt{\delta R}/2)$, in which case we apply Lemma~\ref{lem:ErrorLipschitzDer}, combined with the bound~\eqref{eq:Lipschitz_const_final_psi} on the Lipschitz constant of $\psi$ and its derivative, and the bound $\tfrac{1}{R-\delta}$ on the Lipschitz constant of $f$, and obtain
	\begin{align}\label{eq:prebound1Epsilon2}
		d(q', \Tan_{p'}\M')\leq\tfrac{1}{2}\left(3\cdot\frac{64}{\delta R} L_{D\psi_0}\rho + \frac{1}{R-\delta}\right)\abs{p'-q'}^2.
	\end{align}
	Or $p'\in B(\p, \sqrt{\delta R}/2)$, in which case $\abs{p'-q'}\geq \sqrt{\delta R}/4$. We approximate
	\begin{align*}
		d(q', \Tan_{p'}\M')&\leq \abs{q'-q} + d(q, \Tan_{p}\M) \leq \abs{q'-q}\cdot\frac{\abs{p'-q'}^2}{\abs{p'-q'}^2} +\frac{\abs{p'-q'}^2}{2R}\\
		&\leq \abs{p'-q'}^2 \left(\frac{1}{2R}+\frac{\abs{q'-q}}{\tfrac{\delta R}{16}}\right) = \abs{p'-q'}^2 \left(\frac{1}{2R}+\frac{16\abs{q'-q}}{\delta R}\right).
	\end{align*}
	At the same time, due to the definition \eqref{eq:smoothed_mfld_function} of $F$, and inequality \eqref{eq:AssumptionSmoothing1},
	\begin{align*}
		\abs{q'-q} =\abs{F(y)-f(y)}\leq \psi(y) \cdot \abs{(\varphi_\rho  \ast f - f)(y) }\leq\rho.
	\end{align*}
	Thus, $d(q', \Tan_{p'}\M')\leq  \abs{p'-q'}^2 \left(\frac{1}{2R}+\frac{16\rho}{\delta R}\right)$.
	Finally, we apply Lemma~\ref{lemma:technical_rewrite} with $\xi = \frac{16\rho}{\delta R}$:
	\begin{align*}
		\frac{1}{2R}+\frac{16\rho}{\delta R} = \frac{1}{2R-\frac{4R^2\xi}{1+2R\xi}} = \frac{1}{2R-2R\frac{32\rho}{\delta+32\rho}} = \frac{1}{2R\cdot\frac{\delta}{\delta+32\rho}}.
	\end{align*}
	Hence,
	\begin{align}\label{eq:prebound3Epsilon2}
		d(q', \Tan_{p'}\M')\leq \tfrac{1}{2}\frac{\delta+32\rho}{\delta R} \abs{p'-q'}^2.
	\end{align}
	%		{\color{red} Because the graph of a function from the tangent space to the normal space restricted to a ball of radius $c\delta$, with $c$ some constant corresponds to a slightly larger ball in the ambient space $\mathbb{R}^d$. This difference goes to zero as $\delta$ tends to zero, thanks to Theorem \ref{th418Federer}. Moreover we built in a factor two safety margin for this reason. 
		%			%We note that the Lipschitz constants of $\psi$ and its derivative are bounded by $\frac{8}{\sqrt{\tilde{\varepsilon}R}} L_{\psi_0}$ and $\frac{64}{\tilde{\varepsilon}R} L_{D\psi_0}$. %where $L_{\psi_0}$ and $L_{D\psi_0}$ are the Lipschitz constants and Lipschitz constants of the derivative of the function $\psi_0$, a partition of unity function that is $1$ on the unit ball and zero outside a ball of radius $2$. 
		%			%We can assume without loss of generality (by decreasing $\tilde{\varepsilon}$ if necessary) that $\frac{8}{\sqrt{\tilde{\varepsilon}R}} L_{\psi_0}\leq \frac{64}{\tilde{\varepsilon}R} L_{D\psi_0}$. 
