	\subparagraph{\emph{The case $p'\in B(\p, \sqrt{\delta R}/4)$:}}
	At first assume that $q'\in B(\p, \sqrt{\delta R}/2)$. Then due to Lemma~\ref{lem:ErrorLipschitzDer}, combined with the bound~\eqref{eq:Lipschitz_const_final_psi} on the Lipschitz constant of $\psi$ and its derivative, and the bound $\tfrac{1}{R-\delta}$ on the Lipschitz constant of $f$,
	\begin{align*}
		d(q', \Tan_{p'}\M')\leq\tfrac{1}{2}\left(3\cdot\frac{64}{\delta R} L_{D\psi_0}\rho + \frac{1}{R-\delta}\right)\abs{p'-q'}^2.\tag{\ref{eq:prebound1Epsilon2}}
	\end{align*}

	Finally, assume that $q'\notin B(\p, \sqrt{\delta R}/2)$. Then $q'=q$ and, necessarily, $\abs{q'-p'}\geq \sqrt{\delta R}/4$.
	Then Proposition~\ref{prop:pointsFarAway}, with $\beta = \sqrt{\delta R}/4$, yields
	\begin{align}\label{eq:prebound2Epsilon2}
		d(q' , \Tan_{p'} \M')   \leq  \frac{|p'-q'|^2}{2R'}
	\end{align}
	with 
	\begin{align}  R'= 
		\frac{R}{1+\frac{3\cdot64\rho}{\delta}\left(\tfrac{64}{\delta}L_{D\psi_0}+R+1\right)}.
		\nonumber
	\end{align}

	\subparagraph{Merging the bounds together}
	By combining the bounds \eqref{eq:prebound1Epsilon2}, \eqref{eq:prebound3Epsilon2}, and \eqref{eq:prebound2Epsilon2}, we conclude that 
	\begin{align*}
		d(q' , \Tan_{p'} \M')   \leq  \frac{|p'-q'|^2}{2R}\cdot \Omega,
	\end{align*}
	with 
	\begin{align*}
		\Omega = \max\left\{ 1+32\tfrac{\rho}{\delta}, 3\cdot 64 L_{D\psi_0}\tfrac{\rho}{\delta} + \tfrac{1}{1-\tfrac{\delta}{R}}, 1+ 3\cdot 64\tfrac{\rho}{\delta}\left(\tfrac{64}{\delta}L_{D\psi_0} + R+ 1\right) \right\}.  
	\end{align*}
	Moreover, the first term in the expression $\Omega$ is smaller than the last: 
	\begin{align*}
		1+32\tfrac{\rho}{\delta}\leq 1+ 32\tfrac{\rho}{\delta} \cdot 6 + 64\tfrac{\rho}{\delta}\left(\tfrac{64}{\delta}L_{D\psi_0} + R\right),
	\end{align*} and thus
	\begin{align*}
		\Omega = \max\left\{3\cdot 64 L_{D\psi_0}\tfrac{\rho}{\delta} + \tfrac{1}{1-\tfrac{\delta}{R}}, 1+ 3\cdot 64\tfrac{\rho}{\delta}\left(\tfrac{64}{\delta}L_{D\psi_0} + R+ 1\right) \right\}.  
	\end{align*}
\end{proof}



