\section{Deriving the effective number of bits (ENOB) of analog computation from the mutual information between analog and digital computation}
% Derivation of ENOB via mutual information
\subsection{Noisy analog inner product engine}
Let $\mathbf{w},\mathbf{x}$ be vectors from $\mathbb{R}^d$ whose components are individually independently drawn from arbitrary mean-zero probability distributions. Consider their digital inner product
\[
y_{\mathrm{digital}} \;=\; \mathbf{w}\,\cdot\,\mathbf{x},
\]
and the noisy analog counterpart
\[
y_{\mathrm{analog}} \;=\; \mathbf{w}\,\cdot\,\mathbf{x} \;+\; n,
\]
where \(n\) is additive Gaussian noise, $n \;\sim\; \mathcal{N}(0,\sigma_n^2)$.

We wish to quantify how many bits of information about \(y_{\mathrm{digital}}\) are contained in \(y_{\mathrm{analog}}\).  By definition, the mutual information between \(y_{\mathrm{digital}}\) and \(y_{\mathrm{analog}}\) is
\[
I\bigl(y_{\mathrm{digital}};\,y_{\mathrm{analog}}\bigr)
\;=\;
H\bigl(y_{\mathrm{analog}}\bigr)
\;-\;
H\bigl(y_{\mathrm{analog}}\,\bigm|\,y_{\mathrm{digital}}\bigr).
\]
Because once \(y_{\mathrm{digital}} = \mathbf{w}\cdot\mathbf{x}\) is known, the only remaining uncertainty in \(y_{\mathrm{optical}}\) is the Gaussian noise \(n\), we have
\[
H\bigl(y_{\mathrm{analog}} \,\bigm|\, y_{\mathrm{digital}}\bigr)
\;=\;
H(n)
\;=\;
\frac{1}{2}\,\log_{2}\bigl(2\pi e\,\sigma_n^2\bigr).
\]

To evaluate \(H\bigl(y_{\mathrm{analog}}\bigr)\), we note that \(\mathbf{w}\cdot\mathbf{x}\) is a sum of (not necessarily identically distributed) independent random variables and appeal to the Central Limit Theorem to obtain,
\[
\mathbf{w}\,\cdot\,\mathbf{x}
\;\sim\;
\mathcal{N}\bigl(0,\;\mathbb{E}[(\mathbf{w}\cdot\mathbf{x})^2]\bigr),
\]
so that
\begin{align}
y_{\mathrm{analog}}
\;=&\;
\underbrace{\mathbf{w}\,\cdot\,\mathbf{x}}_{\mathcal{N}(0,\;\mathbb{E}[(\mathbf{w}\cdot\mathbf{x})^2])}
\;+\;
\underbrace{n}_{\mathcal{N}(0,\;\sigma_n^2)}
\;\\
&\sim\;
\mathcal{N}\Bigl(0,\;\mathbb{E}[(\mathbf{w}\cdot\mathbf{x})^2] \;+\; \sigma_n^2\Bigr).
\end{align}
Hence its differential entropy is
\[
H\bigl(y_{\mathrm{analog}}\bigr)
\;=\;
\frac{1}{2}\,\log_{2}\!\Bigl(2\pi e\,\bigl[\mathbb{E}[(\mathbf{w}\cdot\mathbf{x})^2] + \sigma_n^2\bigr]\Bigr).
\]
Putting these pieces together gives
\[
I\bigl(y_{\mathrm{digital}};\,y_{\mathrm{analog}}\bigr)
\;=\;
\frac{1}{2}\,\log_{2}\!\Bigl(1 \;+\; \frac{\mathbb{E}[(\mathbf{w}\cdot\mathbf{x})^2]}{\sigma_n^2}\Bigr).
\]
By defining the signal‐to‐noise ratio \(\mathrm{SNR} = \frac{\mathbb{E}[(\mathbf{w}\cdot\mathbf{x})^2]}{\sigma_n^2}\), we obtain the result
\[
I\bigl(y_{\mathrm{digital}};\,y_{\mathrm{analog}}\bigr)
\;=\;
\frac{1}{2}\,\log_{2}\bigl(1 + \mathrm{SNR}\bigr).
\]
Finally, identifying this mutual information (in bits) with the effective number of bits (ENOB) of the analog computation yields
\[
\mathrm{ENOB}
\;=\;
I\bigl(y_{\mathrm{digital}};\,y_{\mathrm{analog}}\bigr)
\;=\;
\frac{1}{2}\,\log_{2}\bigl(1 + \mathrm{SNR}\bigr).
\]

\subsection{Noisy analog diode ring mixer}
We note in this section that we do not have an exact analog inner product engine in our system; instead our system performs
\begin{align}
y_{\mathrm{analog}} \;=\; f(\mathbf{w}+n_w,\mathbf{x}+n_x) \;+\; n    
\end{align}
where \(n, n_w, n_x\) are Gaussian noise random variables. To fit this into the model we discussed in the previous subsection, we rewrite his equation as:
\begin{align}
y_{\mathrm{analog}} \;&=\; \mathbf{w}\,\cdot\,\mathbf{x}+\left(f(\mathbf{w}+n_w,\mathbf{x}+n_x)-\mathbf{w}\,\cdot\,\mathbf{x} \;+\; n\right)\\
&\approx\mathbf{w}\,\cdot\,\mathbf{x}+n'\notag
\end{align}
where $n'$ captures the total discrepancy between the true digital inner product and the analog inner product due to both noise and functional differences. To compute the ENOB, we will continue to use the formula
\[
I\bigl(y_{\mathrm{digital}};\,y_{\mathrm{analog}}\bigr)
\;=\;
\frac{1}{2}\,\log_{2}\bigl(1 + \mathrm{SNR}\bigr).
\]
with the same signal definition $S=\mathbb{E}\left[\left(\mathbf{w}\cdot\mathbf{x}\right)^2\right]$ but with the noise now defined as $N=\mathbb{E}[n'^2]$. We used this definition to compute the variation of the inner product ENOB with client and server power in Fig. 2 in the main text. 

\section{SNR and energy per MAC of the RF inner product engine}\label{app:SNR}

\subsection{SNR estimation}
We shall estimate the SNR of the RF mixer by working at low voltages where the noisy RF mixing process can be approximated by:
\begin{align*}
    y_{\text{RF}}(t) = \frac{e}{4kT} \cdot \left[w(t)+n_w(t)\right] \cdot \left[x(t)+n_x(t)\right] + n_y(t).
\end{align*}
In our implementation, the activations $x_i$ \iffalse\tingjun{inference request? why activation?}\fi and the weights $w_i$ are encoded into orthonormal frequency basis, thus yielding the following noisy inner product model:
\begin{align}
    y=\frac{e}{4kT}\frac{1}{\sqrt{N}}\ls\sum_i\lp w_i+n^{(w)}_i\rp\lp x_i+n^{(x)}_i\rp\rs+n^{(y)}
\end{align}
\iffalse\tingjun{what is this equation about? not sure what's the connection to the previous equation.}\fi
The components $w_i$ and $x_j$ are drawn independently from normal distributions \iffalse\tingjun{why? for benchmarking or dataset evaluation?}\fi as mentioned in the main text. The noise components $n^{(w)}_i,n^{(x)}_j,n^{(y)}$ are all assumed to be independently drawn from normal distributions of mean $0$ and variance $4kTR\Delta f$. 

We note that we have a peculiar situation where the signal is produced by an underlying random process and the noise on top of it is also produced by a different underlying random process. We define the SNR for this kind of situation in the following way. We first compute the squared average output $\la y\ra_n^2$ for a given $w,x$, but averaged over all the noise components:
\begin{align}
    \la y\ra_n^2=\lp\frac{e}{4kT}\rp^2\frac{1}{N}\lp\sum_iw_ix_i\rp^2=\lp\frac{e}{4kT}\rp^2\frac{1}{N}\lp\mathbf w\cdot\mathbf x\rp^2
\end{align}
The quantity above will be treated as the ``signal strength" for the given $w,x$. The ``noise strength" for the same $w,x$ is given by the variance of $y$ computed over the noise random variables:
\begin{align}
    \text{Var}_n(y)=&\lp\frac{e}{4kT}\rp^2\frac{1}{N}\ls\sum_i\text{Var}_n\ls\lp w_i+n^{(w)}_i\rp\lp x_i+n^{(x)}_i\rp\rs\rs\\
    &+\text{Var}_n\lp n^{(y)}\rp\notag\\
    =&\lp\frac{e}{4kT}\rp^2\frac{1}{N}\ls\sum_i\lp\sigma^2_wx_i^2+\sigma^2_xw_i^2+\sigma^2_w\sigma^2_x\rp\rs+\sigma^2_y
\end{align}
Now, we shall define the signal and noise strengths for our overall setup as the average of $\la y\ra_n^2$ and $\text{Var}_n(y)$ over all choices of $w,x$. For this purpose, we assume that the $w_i, x_i$ have variances $M_w^2, M_x^2$ respectively:
\begin{align}
    S&=\la\la y\ra_n^2\ra_{w,x}=\lp\frac{e}{4kT}\rp^2M_w^2M_x^2d/N\\
    \text{Noise}&=\la\text{Var}_n(y)\ra_{w,x}\\
    &=\lp\frac{e}{4kT}\rp^2\frac{d}{N}\lp M_x^2\sigma^2_w+M_w^2\sigma^2_x+\sigma^2_w\sigma^2_x\rp+\sigma^2_y
\end{align}
The SNR of our inner product engine is then:
\begin{align}
    \text{SNR}=\frac{S}{\text{N}}=\frac{\lp\frac{e}{4kT}\rp^2M_w^2M_x^2d/N}{\lp\frac{e}{4kT}\rp^2\frac{d}{N}\lp M_x^2\sigma^2_w+M_w^2\sigma^2_x+\sigma^2_w\sigma^2_x\rp+\sigma^2_y}
\end{align}
For encoding in the orthonormal Fourier domain, we have $\sigma_w^2=\sigma_x^2=\sigma_y^2=4kTR\Delta f$, where we chose to keep the total bandwidth constant even when the input size is varied. Since $d$ and $N$ are essentially proportional to one another, the formula predicts that the SNR is independent of $d$ for $d\gtrsim10$.

\subsection{Energy per MAC}
The total energy $E_x$ of the $x(t)$ waveform generated by the client is:
\begin{align}
    E_x=\int dt \frac{x^2(t)}{R}\approx\Delta t\sum_n\frac{x^2[n]}{R} 
\end{align}
Since we encode our inputs in the orthonormalized Fourier domain, Parseval's theorem states that $\sum_n|x[n]|^2=\sum_k|X[k]|^2$. Since the $d$ $X[k]$s that correspond to the activation vector each have variance $M_x^2$, the client energy per MAC is:
\begin{align}
    \frac{E_x}{d}\approx\frac{\Delta t}{d}\sum_k\frac{|X[k]|^2}{R}\approx \Delta t\frac{M_x^2}{R}
\end{align}
The signal energy per MAC is:
\begin{align}
    \frac{E_w}{d}\approx\frac{\Delta t}{d}\sum_k\frac{|W[k]|^2}{R}\approx \Delta t\frac{M_w^2}{R}
\end{align}


