\section{Diode ring small signal derivation}
\begin{figure}[ht!]
\begin{centering}
\includegraphics[scale=0.32]{Figures/DiodeRingNew.pdf}
\par\end{centering}
     \caption{The passive diode ring mixer 
     }
 \label{results}
 \end{figure}
% \begin{figure}[ht!]
% \begin{centering}
% \includegraphics[scale=0.5]{Figures/diodering.pdf}
% \par\end{centering}
%      \caption{The quadratic approximation for diodes in the diode mixer 
%      }
%  \label{results}
%  \end{figure}

 We first write out the characteristic equation of the diode, and then expand it up to the second order in Taylor series.
 \begin{align}
     I&=I_0\lp e^{\frac{qV}{kT}}-1\rp=I_0\lp e^{\frac{V}{V_T}}-1\rp\\
     &=I_0\frac{V}{V_T}+I_0\frac{V^2}{2V_T^2}=GV+G_NV^2
 \end{align}
where we set $V_T:=kT/q$. Denoting the potentials at the four corners of the ring by $A, B, C, D$, and writing out the voltage equations implied by the circuit connectivity, we get:
\begin{align}
    A-C&=V_{\text{LO}}\\
    A+C&=0\\
    D-B&=V_{\text{RF}}\\
    I_A&=I_C,\ I_B=I_D\\
    V_{\text{IF}}&=(B+D)/2
\end{align}
The current going into $A$ is:
 \begin{align}
     I_A =&G\lp n_1+n_4+V_{\text{LO}}-2B-V_{\text{RF}}\rp\\
     &+G_N\lp -V_{\text{RF}}^2-2BV_{\text{RF}}+V_{\text{RF}}V_{\text{LO}}\rp
 \end{align}
 \begin{align}
     I_A =G\lp V_{\text{LO}}-2B-V_{\text{RF}}\rp+G_N\lp -V_{\text{RF}}^2-2BV_{\text{RF}}+V_{\text{RF}}V_{\text{LO}}\rp
 \end{align}
 while the current leaving $C$ is:
 \begin{align}
     I_C =&G\lp n_2+n_3+ V_{\text{LO}}+2B+V_{\text{RF}}\rp\\
     &+G_N\lp -V_{\text{RF}}^2-2BV_{\text{RF}}-V_{\text{RF}}V_{\text{LO}}\rp
 \end{align}
 \begin{align}
     I_C =G\lp V_{\text{LO}}+2B+V_{\text{RF}}\rp+G_N\lp -V_{\text{RF}}^2-2BV_{\text{RF}}-V_{\text{RF}}V_{\text{LO}}\rp
 \end{align}
Setting $I_A=I_C$, we get:
\begin{align}
    B&=-\frac{V_{\text{RF}}}{2}+\frac{G_N}{2G}V_{\text{RF}}V_{\text{LO}}\\
    D&=\frac{V_{\text{RF}}}{2}+\frac{G_N}{2G}V_{\text{RF}}V_{\text{LO}}
\end{align}
The output we are interested in, $V_{\text{IF}}$, is then:
\begin{align}
    V_{\text{IF}}&=\frac{G_N}{2G}V_{\text{RF}}V_{\text{LO}}+\frac{n_1+n_4-n_2-n_3}{4}\\
    &=\frac{1}{4V_T}V_{\text{RF}}V_{\text{LO}}+\frac{n_1+n_4-n_2-n_3}{4}
\end{align}
\begin{align}
    V_{\text{IF}}=\frac{G_N}{2G}V_{\text{RF}}V_{\text{LO}}=\frac{1}{4V_T}V_{\text{RF}}V_{\text{LO}}\approx 10V_{\text{RF}}V_{\text{LO}}
\end{align}

\section{Diode ring exact derivation}
The diode's characteristic:
\begin{align}
     I&=I_0\lp e^{\frac{qV}{kT}}-1\rp=I_0\lp e^{\frac{V}{V_T}}-1\rp
\end{align}
where we set $V_T:=kT/q$. Denoting the potentials at the four corners of the ring by $A, B, C, D$, and writing out the voltage equations implied by the circuit connectivity, we get:
\begin{align}
    A-C&=V_{\text{LO}}\\
    A+C&=0\\
    D-B&=V_{\text{RF}}\\
    I_A&=I_C,\ I_B=I_D\\
    V_{\text{IF}}&=(B+D)/2
\end{align}
The current going into $A$ is:
 \begin{align}
     I_A =I_0\lp e^{\frac{V_{lo}/2-B}{V_T}}-e^{\frac{B+V_{rf}-V_{lo}/2}{V_T}}\rp
 \end{align}
 while the current leaving $C$ is:
 \begin{align}
     I_C =I_0\lp e^{\frac{V_{lo}/2+B}{V_T}}-e^{\frac{-B-V_{rf}-V_{lo}/2}{V_T}}\rp
 \end{align}
Setting $I_A=I_C$, we get:
\begin{align}
    B&=\frac{V_T}{2}\ln{\lp\frac{e^{\frac{V_{lo}}{2V_T}}+e^{\frac{-V_{rf}-V_{lo}/2}{V_T}}}{e^{\frac{V_{lo}}{2V_T}}+e^{\frac{V_{rf}-V_{lo}/2}{V_T}}}\rp}
\end{align}
Then, the output is:
\begin{align}
V_{if}=\frac{V_{rf}}{2}+\frac{V_T}{2}\ln{\lp\frac{e^{\frac{V_{lo}}{V_T}}+e^{\frac{-V_{rf}}{V_T}}}{e^{\frac{V_{lo}}{V_T}}+e^{\frac{V_{rf}}{V_T}}}\rp}
\end{align}

\section{Derivation of the second-order expansion}

We want to show that
\[
z \;=\; \frac{y}{2} \;+\; \frac{VT}{2}\,\ln\!\Bigl(\tfrac{e^{x/VT}+e^{-y/VT}}{e^{x/VT}+e^{y/VT}}\Bigr)
\]
reduces, up to second order in \(\frac{x}{VT}\) and \(\frac{y}{VT}\), to
\[
z \;=\; \frac{x\,y}{4\,VT}.
\]

\subsection*{1. Introduce dimensionless parameters}

Define
\[
\alpha \;=\; \frac{x}{VT}, 
\quad
\beta \;=\; \frac{y}{VT}.
\]
Then
\[
z 
\;=\;
\frac{y}{2}
\;+\;
\frac{VT}{2}
\;\ln\!\Bigl(
  \frac{e^\alpha + e^{-\beta}}{\,e^\alpha + e^\beta\,}
\Bigr).
\]
We focus on the argument of the logarithm:
\[
\ln\!\Bigl(
  \frac{e^\alpha + e^{-\beta}}{e^\alpha + e^\beta}
\Bigr)
\;=\;
\ln\!\bigl(\,N/D\bigr),
\]
where
\[
N \;=\; e^\alpha + e^{-\beta},
\quad
D \;=\; e^\alpha + e^\beta.
\]

\subsection*{2. Expand exponentials to second order}

For small \(\alpha\) and \(\beta\), we use the expansions:
\[
\begin{aligned}
e^\alpha &\approx 1 + \alpha + \tfrac12\,\alpha^2,\\
e^\beta  &\approx 1 + \beta  + \tfrac12\,\beta^2,\\
e^{-\beta} &\approx 1 - \beta + \tfrac12\,\beta^2.
\end{aligned}
\]
Hence, up to second order,
\[
\begin{aligned}
N &= e^\alpha + e^{-\beta}
\;\approx\;
\bigl(1 + \alpha + \tfrac12\,\alpha^2\bigr)
\;+\;
\bigl(1 - \beta + \tfrac12\,\beta^2\bigr)
\\[6pt]
&= 2 + (\alpha - \beta) + \tfrac12(\alpha^2 + \beta^2),
\\[8pt]
D &= e^\alpha + e^\beta
\;\approx\;
\bigl(1 + \alpha + \tfrac12\,\alpha^2\bigr)
\;+\;
\bigl(1 + \beta + \tfrac12\,\beta^2\bigr)
\\[6pt]
&= 2 + (\alpha + \beta) + \tfrac12(\alpha^2 + \beta^2).
\end{aligned}
\]
For compactness, set
\[
A \;=\; \alpha + \beta,
\quad
B \;=\; \alpha - \beta,
\quad
Q \;=\; \tfrac12\,(\alpha^2 + \beta^2).
\]
Then
\[
N = 2 + B + Q,
\quad
D = 2 + A + Q.
\]
We want the ratio
\[
R \;=\; \frac{N}{D}
\;=\;
\frac{2 + B + Q}{\,2 + A + Q\,}
\]
only up to second order in \(\alpha\) and \(\beta\).

\subsection*{3. Expand \(\frac{N}{D}\) to second order}

Factor out 2:
\[
R 
\;=\; 
\frac{2 \bigl(1 + \tfrac{B+Q}{2}\bigr)}{\,2 \bigl(1 + \tfrac{A+Q}{2}\bigr)}
\;=\;
\frac{1 + X}{\,1 + Y},
\]
where
\[
X = \frac{B + Q}{2},
\quad
Y = \frac{A + Q}{2}.
\]
For small \(X, Y\), we expand:
\[
\frac{1 + X}{1 + Y}
\;=\;
1 + (X - Y) - \frac{(X - Y)^2}{2} + \cdots,
\]
but it is sufficient just to keep track of terms through second order.  After collecting terms carefully, one finds
\[
R 
\;=\;
1 + \bigl(-\beta + \tfrac{\alpha\,\beta}{2} + \tfrac{\beta^2}{2}\bigr) 
+ \cdots
\;=\;
1 + r,
\]
where
\[
r
\;=\;
-\,\beta 
\;+\; 
\frac{\alpha\,\beta}{2}
\;+\;
\frac{\beta^2}{2}
\;+\;\cdots.
\]

\subsection*{4. Expand \(\ln(R)\) to second order}

Since \(R = 1 + r\) with \(r\) small,
\[
\ln(R)
\;=\;
\ln(1 + r)
\;=\;
r - \frac{r^2}{2} + \cdots.
\]
Here \(r\) itself is already first- plus second-order, so
\[
r^2 \approx \beta^2
\quad (\text{since the first-order part of }r\text{ is }-\beta).
\]
Thus,
\[
\ln(R)
\;=\;
\Bigl(-\beta + \frac{\alpha\,\beta}{2} + \frac{\beta^2}{2}\Bigr)
\;-\;
\frac{\beta^2}{2}
\;+\;\cdots
\;=\;
-\,\beta 
\;+\;
\frac{\alpha\,\beta}{2}
\;+\;\cdots.
\]
Recalling \(\beta = \frac{y}{VT}\) and \(\alpha = \frac{x}{VT}\):
\[
\ln(R)
\;\approx\;
-\frac{y}{VT}
\;+\;
\frac{x\,y}{2\,(VT)^2}.
\]

\subsection*{5. Substitute back into \(z\)}

We have
\[
z 
\;=\;
\frac{y}{2}
\;+\;
\frac{VT}{2}
\;\ln(R).
\]
Therefore,
\[
\frac{VT}{2}\,\ln(R)
\;=\;
\frac{VT}{2}
\bigl(
-\tfrac{y}{VT} + \tfrac{x\,y}{2\,(VT)^2}
\bigr)
\;=\;
-\frac{y}{2} 
\;+\;
\frac{x\,y}{4\,VT}.
\]
Hence
\[
z 
\;=\;
\underbrace{\frac{y}{2}}_{\text{first part}}
\;+\;
\underbrace{\Bigl(-\tfrac{y}{2} + \tfrac{x\,y}{4\,VT}\Bigr)}_{\frac{VT}{2}\,\ln(R)}
\;=\;
\frac{x\,y}{4\,VT}.
\]
This completes the derivation.

