\begin{algorithm}[ht]
\caption{AndroIDS: FL based system call drive IDS%Federated Learning with TF-IDF-GRU and FedAvg
\\ \small \textbf{Server and Client Side}}
\begin{algorithmic}[1]
\REQUIRE Initial global model $\mathcal{M}_g^0$, client set $\mathcal{C}$, TF-IDF transformer $\mathcal{T}$, window size $W$, stride $S$, noise factor $\epsilon$, number of rounds $R$
\ENSURE Final global model $\mathcal{M}_g^R$
\FOR{round $r = 1$ to $R$}
    \STATE Server selects a subset of clients $\mathcal{S} \subseteq \mathcal{C}$
    \FOR{each client $c \in \mathcal{S}$ in parallel}
        \STATE Send current global model weights $\mathcal{W}_r$ to client $c$
        \STATE Client loads local system call logs $\mathcal{D}_c$
        \STATE Remove timestamps and tokenize syscalls using $\mathcal{T}$
        \STATE Apply sliding window with size $W$ and stride $S$
        \STATE Inject Gaussian noise $\mathcal{N}(0, \epsilon^2)$ into input vectors
        \STATE Initialize GRU model with weights $\mathcal{W}_r$
        \STATE Train model locally on preprocessed data for $E$ epochs
        \STATE Send updated model weights $\mathcal{W}_c^r$ and sample count $n_c$ to server
    \ENDFOR
    \STATE Server aggregates using FedAvg:
    \STATE \quad $\mathcal{W}_{r+1} \leftarrow \left(\sum n_c \cdot \mathcal{W}_c^r \right) \big/ \left(\sum n_c\right)$
    \STATE Update global model: $\mathcal{W}_r \leftarrow \mathcal{W}_{r+1}$
\ENDFOR
\RETURN Final global model $\mathcal{W}_R$
\end{algorithmic}
\label{androids}
\end{algorithm}
