    We remark that every graph admits a tree-parallel decomposition. To see this, observe that we can always take two adjacent vertices $s,t \in V$, and do a parallel decomposition with $E_1 = N(v) \cap N(w)$, and $E_2 = E \setminus E_1$. If this leads to $E_2$ being empty, then we can decompose $E_1$ into single edges with a parallel decomposition. Inductively, then, this means that we can always iterate this process until we have decomposed the entire graph into subsets that just contain a single edge. Moreover, we can always upper bound the depth of the tree-parallel decomposition by $|E|$.

    We now proceed to show how these decompositions relate to the circulation space.

    \begin{lemma}[Tree decomposition of the circulation space]
        \label{lem:tree-decomposition}
        Let $G = (V,E)$ be a graph with resistances $r : E \to \R_{>0}$. Let $E_1, \dots, E_k \subseteq E$ such that $G|_{E_1}, \dots, G|_{E_k}$ is a tree decomposition of $G$. Then,
        \[\mathcal{C}_{G,r} = \bigoplus_{j=1}^k \mathcal{C}_{G|_{E_j},r|_{E_j}}.\]
    \end{lemma}

    \begin{proof}
        The ``$\supseteq$''-direction is clear, so it remains to prove the ``$\subseteq$''-direction. To that end, let $f : E \to \R$ be a circulation on $G$. For every edge $\{v_{j,j'},v_{j,j''}\} = e' \in E'$, we can compute the net flow over that edge as
        \[f_{e'} = \sum_{e \in E_j \cap N^+(v_{j,j'})} f_e - \sum_{e \in E_j \cap N^-(v_{j,j'})} f_e.\]
        This defines a flow on $G'$, and since the net-flow on every vertex $v \in V$ is zero, so is the flow on all the vertices $v \in V'$. But as $G'$ is a tree, that means that $f_{e'} = 0$ for all $e' \in E'$. Thus, for every edge $\{v_{j,j'},v_{j,j''}\} = e' \in E'$, we have
        \[\sum_{e \in E_j \cap N^+(v_{j,j'})} - \sum_{e \in E_j \cap N^-(v_{j,j'})} = 0,\]
        and so we observe for all $j \in [k]$ that $f|_{E_j}$ is a circulation in $G|_{E_j}$. Since the $E_j$'s form a partition of $E$, we can write $f$ as a linear combination of circulations in $G|_{E_j}$.
    \end{proof}

    \begin{lemma}[Parallel decomposition of the circulation space]
        \label{lem:parallel-decomposition}
        Let $G = (V,E)$ be a graph with resistances $r : E \to \R_{>0}$. Let $E_1, \dots, E_k \subseteq E$, such that $G|_{E_1}, \dots, G|_{E_k}$ is a parallel decomposition of $G$. Let $\mathcal{E} : \C^k \to \H_E = \Span\{\ket{e} : e \in E\}$, that for all $j \in [k]$ performs the mapping
        \begin{equation}
            \label{eq:parallel-embedding}
            \mathcal{E}: \ket{j}\ket{\bot} \mapsto \ket{j}\frac{\ket{f_j}}{\norm{\ket{f_j}}}, \qquad \text{with} \qquad \ket{f_j} = \ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}} \in \C^{E_j}.
        \end{equation}
        Then,
        \begin{equation}
            \label{eq:parallel-decomposition}
            \mathcal{C}_{G,r} = \mathcal{E}\left(\mathcal{C}'\right) \oplus \bigoplus_{j=1}^k \mathcal{C}_{G|_{E_j},r|_{E_j}}, \quad \text{with} \quad \mathcal{C}' = \Span\left\{\ket{\psi}\right\}^{\perp}, \quad \text{and} \quad \ket{\psi} = \sum_{j=1}^k \frac{1}{\norm{\ket{f_j}}}\ket{j}.
        \end{equation}
    \end{lemma}

    \begin{proof}
        For the ``$\supseteq$''-direction, it is clear that $\mathcal{C}_{G|_{E_j},s,t,r|_{E_j}}$ is contained in $\mathcal{C}_{G,r}$. On the other hand, let $\sum_{j=1}^k f_j'\norm{\ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}}}\ket{j} = \ket{f'} \in \mathcal{C}'$. Then, we observe that
        \[0 = \bra{f'} \sum_{j=1}^k \frac{1}{\norm{\ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}}}}\ket{j} = \sum_{j=1}^k \frac{f_j'\norm{\ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}}}}{\norm{\ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}}}} = \sum_{j=1}^k f_j'.\]
        We find immediately that the flow is conserved at every node besides $s$ and $t$, and for $s$ we find
        \begin{align*}
            &\sum_{e \in N^+(s)} \bra{e}\frac{1}{\sqrt{r_e}} \mathcal{E}(\ket{f'}) - \sum_{e \in N^-(s)} \bra{e}\frac{1}{\sqrt{r_e}} \mathcal{E}(\ket{f'}) \\
            &\qquad = \sum_{j=1}^k \left[\sum_{e \in E_j \cap N^+(s)} \frac{1}{\sqrt{r_e}} f_j'(f^{\min}_{G|_{E_j},s,t,r|_{E_j|}})_e\sqrt{r_e} - \sum_{e \in E_j \cap N^-(s)} \frac{1}{\sqrt{r_e}} f_j'(f^{\min}_{G|_{E_j},s,t,r|_{E_j|}})_e\sqrt{r_e}\right] \\
            &\qquad = \sum_{j=1}^k f_j'\left[\sum_{e \in E_j \cap N^+(s)} (f^{\min}_{G|_{E_j},s,t,r|_{E_j|}})_e - \sum_{e \in E_j \cap N^-(s)} (f^{\min}_{G|_{E_j},s,t,r|_{E_j|}})_e\right] = \sum_{j=1}^k f_j' = 0.
        \end{align*}
        The same argument can be applied to $t$, and so $\mathcal{E}(\ket{f'}) \in \mathcal{C}_{G,r}$.

        For the ``$\subseteq$''-direction, let $f$ be a circulation on $G$. For all $j \in [k]$, we write
        \[f_j' = \sum_{e \in E_j \cap N^+(s)} f_e - \sum_{e \in E_j \cap N^-(s)} f_e.\]
        Since $f$ is a circulation, we have net-zero flow on all the nodes, so in particular on those besides $s$ and $t$. This means that the flow flowing from $s$ into $E_j$, i.e., $f_j'$, is the same as the flow from $E_j$ into $t$. As such, we observe that we have an $st$-flow through $E_j$ with total flow $f_j'$, and so we can write
        \[\ket{f|_{E_j}} - f_j'\ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}} \in \mathcal{C}_{G|_{E_j},r|_{E_j}}.\]
        As such, it remains to prove that $\sum_{j=1}^k f_j'\ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}} \in \mathcal{E}(\mathcal{C}')$, for which it suffices to prove that $\ket{f'} := \sum_{j=1}^k f_j'\norm{\ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}}}\ket{j} \in \mathcal{C}'$. We conclude by observing that
        \[\bra{f'} \sum_{j=1}^k \frac{1}{\norm{\ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}}}}\ket{j} = \sum_{j=1}^k \frac{f_j'\norm{\ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}}}}{\norm{\ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}}}} = \sum_{j=1}^k f_j' = 0.\qedhere\]
    \end{proof}

    We observe that the tree and parallel decompositions effectively split up the circulation space into several mutually orthogonal components, through which we can reflect individually. These decompositions can be useful to implement the reflection through the circulation space time-efficiently in the circuit model. We prove this in the following theorem.

    \begin{theorem}
        \label{thm:implementation-circuit-model}
        Let $G = (V,E)$ be a graph with resistances $r : E \to \R_{>0}$, and let $T$ be a tree-parallel decomposition of the circulation space of $G$, with depth $d$. For every $\ell \in [d]$, let $k_{\ell}$ be the maximum number of children of nodes in the $(\ell-1)$th vertex layer. We use a Hilbert space $\C^{[k_1] \cup \{\bot\}} \otimes \cdots \otimes \C^{[k_d] \cup \{\bot\}}$, with dimension $K = (k_1+1) \cdots (k_d+1)$.

        Every node $u$ in $T$ is connected to its root by a unique path. If $u$ is in the $\ell$th vertex layer, we write $u = (j_1, \dots, j_\ell)$, if $u$ is reached through starting at the root node and taking the $j_{\ell'}$th child at the $(\ell'-1)$th vertex layer, for all $\ell' \in [\ell]$. Moreover, since every leaf $u = (j_1, \dots, j_d)$ is uniquely labeled by a singleton $\{e\}$, we identify
        \[\ket{e} := \ket{j_1, \dots, j_d}.\]

        Next, let an internal node $u \in V$ be labeled by $E_u$, and let $u_1, \dots, u_k$ be its children, labeled by $E_{u_1}, \dots, E_{u_k}$. Suppose that $G|_{E_{u_1}}, \dots, G|_{E_{u_k}}$ is a parallel decomposition of $G|_{E_u}$, with source and sink nodes $s$ and $t$. For all $j \in [k]$, we write
        \[\ket{\psi_u} := \sum_{j=1}^k \frac{1}{\norm{\ket{f_{u,j}}}}\ket{j}, \qquad \text{with} \qquad \ket{f_{u,j}} := \ket{f^{\min}_{G|_{E_{u_j}}, s, t, r|_{E_{u_j}}}}.\]

        Now, for every $\ell \in [d]$, we write the operation $\mathcal{E}_{\ell}$ that for all $u = (j_1, \dots, j_{\ell-1})$ in the $(\ell-1)$th layer of $T$ acts for all $j \in [k]$,
        \[\mathcal{E}_{\ell} : \ket{j_1,\dots,j_{\ell-1}}\ket{j}\ket{\bot}^{\otimes(d-\ell)} \mapsto \begin{cases}
            \ket{j_1,\dots,j_{\ell-1}}\ket{j}\ket{\bot}^{\otimes(d-\ell)}, & \text{if } u \text{ is the root of a tree decomposition}, \\
            \ket{j_1,\dots,j_{\ell-1}}\ket{j}\frac{\ket{f_{u,j}}}{\norm{\ket{f_{u,j}}}}, & \text{otherwise}.
        \end{cases}\]

        Similarly, for all $\ell \in [d]$, we write $U_{\ell}$ as the operation that for all $u = (j_1, \dots, j_{\ell-1})$ in the $(\ell-1)$th layer of $T$ acts as
        \[U_{\ell} : \ket{j_1,\dots,j_{\ell-1}}\ket{\bot}\ket{\bot}^{\otimes(d-\ell)} \mapsto \begin{cases}
            \ket{j_1,\dots,j_{\ell-1}}\ket{\bot}\ket{\bot}^{\otimes(d-\ell)}, & \text{if } u \text{ is the root of a tree decomposition}, \\
            \ket{j_1, \dots, j_{\ell-1}}\ket{\psi_u}\ket{\bot}^{\otimes(d-\ell)}, & \text{otherwise}.
        \end{cases}\]

        Then, we can implement the reflection through $\mathcal{C}_{G,r}$ in the circuit model with two calls to all the $\mathcal{E}_{\ell}$'s and $U_{\ell}$'s, and $\widetilde{O}(d\log(K))$ auxiliary elementary gates.
    \end{theorem}

    \begin{proof}
        We prove that we can implement the reflection through $\mathcal{C}_{G,r}$ by
        \[R_{\mathcal{C}_{G,r}} = \prod_{\ell=1}^d -\underbrace{\mathcal{E}_{\ell}U_{\ell} \left(I^{\otimes(\ell-1)} \otimes \left[(-R_{\ket{\bot}}) \otimes (\ket{\bot}\bra{\bot})^{\otimes(d-\ell)} + (-I) \otimes (I - (\ket{\bot}\bra{\bot})^{\otimes(d-\ell)})\right]\right) U_{\ell}^{\dagger} \mathcal{E}_{\ell}^{\dagger}}_{=: R_\ell}.\]
        The claim about the number of calls to the $\mathcal{E}_{\ell}$'s and the $U_{\ell}$'s then follows immediately. The reflection through $\ket{\bot}$ and its control structure can both be implemented can be implemented using $\widetilde{O}(\log(K))$ auxiliary gates.

        Let $\ell \in [d]$. We observe that $\mathcal{E}_{\ell}U_{\ell}$ acts as identity on $\ket{j_1, \dots, j_{\ell-1}} \otimes \C^{[k_{\ell}] \cup \{\bot\}} \otimes \cdots \otimes \C^{[k_d] \cup \{\bot\}}$, if $(j_1, \dots, j_{\ell-1})$ is the root node of a tree decomposition. Using \cref{lem:tree-decomposition,lem:parallel-decomposition}, it remains to show that if $u = (j_1, \dots, j_{\ell-1})$ is the root node of a parallel decomposition, $R_\ell$ reflects through all the spaces $\mathcal{E}_{\ell}(\ket{j_1, \dots, j_{\ell-1}} \otimes \Span\{\ket{\psi_u}\}^{\perp} \otimes \ket{\bot}^{\otimes (d-\ell)})$. This is equivalent to showing that $U_{\ell}^{\dagger}\mathcal{E}_{\ell}^{\dagger}R_{\ell}\mathcal{E}_{\ell}U_{\ell}$ reflects through $\C^{([k_1] \cup \{\bot\})} \otimes \cdots \otimes \C^{[k_{\ell-1}] \cup \{\bot\}} \otimes \Span\{\ket{\bot}\}^{\perp} \otimes \ket{\bot}^{\otimes (d-\ell)}$, which is indeed the action of the middle operation of $R_{\ell}$.
    \end{proof}

    In specific instances it is possible to implement the operations $\mathcal{E}_\ell$ and $U_\ell$ efficiently in the circuit model. However, we remark here that is possible to give a time-efficient implementation of these operations unconditionally, in the QROM-model.

    \begin{theorem}
        \label{thm:circulation-space-reflection-implementation}
        Let $G = (V,E)$ be a graph with resistances $r : E \to \R_{>0}$, and let $T$ be a tree-parallel decomposition of $G$, with depth $d$. For every $\ell \in [d]$, let $k_{\ell}$ be the maximum number of children nodes of vertices in the $(\ell-1)$th vertex layer, and let $K = (k_1 + 1) \cdots (k_d + 1)$. Then, we can implement $R_{\mathcal{C}_{G,r}}$ in the QROM-model with $\widetilde{O}(|E|K) \subseteq \widetilde{O}(|E|^{d+1})$ bits of QROM, and $\widetilde{O}(d\log(K)) \subseteq \widetilde{O}(d^2\log|E|)$ elementary gates.
    \end{theorem}

    \begin{proof}
        It remains to implement the operations $\mathcal{E}_{\ell}$ and $U_{\ell}$ in \cref{thm:implementation-circuit-model}. To that end, observe that both are parallel quantum state-preparation operations. For each internal node, we need to store the state $\ket{\psi_u}$, and the states $\ket{f_{u,j}}$, all of which requires $\widetilde{O}(K)$ bits of QROM to store. The number of nodes in the tree for which we have a parallel decomposition is at most $|E|$, and so we obtain that the QROM-size required is $\widetilde{O}(|E|K)$.

        Finally, every state-preparation routine requires $\widetilde{O}(\log(K))$ elementary gates to be implemented, and this is also the number of gates to implement it in parallel. Thus, the total number of gates required to implement the entire reflection through $\mathcal{C}_{G,r}$ is $\widetilde{O}(d\log(K))$.
    \end{proof}

    Note that even though the above implementations can be quite efficient when it comes to the number of elementary gates, they are typically still very space-inefficient. In general, we require a QROM of size $\widetilde{O}(|E|K)$ to implement the aforementioned operations, which, as we will see in \cref{sec:relations,sec:applications}, can be exponentially large for some applications. Moreover, it also takes time to classically precompute the contents of this memory, which might also take exponential time to do. Thus, when applying these techniques to specific applications, it might still be necessary to find problem-specific improvements over the generic techniques presented in this section, and we will see several examples of that in the following sections.

    \section{Relations to other quantum algorithmic frameworks}
    \label{sec:relations}

    In this section, we elaborate on how the graph composition framework relates to other ways of designing quantum algorithms that exist in various places in the literature.

    \subsection{$st$-connectivity and planar graphs}

    The $st$-connectivity problem in the adjacency matrix model has received quite some attention in the literature. The first quantum algorithm that solves it in an undirected graph of $n$ vertices was presented by D\"urr et al.~\cite{durr2006quantum}, who constructed an $O(n^{3/2})$-query algorithm. It was subsequently improved by Belovs and Reichardt~\cite{belovs2012span}, who constructed a span-program-based algorithm that makes $\widetilde{O}(n\sqrt{\ell})$ queries, if one is promised that if $s$ and $t$ are connected, there always exists a path between them of length at most $\ell$. Later, Jeffery and Kimmel improved the analysis of the algorithm from \cite{belovs2012span} in the special case where $G \cup \{\{s,t\}\}$ is a planar graph, relating the span program witness sizes to effective resistances~\cite{jeffery2017quantum}. Moreover, they also showed how the boolean formula evaluation problem fits in this framework. Finally, Jarret et al.~\cite{jarret2018quantum} generalized the approach taken in \cite{jeffery2017quantum} to non-planar graphs, leading to the current state-of-the-art algorithm for solving the $st$-connectivity problem in the adjacency matrix model~\cite[Corollary~18]{jarret2018quantum}.

    The graph composition framework is a strict generalization of the setting considered in the $st$-connectivity problem. In the $st$-connectivity problem, one can make direct queries whether a given edge $\{u,v\} \in V^2$ is present in the graph. In the graph composition framework, we instead allow for putting arbitrary span programs on the edges in the graph that compute whether the edge is present. Indeed, the main result from \cite{jarret2018quantum} for a graph $G = (V,E)$ can be recovered from \cref{thm:graph-composition} by setting all the span programs $(\mathcal{P}_e)_{e \in E}$ to scalar multiples of trivial span programs that evaluate the $e$th bit of a bitstring $x \in \{0,1\}^E$.

    We formalize the definition of an $st$-connectivity graph here.

    \begin{definition}
        Let $G = (V,E)$ be an undirected multigraph with resistances $r : E \to \R_{>0}$, and $s,t \in V$ with $s \neq t$. Let $\D \subseteq \{0,1\}^n$ and for all $e \in E$, let $j(e) \in [n]$ and $b(e) \in \{0,1\}$. We refer to $\mathcal{G} = (G,j,b,r)$ as an $st$-connectivity graph on $\D$, and we say that it computes the function $f : \D \to \{0,1\}$, where $f(x) = 1$ if and only if $s$ and $t$ are connected along the graph $G(x) = (V,E(x))$, where $E(x) = \{e \in E : x_{j(e)} = b(e)\}$. We let $w_+(x,\mathcal{G}) = R_{G(x),s,t,r}$, and $w_-(x,\mathcal{G}) = R_{G,s,t,r'}^{-1}$, where $r'(e) = r(e)^{-1}$ if $x_{j(e)} \neq b(e)$, and $0$ otherwise. We say that the complexity of $\mathcal{G}$ is
        \[C(\mathcal{G}) = \sqrt{\max_{x \in f^{-1}(1)} w_+(x,\mathcal{G}) \cdot \max_{x \in f^{-1}(0)} w_-(x,\mathcal{G})}.\]
        Finally, for any boolean function $f : \D \to \{0,1\}$ with $\D \subseteq \{0,1\}^n$, we write $\st(f)$ for the minimal complexity $C(\mathcal{G})$ of an $st$-connectivity graph $\mathcal{G}$ that computes $f$.
    \end{definition}

    \begin{theorem}
        \label{thm:st-connectivity}
        Let $n \in \mathbb{N}$ and $\D \subseteq \{0,1\}^n$. Every $st$-connectivity graph $\mathcal{G} = (G,j,e,r)$ on $\D$ can be turned into a graph composition $\mathcal{P}$ on $\D$, such that $C(\mathcal{P}) = C(\mathcal{G})$.
    \end{theorem}

    \begin{proof}
        Let $G = (V,E)$. For all $j \in [n]$, let $\mathcal{P}_j$ on $\D$ be a trivial span program that computes $j$th bit. For all the edges $e \in E$, let $\mathcal{P}_e = r_e\mathcal{P}_{j(e)}$ if $b(e) = 1$, and $\mathcal{P}_e = r_e(\lnot\mathcal{P}_{j(e)})$ if $b(e) = 0$. Now, we take $\mathcal{P}$ to be the graph composition of $(\mathcal{P}_e)_{e \in E}$ on $G$. The analyses of the witness sizes then follows directly from \cref{thm:graph-composition}.
    \end{proof}

    It turns out that in the case where $G \cup \{\{s,t\}\}$ is a planar graph, the span program negation of the graph composition of $G$ is related to a span program composition of the planar dual graph $G^{\dagger}$. This was observed in the unit-cost setting in \cite{jeffery2017quantum}, and here we extend this observation to our generalized setting. The core result that makes the special case of planar graphs interesting to us is the following characterization of the circulation space of dual graphs.

    \begin{lemma}
        \label{lem:planar-dual-circulation-space}
        Let $G = (V,E)$ be a connected, undirected, planar graph, where every edge $e \in E$ has an implicit direction meaning that it goes from $e_-$ to $e_+$. Let $G^{\dagger} = (F^{\dagger},E^{\dagger})$ be a planar dual of $G$, where every edge $e$ is associated to a dual edge $e^{\dagger} \in E^{\dagger}$, that points from the face on the left of $e$ to the face on the right of $e$, as seen from the perspective of traversing $e$ in its implicit direction. Moreover, let $r : E \to [0,\infty]$ be resistances on $G$, and let $r^{\dagger} : E^{\dagger} \to [0,\infty]$ be defined by $r^{\dagger}_{e^{\dagger}} = 1/r_e$. Then, by identifying $\ket{e^{\dagger}} = \ket{e}$, and as such identifying $\H_{G^{\dagger}} = \H_G$, we find that
        \[\H_G = \mathcal{C}_{G,r} \oplus \mathcal{C}_{G^{\dagger},r^{\dagger}} = \H_{G^{\dagger}}.\]
    \end{lemma}

    \begin{proof}
        Let $\ket{f} \in \mathcal{C}_{G^{\dagger},r^{\dagger}}$. Let $f^{\dagger} \in F^{\dagger}$ arbitrarily, and let $f'$ be the unit flow in $G$ around $f^{\dagger}$ in the counter-clockwise direction. Let $e_1, \dots, e_k$ and $e_1', \dots, e_{k'}'$ be the edges it traverses in the right and wrong direction, respectively. Note that $N_+(f^{\dagger}) = \{e_1^{\dagger}, \dots, e_k^{\dagger}\}$, and $N_-(f^{\dagger}) = \{(e_1')^{\dagger}, \dots (e_{k'}')^{\dagger}\}$. Thus, we observe that
        \[\braket{f'}{f} = \sum_{j=1}^k \sqrt{r_{e_j} \cdot r_{e_j^{\dagger}}^{\dagger}}f_{e_j^{\dagger}} - \sum_{j=1}^{k'} \sqrt{r_{e_j'} \cdot r_{(e_j')^{\dagger}}^{\dagger}}f_{(e_j')^{\dagger}} = \sum_{e \in N_+(f^{\dagger})} f_{e^{\dagger}} - \sum_{e \in N_-(f^{\dagger})} f_{e^{\dagger}} = 0,\]
        Next, observe that such cycle flows $f'$ span the circulation space of $G$, we obtain $\ket{f} \in \mathcal{C}_{G,r}^{\perp}$. We thus find $\mathcal{C}_{G^{\dagger},r^{\dagger}} \subseteq \mathcal{C}_{G,r}^{\perp}$, and by symmetry $\mathcal{C}_{G,r} \subseteq \mathcal{C}_{G^{\dagger},r^{\dagger}}^{\perp}$. Finally, observe that there are $|F^{\dagger}|-1$ linearly independent cycle flows in $G$, and similarly $|V|-1$ linearly independent cycle flows in $G^{\dagger}$, and so we find using Euler's formula that
        \[\dim(\mathcal{C}_{G,r}) + \dim(\mathcal{C}_{G^{\dagger},r^{\dagger}}) = |F^{\dagger}|-1 + |V|-1 = |E| = \dim(\H_G).\qedhere\]
    \end{proof}

    This result gives a nice relation between dual-graph-composed span programs and their negation. We note that this result elegantly recovers~\cite[Lemma~11]{jeffery2017quantum}.

    \begin{theorem}
        \label{thm:dual-graph-composition}
        Let $G = (V,E)$ be a connected, undirected graph with $s,t \in V$ and $s \neq t$, such that $G \cup \{(s,t)\}$ is planar. Let $G^{\dagger} = (F^{\dagger},E^{\dagger})$ be a planar dual of $G \cup \{(s,t)\}$ with the dual edge of $(s,t)$, connecting $s^{\dagger}$ and $t^{\dagger}$, removed. For all $e \in E$ we denote its dual edge by $e^{\dagger}$, we let $\mathcal{P}$ be the span program formed by taking the graph composition of $G$ with the span programs $(\mathcal{P}_e)_{e \in E}$, and we let $\mathcal{P}^{\dagger}$ be the graph composition of $G^{\dagger}$ with span programs $(\lnot\mathcal{P}_e)_{e^{\dagger} \in E^{\dagger}}$. Then, $\lnot\mathcal{P} = \mathcal{P}^{\dagger}$.
    \end{theorem}

    \begin{proof}
        Let $\ket{st}$ be the vector with weight $1$ on the edge between $s$ and $t$, and let the default direction of this edge be from $s$ to $t$. We define $r : E \to [0,\infty]$ as $r_e = \norm{\ket{w_0^e}}^2$, and $r_{st} = 1$. Now, we observe that
        \[\ket{f^{\min}_{G,s,t,r}} \oplus -\ket{st} \in \mathcal{C}_{G \cup \{(s,t)\}, r}, \qquad \text{and} \qquad \mathcal{C}_{G \cup \{(s,t)\},r} = \mathcal{C}_{G,r} \oplus \Span\{\ket{f^{\min}_{G,s,t,r}} \oplus -\ket{st}\},\]
        where we used that $\ket{f^{\min}_{G,s,t,r}} \in \mathcal{C}_{G,r}^{\perp}$. By symmetry, we find that
        \[\mathcal{C}_{G^{\dagger} \cup \{(s^{\dagger},t^{\dagger})\}, r^{\dagger}} = \mathcal{C}_{G^{\dagger},r^{\dagger}} \oplus \Span\{\ket{f^{\min}_{G^{\dagger},s^{\dagger},t^{\dagger},r^{\dagger}}} \oplus -\ket{s^{\dagger}t^{\dagger}}\},\]
        and recall by \cref{lem:planar-dual-circulation-space} that
        \[\mathcal{C}_{G \cup \{(s,t)\},r} \oplus \mathcal{C}_{G^{\dagger} \cup \{(s^{\dagger},t^{\dagger})\}, r^{\dagger}} = \H_G \oplus \Span\{\ket{st}\},\]
        and since $\ket{st}$ and $\ket{s^{\dagger}t^{\dagger}}$ are directed oppositely, we find $\ket{f^{\min}_{G,s,t,r}} = \ket{f^{\min}_{G^{\dagger},s^{\dagger},t^{\dagger},r^{\dagger}}}/\norm{\ket{f^{\min}_{G^{\dagger},s^{\dagger},t^{\dagger},r^{\dagger}}}}^2$.

        Now, we verify that $\lnot\mathcal{P} = \mathcal{P}^{\dagger}$. To that end, note that the embedding $\mathcal{E}$ is the same for both graphs, and so we have
        \[\ket{w_0'} = \frac{\ket{w_0}}{\norm{\ket{w_0}}^2} = \frac{\mathcal{E}(\ket{f^{\min}_{G,s,t,r}})}{\norm{\ket{f^{\min}_{G,s,t,r}}}^2} = \mathcal{E}\left(\ket{f^{\min}_{G^{\dagger},s^{\dagger},t^{\dagger},r^{\dagger}}}\right) = \ket{w_0^{\dagger}},\]
        and we observe from the definition that for all $x \in \D$, we have
        \[\H(x)^{\perp} = \left[\bigoplus_{e \in E} \H^e(x)\right]^{\perp} = \bigoplus_{e \in E} \H^e(x)^{\perp} = \H^{\dagger}(x).\]
        Thus, it remains to prove that $(\K \oplus \Span\{\ket{w_0}\})^{\perp} = \K^{\dagger}$. To that end, observe that
        \begin{align*}
            (\K \oplus \Span\{\ket{w_0}\})^{\perp} &= \left[\bigoplus_{e \in E} \K_e \oplus \mathcal{E}(\mathcal{C}_{G,r}) \oplus \Span\{\mathcal{E}(\ket{f^{\min}_{G,s,t,r}})\}\right]^{\perp} \\
            &= \bigoplus_{e \in E} (\K_e \oplus \Span\{\ket{w_0^e}\})^{\perp} \oplus \mathcal{E}((\mathcal{C}_{G,r} \oplus \Span\{\ket{f^{\min}_{G,s,t,r}}\})^{\perp}) \\
            &= \bigoplus_{e \in E} (\K_e \oplus \Span\{\ket{w_0^e}\})^{\perp} \oplus \mathcal{E}(\mathcal{C}_{G^{\dagger},r^{\dagger}}) = \K^{\dagger}.\qedhere
        \end{align*}
    \end{proof}

    \subsection{Variable-time search, formula evaluation and divide and conquer}
    \label{subsec:var-time-search-formula-evaluation-divide-conquer}

    We continue by making the fundamental observation that we can encode logic in the structure of the graph that we use to compose span programs. Indeed, if we want to compute the AND or OR of several span programs, there is an easy way to do this using the graph composition framework. We briefly introduce these constructions here, analogously to earlier works, e.g., \cite{reichardt2012span,reichardt2009span,jeffery2017quantum}, \cite[Section~5.1]{cornelissen2020span} and \cite[Section~3.3]{jeffery2024multidimensional}.

    \begin{definition}[AND- and OR-composition]
        \label{def:logical-compositions}
        Let $n \in \N$, and $\mathcal{P}_1, \dots, \mathcal{P}_n$ be span programs on $\D$. We define two special types of graph compositions:
        \begin{enumerate}[nosep]
            \item Let $G$ be a line graph with $n$ edges, and let $s$ and $t$ be the endpoints. We let $\mathcal{P}$ be the graph composition of $G$ with span programs $\mathcal{P}_1, \dots, \mathcal{P}_n$ on the edges, and we write $\mathcal{P} = \bigwedge_{j=1}^n \mathcal{P}_j$. We refer to this as the AND-composition of $\mathcal{P}_1, \dots, \mathcal{P}_n$.
            \item Let $G$ be a graph with $2$ nodes, $s$ and $t$, and $n$ parallel edges between them. We let $\mathcal{P}$ be the graph composition with span programs $\mathcal{P}_1, \dots, \mathcal{P}_n$ on the edges, and we write $\mathcal{P} = \bigvee_{j=1}^n \mathcal{P}_j$. We refer to this construction as the OR-composition of $\mathcal{P}_1, \dots, \mathcal{P}_n$.
        \end{enumerate}
    \end{definition}

    The pictorial interpretations of these constructions are provided in \cref{fig:and-or-compositions}, and we compute the witness sizes in \cref{thm:and-or-witness-sizes}.

