        It now remains to compute the witness sizes of this construction. To that end, suppose that $x \in \D$ is a positive input for the learning graph $L$. Let $p_x : E \to \R_{\geq 0}$ be the corresponding flow. We show how this flow naturally extends to a flow in the graph composition. To that end, let $(u,v) = e \in E$. We define $e_x = \{(u,z),(v,z')\}$, where $z$ and $z'$ are the partial assignments with support on $S(u)$ and $S(v)$ that agree with $x$. We let $p_x'(e_x) = p_x(e)$, and $p_x'(e') = 0$ for all other $e' \in E'$. This flow $p_x'$ is a unit $st$-flow in $G'$. We write $r_+(e') = w_+(x,\mathcal{P}_{e'})$, and upper bound the positive witness size by
        \[w_+(x,\mathcal{P}) \leq \min_{f \in F_{G',s,t}} \norm{\ket{f_{G,r^+}}}^2 \leq \sum_{e' \in E'} p_x'(e')^2w_+(x,\mathcal{P}_{e'}) = \sum_{e \in E} \frac{p_x(e)^2}{w(x,e)} = \ell_+(x,L).\]

        On the other hand, suppose that $x \in \D$ is a negative input to $L$. Now, we define a potential function $U_x : V' \to \R$ on $G'$, with $U_x((v,z)) = 1$ if $z$ agrees with $x$, and $0$ otherwise. We also take $U_x(t) = 0$, and we observe that $U_x(s) = 1$. Next, let $\{(u,z),(v,z')\} = e' \in E'$. We observe that $U_x((u,z)) - U_x((v,z'))$ is only non-zero if $z$ agrees with $x$ and $z'$ does not. For every edge $(u,v) = e \in E$, at most one such edge $\{(u,z),(u,z')\} \in E'$ exists. As such, we write $r^-(e') = w_-(x,\mathcal{P}_{e'})^{-1}$, and upper bound the negative witness size by
        \[w_-(x,\mathcal{P}) \leq \norm{\ket{f_{G',U_x,r^-}}}^2 = \sum_{\{(u,z),(v,z')\} = e' \in E'} \frac{(U_x((u,z)) - U_x((v,z')))^2}{r^-(e')} \leq \sum_{e \in E} w(x,e) = \ell_-(x,L).\]

        We conclude that
        \[W_+(\mathcal{P}) = \max_{x \in f^{-1}(1)} w_+(x,\mathcal{P}) \leq \mathcal{L}_+(L), \qquad \text{and} \qquad W_-(\mathcal{P}) = \max_{x \in f^{-1}(0)} w_-(x,\mathcal{P}) \leq \mathcal{L}_-(L),\]
        and so $C(\mathcal{P}) \leq \mathcal{L}(L)$.
    \end{proof}

    \subsection{The bomb-testing model, and weighted decision trees}

    Another technique to develop quantum algorithms is through the conversion of classical decision trees into quantum algorithms. The first such construction was introduced by Lin and Lin~\cite[Theorem~5.5]{lin2016upper}, in a framework that they referred to as the bomb-testing model. They constructed a quantum algorithm that evaluates a given decision tree with boolean queries using $O(\sqrt{\mathsf{GT}})$ queries, where $\mathsf{G}$ is the ``guessing complexity'' of the decision tree, and $\mathsf{T}$ is its depth. This construction was later generalized to the non-boolean case by Beigi and Taghavi~\cite[Theorem~4]{beigi2020quantum}. A time-efficient implementation was later provided in \cite{beigi2022time}. Finally, the construction in the boolean case was improved in \cite[Theorem~8]{cornelissen2022improved}.

    Here, we show that both constructions are a specific instantiation of the $st$-connectivity framework. We start by formalizing both as complexity measures.

    \begin{definition}[Decision tree + guessing algorithm complexity~{\cite[Sections~5.2 and 5.3]{lin2016upper}}]
        Let $n \in \N$, $\D \subseteq \{0,1\}^n$ and $f : \D \to \{0,1\}$. Let $T = (V,E)$ be a decision tree computing $f$, and let $G : E \to \{0,1\}$ be a guessing algorithm, such that for every internal node $v \in V$, exactly one of its children is connected with an edge $e \in E$ for which $G(e) = 1$. Then, we write $\mathsf{T}(T)$ for the depth of $T$, and the $\mathsf{G}(T)$ for the maximum number of edges $e \in E$ along a path from the root to a leaf that satisfy $G(e) = 0$. We call $\mathsf{G}(T)$ the guessing complexity of $T$. Finally, we write
        \[\sqrt{\mathsf{GT}}(f) = \min_{T \text{ computing } f} \sqrt{\mathsf{G}(T) \cdot \mathsf{T}(T)}.\]
    \end{definition}

    \begin{definition}[{Weighted-decision-tree complexity~\cite[Definition~1.5]{cornelissen2022improved}}]
        \label{def:weighted-decision-tree}
        Let $n \in \N$, $\D \subseteq \{0,1\}^n$ and $f : \D \to \{0,1\}$. Let $\T = (V,E)$ be a decision tree computing $f$, and $w : E \to \R_{\geq 0}$ a weight functions on the edges. For every input $x \in \D$, let $\mathcal{P}_x$ be the path taken on input $x$, and let $\overline{\mathcal{P}}_x$ be the set of edges that have exactly one node in common with the vertices traversed in $\mathcal{P}_x$. Then, we define
        \[\WDT_+(\T,w) = \max_{x \in f^{-1}(1)} \sum_{e \in \mathcal{P}_x} w_e, \qquad \WDT_-(\T,w) = \max_{x \in f^{-1}(0)} \sum_{e \in \overline{\mathcal{P}}_x} \frac{1}{w_e},\]
        and $\WDT(\T,w) = \sqrt{\WDT_+(\T,w) \cdot \WDT_-(\T,w)}$. Moreover, we let
        \[\WDT(\T) = \min_{w : E \to \R_{\geq0}} \WDT(\T,w), \qquad \text{and} \qquad \WDT(f) = \min_{\T \text{ computing } f} \WDT(\T).\]
    \end{definition}

    We can also phrase these complexity measures in the zero-error setting, as follows.

    \begin{definition}[Zero-error version of the complexity measures]
        \label{def:zero-error}
        Let $n \in \N$, $\D \subseteq \{0,1\}^n$, and $f : \D \to \{0,1\}$. Let $\mathcal{T} = \{T_1, \dots, T_k\}$ be a set of decision trees, where every leaf is labeled with $0$, $1$, or \texttt{?}. Let $ p= (p_1, \dots, p_k)$ be a probability distribution on $[k]$, such that for all $x \in \D$, if we sample $T_j$ with $j \sim p$, then the probability that it outputs $\lnot f(x)$ is $0$, and the probability that it outputs \texttt{?} is at most $1/2$. Then, we say that $\mathcal{T}$ computes $f$ with zero error, and we write
        \[\sqrt{\mathsf{GT}}(\mathcal{T}) = \max_{j \in [k]} \sqrt{\mathsf{G}(T_j) \cdot \mathsf{T}(T_j)}, \qquad \text{and} \qquad \sqrt{\mathsf{GT}}_0(f) = \min_{\mathcal{T} \text{ computes } f \text{ with zero error}} \sqrt{\mathsf{GT}}(\mathcal{T}).\]
        and
        \[\WDT(\mathcal{T}) = \max_{j \in [k]} \WDT(T_j), \qquad \text{and} \qquad \WDT_0(f) = \min_{\mathcal{T} \text{ computes } f \text{ with zero error}} \WDT(\mathcal{T}).\]
    \end{definition}

    It is immediate from the definitions above that $\mathsf{WDT}_0(f) \leq \mathsf{WDT}(f) \leq \sqrt{\mathsf{GT}}(f) \leq \mathsf{D}(f)$, and similarly that $\mathsf{WDT}_0(f) \leq \sqrt{\mathsf{GT}}_0(f) \leq \sqrt{\mathsf{GT}}(f)$, for all possibly partial functions $f : \D \to \{0,1\}$. We prove here that the smallest of all these measures, i.e., $\mathsf{WDT}_0(f)$, is lower bounded by the $st$-connectivity complexity of $f$. We start by showing that we can turn any weighted decision tree in an $st$-connectivity instance, in~\cref{thm:weighted-decision-trees}, and then we use the graph composition framework to compose the family of decision trees together, in~\cref{thm:st-to-WDT0}.

    \begin{theorem}
        \label{thm:weighted-decision-trees}
        Let $\T = (V,E)$ be a decision tree, making queries to an $n$-bit string, having outputs in $\{0,1,\texttt{?}\}$, and with a weight function $w : E \to \R_{>0}$ on the edges. Then, we can construct an instance of the $st$-connectivity framework that distinguishes whether the output of the tree is $1$ or an element of $\{0,\texttt{?}\}$ with complexity at most $\WDT(\T,w)$.
    \end{theorem}

    \begin{proof}
        Let $\mathcal{P}_j$ be the trivial span program that evaluates the $j$th bit of the bitstring. We construct our graph composition by modifying the decision tree as follows. First, for every non-leaf node in the decision tree, querying the $j$th bit of the bitstring, we label its outgoing legs by $w_e\mathcal{P}_j$ for the outcome-$1$ leg, and $w_e(\lnot\mathcal{P}_j)$ for the outcome-$0$ leg. Next, we label the root vertex of the decision tree by $s$, we prune all the $0$-leaves and \texttt{?}-leaves of the tree, and we contract all the $1$-leaves into a single vertex labeled by $t$. An example of this conversion is shown in \cref{fig:decision-tree-conversion}.

