        It remains to compute the witness sizes of the resulting graph composition. To that end, suppose that $x$ is a positive input. Then, there is a unique path $\mathcal{P}_x \subseteq E$ that connects $s$ and $t$, corresponding to the path followed in the decision tree, and as such the positive witness size is $w_+(x,\mathcal{P}) = \sum_{e \in \mathcal{P}_x} w_e$.

        On the other hand, suppose that $x$ is a negative input. Then, for every non-leaf vertex in the decision tree that $x$'s path traverses, we consider the set $\overline{\mathcal{P}}_x$ of legs of these vertices that the path is not taking. We now observe that $\overline{\mathcal{P}}_x$ is a cut in the graph, and thus from \cref{thm:witness-upper-bounds}, we find that $w_-(x,\mathcal{P}) \leq \sum_{e \in \overline{\mathcal{P}}_x} \frac{1}{w_e}$.

        Combining these observations yields that
        \[W_+(\mathcal{P}) = \max_{x \in f^{-1}(1)} w_+(x,\mathcal{P}) = \WDT_+(\T,w), \qquad \text{and} \qquad W_-(\mathcal{P}) = \max_{x \in f^{-1}(0)} w_-(x,\mathcal{P}) \leq \WDT_-(\T,w),\]
        and so $C(\mathcal{P}) \leq \WDT(\T,w)$.
    \end{proof}

    The above theorem immediately proves that $\st(f) \leq \WDT(f)$. However, we can do slightly better and prove that $\st(f) \leq \WDT_0(f)$. This is the objective of the following theorem.

    \begin{theorem}
        \label{thm:st-to-WDT0}
        Let $f : \D \to \{0,1\}$ with $\D \subseteq \{0,1\}^n$. We have $\st(f) \leq \sqrt{2}\WDT_0(f)$.
    \end{theorem}

    \begin{proof}
        Let $\mathcal{T} = \{T_1, \dots, T_k\}$ be a family of decision trees that computes $f$ with zero-error, and that minimizes $\WDT(\mathcal{T})$. Then, we find that $\WDT(\mathcal{T}) = \WDT_0(f)$. Next, for all $j \in [k]$, we let $\mathcal{P}_j$ be the $st$-connectivity that is constructed from $T_j$ by \cref{thm:weighted-decision-trees}. We observe that $C(\mathcal{P}_j) = \WDT(T_j) \leq \WDT_0(f)$. Without loss of generality, we assume that $W_-(\mathcal{P}_j) = C(\mathcal{P}_j)$ and $W_+(\mathcal{P}_k) = C(\mathcal{P}_j)$, since we can always rescale the resistances accordingly.

        Next, we consider a parallel graph composition $\mathcal{P}$ with span programs $(\mathcal{P}_j/p_j)_{j=1}^k$ on the edges. See also \cref{fig:st-to-WDT}. We compute the witness sizes of the resulting instance of the $st$-connectivity framework.

        \begin{figure}[!ht]
            \centering\scriptsize
            \begin{tikzpicture}[vertex/.style = {draw, rounded corners = .3em}, scale = 2]
                \node[vertex] (s) at (0,0) {$s$};
                \node[left] at (s.west) {$\mathcal{P} = \;\;$};
                \node[vertex] (t) at (1,0) {$t$};
                \draw (s) to[bend left=80] node[above] {$\mathcal{P}_1/p_1$} (t);
                \draw (s) to[bend left=30] node[above] {$\mathcal{P}_2/p_2$} (t);
                \node at (.5,.05) {$\vdots$};
                \draw (s) to[bend right=80] node[above] {$\mathcal{P}_k/p_k$} (t);
            \end{tikzpicture}
            \caption{The reduction from any zero-error randomized algorithm to an $st$-connectivity instance.}
            \label{fig:st-to-WDT}
        \end{figure}

        To that end, let $x \in \{0,1\}^n$ be a positive instance, and let $J(x) \subseteq [k]$ be the subset of indices such that $j \in J(x)$ if and only if $T_j$ accepts $x$. Since this happens with probability at least $1/2$, we have $\sum_{j \in J(x)} p_j \geq 1/2$. Thus, we find that
        \[w_+(x,\mathcal{P}) = \frac{1}{\sum_{j \in J(x)} \frac{p_j}{w_+(x,\mathcal{P}_j)}} \leq \max_{j \in J(x)} C(\mathcal{P}_j) \cdot \left[\sum_{j \in J(x)} p_j\right]^{-1} \leq 2\WDT_0(f).\]

        On the other hand, let $x \in \{0,1\}^n$ be a negative instance. Then, all trees in $\mathcal{T}$ do not accept $x$, and so we obtain that
        \[w_-(x,\mathcal{P}) = \sum_{j=1}^k w_-\left(x,\frac{\mathcal{P}_j}{p_j}\right) = \sum_{j=1}^k p_jw_-(x,\mathcal{P}_j) \leq \WDT_0(f) \cdot \sum_{j=1}^k p_j = \WDT_0(f).\]

        We conclude that $\st(f) \leq C(\mathcal{P}) \leq \sqrt{2} \cdot \WDT_0(f)$.
    \end{proof}

    \subsection{Phase estimation algorithms and multidimensional quantum walks}

    We relate the graph composition framework to the framework of multidimensional walks. The latter framework was introduced in \cite{jeffery2025multidimensional}, and further formalized in \cite{jeffery2024multidimensional}.

    First, Jeffery and Zur define the notion of a phase estimation algorithm in~\cite[Definition~3.1]{jeffery2025multidimensional}. It was shown by Reichardt~\cite{reichardt2009span} that span programs can always be evaluated using the phase estimation algorithm. We reprove that result in the span program notation used here, and the phase estimation algorithm notation used in \cite{jeffery2025multidimensional}.

    \begin{theorem}
        \label{thm:phase-estimation-algo}
        Every span program, evaluated on an input $x$, is also a phase estimation algorithm, and the span program's positive and negative witnesses are negative and positive witnesses of the phase estimation program, respectively.
    \end{theorem}

    \begin{proof}
        Let $\mathcal{P} = (\H, x \mapsto \H(x), \K, \ket{w_0})$ be a span program. Fix $x \in \D$, and let $\Psi_A$ and $\Psi_B$ be bases for $\H(x)$ and $\K$, respectively. Then, $(\H, \Psi_A, \Psi_B, \ket{w_0})$ defines a phase estimation algorithm according to \cite[Definition~3.1]{jeffery2025multidimensional}. It remains to check the witness sizes.

        To that end, according to \cref{def:span-program}, a negative witness for $x$ is a vector in $\K^{\perp} \cap \H(x)^{\perp} = (\Span(\Psi_A) + \Span(\Psi_B))^{\perp}$, which fits in the definition of a positive witness in \cite[Definition~3.5]{jeffery2025multidimensional}. On the other hand, according to \cref{def:span-program}, a positive witness for $x$ is a vector in $\ket{w_x} \in \H(x)$, such that $\ket{k} := \ket{w_x} - \ket{w_0} \in \K$. This is equivalent of finding a pair of vectors in $\Span(\Psi_A)$ and $\Span(\Psi_B)$, such that $\ket{w_0}$ is the sum of the two, which fits the definition of a negative witness in \cite[Definition~3.2]{jeffery2025multidimensional}.
    \end{proof}

    Jeffery and Zur then go on to evaluate the welded-trees problem and the $k$-distinctness problem using phase estimation algorithms. The algorithm for welded trees inherently relies on the alternative-neighborhood technique presented in \cite[Section~3.2.2]{jeffery2025multidimensional}, which seems not to be available in the graph composition framework. For the $k$-distinctness problem, we leave recovering a time-efficient algorithm using the graph composition framework for future work.

    Recently, Jeffery and Pass defined a formal version of the multidimensional quantum walk, referred to as a subspace graph, in~\cite[Definition~3.1]{jeffery2024multidimensional}. We show that every graph composition is also a subspace graph.

    \begin{theorem}
        \label{thm:subspace-graph}
        Every graph composition can be turned into a subspace graph with at most the same witness sizes.
    \end{theorem}

    \begin{proof}
        We embed span programs in subspace graphs in a similar way to the switching networks, as presented in \cite[Section~3.3]{jeffery2024multidimensional}. Let $G = (V,E)$ with $s,t \in V$ connected in $G$, and $s \neq t$, and let $\mathcal{P}$ be the graph composition of $G$ with span programs $(\mathcal{P}_e)_{e \in E}$ on $\D$. For all $e \in E$, we write $\lnot\mathcal{P}_e =: \mathcal{P}_e' = (\H_e', x \mapsto \H_e'(x), \K_e', \ket{(w_0^e)'})$, and we define
        \[\Xi_e = (\H_e' \cap \Span\{\ket{(w_0^e)'}\}^{\perp}) \oplus \Span\{\ket{(w_0^e)',\rightarrow},\ket{(w_0^e)',\leftarrow}\},\]
        and we define the isometric embedding $\mathcal{Z}_e : \H_e' \mapsto \Xi_e$ that acts as identity on $\H_e' \cap \Span\{\ket{(w_0^e)'}\}$, and as $\mathcal{Z}_e : \ket{(w_0^e)'} \mapsto (\ket{(w_0^e)',\rightarrow} - \ket{(w_0^e)',\leftarrow})/\sqrt{2}$. Inspired by \cite[Definition~3.5]{jeffery2024multidimensional}, we define
        \[\Xi_e^{\mathcal{A}} = \mathcal{Z}_e(\H_e'(x)), \qquad \text{and} \qquad \Xi_e^{\mathcal{B}} = \K_e' \oplus \Span\{\ket{(w_0^e)',\rightarrow} + \ket{(w_0^e)',\leftarrow}\}.\]
        Next, we take $B = \{s,t\}$, and we define
        \begin{align*}
            \Xi_s &= \Span\{\ket{s},\ket{s,\leftarrow}\}, \qquad \Xi_s^{\mathcal{A}} = \Span\{\ket{s} + \ket{s,\leftarrow}\}, \qquad \text{and} \qquad \Xi_s^{\mathcal{B}} = \{0\}, \\
            \Xi_t &= \Span\{\ket{t},\ket{t,\rightarrow}\}, \qquad \Xi_t^{\mathcal{A}} = \Span\{\ket{t} + \ket{t,\rightarrow}\}, \qquad \text{and} \qquad \Xi_t^{\mathcal{B}} = \{0\},
        \end{align*}
        and $\mathcal{V}_B = \Span\{\ket{s,\leftarrow} + \ket{t,\rightarrow}\}$. Next, in accordance with \cite[Definition~3.3]{jeffery2024multidimensional}, we define for all $v \in V$,
        \[\mathcal{V}_v = \begin{cases}
            \Span\left\{\ket{\psi_*(s)} + \ket{s,\leftarrow}\right\}, & \text{if } v = s, \\
            \Span\left\{\ket{\psi_*(t)} + \ket{t,\rightarrow}\right\}, & \text{if } v = t, \\
            \Span\left\{\ket{\psi_*(v)}\right\}, & \text{otherwise},
        \end{cases} \quad \text{where} \quad \ket{\psi_*(v)} = \sum_{e \in N_+(v)} \frac{\ket{(w_0^e)',\rightarrow}}{\norm{\ket{(w_0^e)'}}^2} + \sum_{e \in N_-(v)} \frac{\ket{(w_0^e)',\leftarrow}}{\norm{\ket{(w_0^e)'}}^2}.\]
        This defines a subspace graph, and we take the initial vector $\ket{\psi_0} = (\ket{s}-\ket{t})/\sqrt{2}$. We now observe that if $x \in \D$ is a positive input for $\mathcal{P}_e'$, then we can find vectors $\ket{(w_x^e)'} \in \H_e'(x)$ and $\ket{k_e'} \in \K_e'$ such that $\ket{(w_0^e)'} = \ket{(w_x^e)'} + \ket{k_e'}$. Thus, we find that
        \[\frac{\ket{(w_0^e)',\rightarrow} - \ket{(w_0^e)',\leftarrow}}{\sqrt{2}} = \mathcal{Z}_e(\ket{(w_0^e)'}) = \underbrace{\mathcal{Z}_e(\ket{(w_x^e)'})}_{\in \mathcal{A}_G} + \underbrace{\ket{k_e'}}_{\in \mathcal{B}_G},\]
        and thus we obtain that $(\mathcal{A}_G + \mathcal{B}_G)^{\perp} \cap \Xi_e = \{0\}$. Thus, intuitively, if $x \in \D$ is positive for $\mathcal{P}_e' = \lnot\mathcal{P}_e$, i.e., if $x \in \D$ is negative for $\mathcal{P}_e$, it turns off the edge $e \in E$ and bars any flow from flowing through it. Hence, analogously as in \cite[Section~3.3]{jeffery2024multidimensional}, the subspace graph checks whether there exists an $st$-path along edges $e \in E$ for which $x$ is a positive input to $\mathcal{P}_e$, and the witness analysis follows directly from the analysis in \cite[Section~3.3]{jeffery2024multidimensional}.
    \end{proof}

    Note that the definition of all the subspaces in the above proof do not make any reference to the circulation space. However, recall that the space $\mathcal{B}_G$ is defined on \cite[Page~8]{jeffery2024multidimensional} as
    \[\mathcal{B}_G = \left[\bigoplus_{e \in E} \Xi_e^{\mathcal{B}} \oplus \bigoplus_{u \in B} \Xi_u^{\mathcal{B}}\right] + \mathcal{V}_B + \bigoplus_{v \in V} \mathcal{V}_v,\]
    and that these constituent spaces are not necessarily orthogonal to one another. Thus, reflecting through $\mathcal{B}_G$ still requires some non-trivial amount of work. In the setting considered in \cite[Section~3.3]{jeffery2024multidimensional}, it seems to be similar in hardness to reflecting through the circulation space, so the time-complexity considerations of implementing the graph composition framework, in \cref{thm:implementation-graph-composition,thm:circulation-space-reflection-implementation}, can be used to understand the time complexity of implementing subspace graphs too.

    Finally, since the graph composition framework outputs a span program, we can use \cref{thm:feasible-sln-adv-bound} to generate a feasible solution to the dual adversary bound in a black-box manner. This sets the graph composition framework apart from the multidimensional quantum walk framework. We leave it for future work to figure out whether a similar conversion technique exists that turns instances of the multidimensional quantum walk framework into feasible solutions to the dual adversary bound.

    \subsection{Other relations complexity-measure relations}

    Finally, we investigate the relationship between the frameworks considered in the previous subsections, and well-known complexity measures for total boolean functions, like deterministic, randomized, and quantum query complexity.

    The first thing to note is that the graph composition framework always admits a query-optimal quantum algorithm, since we can embed an arbitrary span program on a single edge between $s$ and $t$, and we can always generate a span program with optimal complexity by generating one from an optimal solution to the dual adversary bound. As such, it doesn't make sense to define a ``graph composition'' complexity measure, since it would simply equal quantum query complexity up to constants.

    The same argument can be made for the divide and conquer framework. Indeed, one can always embed any boolean function $f : \{0,1\}^n \to \{0,1\}$ into the top-level auxiliary function $f_n^{\lambda,\aux}$, and then provide a span program with optimal complexity as $\mathcal{P}_n^{\lambda,\aux}$. Thus, if we were to define a ``divide and conquer complexity'', it would equal the quantum query complexity up to constants as well. Similarly, from the relations displayed in \cref{fig:framework-relations}, we observe that defining a ``multidimensional quantum walk complexity'' would also coincide with quantum query complexity.

    However, for the other frameworks, i.e., $st$-connectivity, (adaptive) learning graphs and (weighted) decision trees, it does make sense to define complexity measures, as we did in the previous sections. We prove several relations between these complexity measures here that were not present in the literature before.

    \begin{theorem}
        \label{thm:weighted-decision-tree-complexity}
        Let $f : \D \to \{0,1\}$ with $\D \subseteq \{0,1\}^n$. Then $\mathsf{D}(f) \leq \mathsf{WDT}(f)^2$.
    \end{theorem}

    \begin{proof}
        Let $T$ be a decision tree that minimizes $\WDT(f)$. We present a deterministic algorithm that makes at most $\WDT(f)^2$ queries. To that end, we observe from \cite[Theorem~5.4]{cornelissen2022improved} that if we have a tree $T$, where the two children of the root node have subtrees $T_L$ and $T_R$ rooted at it, then we have
        \[\WDT(T) = \frac{\WDT(T_L) + \WDT(T_R) + \sqrt{(\WDT(T_L) - \WDT(T_R))^2 + 4}}{2}.\]
        Observe that the above expression is increasing in both $\WDT(T_L)$ and $\WDT(T_R)$, since for $f(x,y) = (x+y+\sqrt{(x-y)^2+4})/2$, we have
        \[\frac{\partial f}{\partial x} = \frac12 + \frac{2(x-y)}{4\sqrt{(x-y)^2+4}} \geq \frac12\left[1 + \frac{1}{\sqrt{1 - \frac{4}{(x-y)^2}}}\right] > 0,\]
        and similarly for $y$. Now, let $P$ be the longest path in $T$ from the root to a leaf, with length $\mathrm{depth}(T)$. If for each vertex $v$ in $P$, we replace the other child with a leaf node to obtain a new tree $T'$, then we find that $\WDT(T) \geq \WDT(T')$. The resulting tree $T'$ has just one path with length $\mathrm{depth}(T)$, and leaves on all its other edges. We modify the proof of \cite[Corollary~1.7]{cornelissen2022improved}, to show that
        \[\WDT(f) = \WDT(T) \geq \WDT(T') \geq \sqrt{\mathsf{DTSize}(T')} = \sqrt{\mathrm{depth}(T)} \geq \sqrt{\mathsf{D}(f)},\]
        where the decision-tree size of $T'$ is the number of internal nodes it contains, which is $\mathrm{depth}(T)$ in this case. Finally, since $T$ computes $f$, $\mathrm{depth}(T)$ is an upper bound for $\mathsf{D}(f)$.
    \end{proof}

    \begin{corollary}
        \label{cor:R0-WDT02}
        Let $n \in \N$, $\D \subseteq \{0,1\}^n$, and $f : \D \to \{0,1\}$. Then, $\mathsf{R}_0(f) \leq \mathsf{\WDT}_0(f)^2$.
    \end{corollary}

    \begin{proof}
        Let $\mathcal{T}$ be a family of zero-error decision-trees that minimizes $\WDT_0(f)$. Draw $T \sim \mathcal{T}$, and evaluate $T$. Observe that evaluating it can be done in at most $\WDT_0(T)^2$ queries, by \cref{thm:weighted-decision-tree-complexity}. Thus, we obtain a zero-error randomized algorithm that runs in at most $\WDT_0(f)^2$ queries.
    \end{proof}

    \begin{theorem}
        \label{thm:GT-ub-WDT}
        Let $n \in \N$, $\D \subseteq \{0,1\}^n$, and $f : \D \to \{0,1\}$. Then, $\sqrt{\GT}_0(f) \leq \WDT(f)^{3/2}$ and $\sqrt{\GT}(f) \leq \WDT_0(f)^{3/2}$.
    \end{theorem}

    \begin{proof}
        Let $\mathcal{T}$ be a decision tree computing $f$, with guessing complexity $G$ and depth $T$. Analogous to \cref{thm:weighted-decision-tree-complexity}, we can prune the tree to either a complete binary tree with depth $G$, or a single-path tree of length $T$, and so $\WDT(\mathcal{T}) \geq G$, and $\WDT(\mathcal{T}) \in \Omega(\sqrt{T})$. Thus, we obtain that
        \[\WDT(T) = \WDT(\mathcal{T})^{1/3} \cdot \WDT(\mathcal{T})^{2/3} \in \Omega(G^{1/3} \cdot \sqrt{T}^{2/3}) = \Omega(\sqrt{GT}^{2/3}),\]
        and since this holds for every decision tree $\mathcal{T}$, the relation also holds for the complexity measures $\WDT$ (resp.\ $\WDT_0$) and $\sqrt{\GT}$ (resp.\ $\sqrt{\GT_0}$).
    \end{proof}

    We also provide a separation that matches the above bound.

    \begin{theorem}
        \label{thm:GT-sep-WDT}
        Let $n \in \N$ and $f : \{0,1\}^{2n+1} \to \{0,1\}$ be defined as
        \[f(x) = \begin{cases}
            x_2 \oplus x_3 \oplus \cdots \oplus x_{n+1}, & \text{if } x_1 = 1, \\
            x_2 \lor x_3 \lor \cdots \lor x_{n^2+1}, & \text{if } x_1 = 0.
        \end{cases}.\]
        Then, $\WDT(f) \in O(n)$ and $\sqrt{\GT}_0(f) \in \Omega(n^{3/2})$.
    \end{theorem}

    \begin{proof}
        For the upper bound on $\WDT$, we take a decision tree that first queries $x_1$, and depending on the outcome either uses a full binary tree to evaluate the parity function on $n$ bits, or a single-path tree to evaluate the or function on $n^2$ bits. Both have a weighted-decision-tree complexity $O(n)$, and so the total weighted-decision-tree complexity of $f$ is also upper bound by $O(n)$.

        For the lower bound on $\sqrt{\GT}_0$, observe that we can obtain the or-function and the parity-function from restrictions of $f$. Thus, in any family of decision trees evaluating $f$ with zero error, there must be a decision tree $T$ that evaluates to $1$ on input $0(1)^{n^2}$. This decision tree generates a cover of the $(n^2+1)$-dimensional hypercube, where the subcube containing $0(1)^{n^2}$ must be monochromatic. This means that it can only contain $0(1)^{n^2}$, and thus its codimension must be $n^2$. That means the depth of the decision tree must be at least $n^2$, and so $\mathsf{T}_0(f) \geq n^2$, and hence it remains to prove that $\mathsf{G}_0(f) \in \Omega(n)$.

        On the other hand, any family of decision trees evaluating $f$ with zero-error must contain a decision tree that evaluates at least half of the inputs $1x0^n$ with $x \in \{0,1\}^n$ correctly, by the pigeonhole principle. If we now prune the subtrees of all the internal nodes that query outside of the parity function's inputs and that don't match with $1x0^{n(n-1)}$, the resulting pruned decision tree still evaluates $1x0^{n(n-1)}$ correctly for at least half of the $x \in \{0,1\}^n$. Thus, there must be at least $2^n/4$ $0$ or $1$-inputs that are correctly evaluated, and hence the monochromatic cover on $\{0,1\}^n$ generated by this decision tree must contain at least $2^n/4$ singletons. From this, we observe that the number of leaves at depth $n$ of the decision tree must be at least $2^n/4$, and so the decision tree size must be at least $2^n/2-1$. Thus, we find from \cite[Lemma~1]{ehrenfeucht1989learning} that the rank $G$ satisfies
        \[2^{n-1}-1 \leq 2\sum_{j=0}^{G}\binom{n}{j} - 1 \qquad \Leftrightarrow \qquad 2^{n-2} \leq \sum_{j=0}^G \binom{n}{j} \leq 2^{nH(G/n)},\]
        where $H(x) = -x\log(x) - (1-x)\log(1-x)$ is the binary entropy function, and the final inequality is \cite[Lemma~16.19]{flum2006parameterized}. Thus, using the inequality $H(x) \leq 1 - 2(x-1/2)^2$, we find that
        \[1 - \frac2n = \frac{n-2}{n} \leq H\left(\frac{G}{n}\right) \leq 1 - 2\left(\frac{G}{n} - \frac12\right)^2,\]
        and so
        \[\left|\frac{G}{n} - \frac12\right| \leq \frac{1}{\sqrt{n}},\]
        from which we find that $G \in n/2 - O(\sqrt{n}) \subseteq \Omega(n)$.
    \end{proof}

    We present an overview of the relations between the different complexity measures in \cref{fig:compl-meas}, where $\mathsf{FS}$ denotes the formula size, i.e., the minimum number of variables required to generate a read-once formula that computes $f$. The lower bound on formula size follows from a counting argument on the number of formulas of a given size. The lower bound on the learning graph for the threshold function follows from the lower bound on the learning graph complexity for the $k$-subset certificate structure, as discussed in \cite[Proposition~11]{belovs2014power}. The relations between the complexity measures $\mathsf{Q}$, $\mathsf{Q}_0$, $\mathsf{Q}_E$, $\mathsf{R}$, $\mathsf{R}_0$ and $\mathsf{D}$ follow from known results, see e.g.~\cite[Table~1]{aaronson2021degree} for an excellent overview, and the proper references.

    It is unknown whether $\st$ and $\mathsf{Q}$ can be separated. They are equal for all the ``usual suspects'', i.e., for the or, majority, parity, tribes, and indexing functions. Another interesting open question is whether $\mathsf{D}$ is upper bounded by $\st^2$. We leave both questions for future research.

    \section{Applications}
    \label{sec:applications}

    In this section, we emphasize the new results that can be obtained using the graph composition framework.

    \subsection{Threshold and exact-weight function}

    We first construct an optimal solution to the dual adversary bound for the threshold function, using the graph composition framework. This recovers the results in \cite[Proposition~A.4, Claim~A.5]{reichardt2009span} and \cite[Proposition~3.32]{belovs2014applications}.

    \begin{theorem}[Graph-composition for the threshold function]
        \label{thm:threshold}
        Let $n \in \N$, and $k \in \{1, \dots, n\}$. Let $f_n^k$ be the threshold function on $n$ bits with threshold $k$, i.e., $f_n^k(x) = 1$ if and only if $|x| \geq k$. Let $x_j$ be a trivial span program computing the $j$th bit of the input. Then, for all $\S \subseteq [n]$, we recursively define
        \[\Th_\S^{k+1} = \bigvee_{j \in \S} (x_j \land k\Th_{\S \setminus \{j\}}^k), \qquad \text{and} \qquad \Th_\S^1 = \bigvee_{j \in \S} x_j.\]
        Then, $\Th_n^k := \Th_{[n]}^k$ computes $f_n^k$, with witness sizes
        \[w_+(x,\Th_n^k) = \begin{cases}
            \frac{1}{|x|-k+1}, & \text{if } |x| \geq k, \\
            \infty, & \text{otherwise},
        \end{cases} \qquad \text{and} \qquad w_-(x,\Th_n^k) = \begin{cases}
            \infty, & \text{if } |x| \geq k, \\
            \frac{k(n-k+1)}{k-|x|}, & \text{otherwise}.
        \end{cases}\]
        Consequently, $C(\Th_n^k) = \sqrt{k(n+k-1)}$, and this is optimal.
    \end{theorem}

    \begin{proof}
        The optimality was already proven in \cite[Proposition~3.32]{belovs2014applications}, so it remains to compute the witness sizes. We use \cref{thm:and-or-witness-sizes}, and perform induction on the size of $\S$. Suppose that $x \in \{0,1\}^n$, with $|x| \geq k+1$. Then,
        \begin{align*}
            w_+(x,\Th_\S^{k+1}) &= \left[\sum_{j \in \S} w_+\left(x, x_j \land k\Th_{\S \setminus \{j\}}^k\right)^{-1}\right]^{-1} = \left[\sum_{\substack{j \in \S \\ x_j = 1}} \left(1 + kw_+\left(x, \Th_{\S \setminus \{j\}}^k\right)\right)^{-1}\right]^{-1} \\
            &= \left[\sum_{\substack{j \in \S \\ x_j = 1}} \left(1 + \frac{k}{|x|-k}\right)^{-1}\right]^{-1} = \left[|x| \cdot \frac{|x|-k}{|x|}\right]^{-1} = \frac{1}{|x|-k}.
        \end{align*}
        On the other hand, suppose that $|x| < k+1$. Then, we have
        \begin{align*}
            w_-(x,\Th_\S^{k+1}) &= \sum_{j \in \S} w_-\left(x, x_j \land k\Th_{\S \setminus \{j\}}^k\right) = \sum_{j \in \S} \left[w_-(x,x_j)^{-1} + kw_-\left(x,\Th_{\S \setminus \{j\}}^k\right)^{-1}\right]^{-1} \\
            &= \frac1k\sum_{\substack{j \in \S \\ x_j = 1}} w_-\left(x,\Th_{\S \setminus \{j\}}^k\right) + \sum_{\substack{j \in \S \\ x_j = 0}} \left[1 + kw_-\left(x, \Th_{\S \setminus \{j\}}^k\right)^{-1}\right]^{-1} \\
            &= \frac{|x|}{k} \cdot \frac{k(n-k)}{k-(|x|-1)} + \frac{n-|x|}{1 + k \cdot \frac{k-|x|}{k(n-k)}} = \frac{|x|(n-k)}{k-|x|+1} + \frac{(n-|x|)(n-k)}{n-k+k-|x|} \\
            &= (n-k)\left[\frac{|x|}{k+1-|x|} + 1\right] = \frac{(n-k)(k+1)}{k+1-|x|}.\qedhere
        \end{align*}
    \end{proof}

