\title{MAS-KCL: Knowledge Component Graph Structure Learning with Large Language Model-based Agentic Workflow}
\author{Yuan-Hao Jiang$^{\dagger}$ \and Kezong Tang$^{\dagger, *}$ \and Zi-Wei Chen$^{\dagger, *}$ \and Yuang Wei \and Tian-Yi Liu \and Jiayi Wu}
