% \noindent where  $M_{ER}^{i}$ is the output from the external reasoning expert $ER^{i}$ in the encoder layer $i$. $ER$ is implemented like a cross-attention mechanism as follows:
% \begin{equation}
%   ER(H_{\hat{T}}, H_{I}) = \text{softmax}\left(\frac{Q_{\hat{T}}K^{T}_{I}}{\sqrt{d}}\right) V_{I}  
% \end{equation}
% \noindent where $\{Q_{\hat{T}}, K^{T}_{I}, V_{I}\} = \{H_{\hat{T}}W_{Q}, H_{I}W_{K}, H_{I}W_{V}\}$. $\{W_{Q}, W_{K}, W_{V}\} \in \mathbb{R}^{d \times d_{k}}$ are query, key and value projections respectively.
% Similarly, the internal reasoning expert ($IR$) operates on the text and image embeddings without the rationale. At each LLM encoder layer $i$, it produces the output:
% \begin{equation}
%  M_{IR}^{i} = IR^{i}(H_{T}, H_{I})
% \end{equation}
% The internal reasoning expert is realized as:
% \begin{equation}
%   IR(H_{T}, H_{I}) = \text{softmax}\left(\frac{Q_{T}K^{T}_{I}}{\sqrt{d}}\right) V_{I}
% \end{equation}
% \noindent where $\{Q_{T}, K_{I}, V_{I}\} = \{H_{T}W_{Q}, H_{I}W_{K}, H_{I}W_{V}\}$.

% \textit{Since $H_{\hat{T}}$ represents the combined embeddings of the text ($T$) and rationale ($R$), we do not use it as input to the internal expert $IR$. We hypothesize that $\hat{T}$, encode richer and more complex information that benefits from deeper processing through the LLM encoder. In contrast, $T$ is more suitable for the CLIP text encoder used by the internal expert. To validate this design choice, we also experimented with a reversed configuration—feeding $T$ into the LLM encoder and $\hat{T}$ into the CLIP text encoder, but this led to inferior performance. The corresponding results are reported in Appendix A.3.}

While $IR$ suffices in cases where the text and image directly convey sarcastic cues, there are scenarios where IR alone is inadequate, and the model must rely on the $ER$, for contextual understanding. However, external reasoning can also be noisy or unreliable. To adaptively balance these signals, we introduce a gating mechanism that dynamically weighs the contributions of $IR$ and $ER$ at each encoder layer $i$. The gating is realized as a bottleneck layer that takes the concatenated embeddings of both expert outputs:
\begin{equation}
    G^{i} = \text{softmax}(W_{g2}^{i} \cdot \text{GELU}\left(W_{g1}^{i}[M_{ER}^{i}; M_{IR}^{i}] \right)) 
\end{equation}
where $W_{g1}^{i} \in \mathbb{R}^{2d_{t} \times d_{b}}$, $W_{g2}^{i} \in \mathbb{R}^{d_{b} \times 2}$, $d_{b} < d$ defines the bottleneck dimension, and  $G^{i} \in \mathbb{R}^{2}$. 

The final gated output is then computed as:
\begin{equation}
    M_{G}^{i} = G^{i}_{1} \odot M_{ER}^{i} \;+\; G^{i}_{2} \odot M_{IR}^{i}
\end{equation}
The bottleneck design allows the gate to act as an information filter to dynamically attend to either $IR$, $ER$, or a context-dependent combination of both. We utilize a residual connection to generate the final output from encoder layer $i$ which will be fed to the next encoder layer $i+1$:
\begin{equation}
H_{\hat{T}}^{i} = H_{\hat{T}}^{i-1} + M_{G}^{i} 
\end{equation}

\subsection{Model Training and Prediction}
The output $H_{\hat{T}}^{L}$ from the final encoder layer $L$ is fed to the LLM decoder, which generates the label from the label set $\{yes, no\}$. The LLM and the image and text projection layers are trained to minimize the cross-entropy loss between the ground truth label and the generated label. The CLIP visual and text encoders are only used as feature extractors and are frozen during training.
\section{Experiments and Results}

\subsection{Datasets and Experimental Settings}
We evaluate our proposed model MiDRE on MMSD2.0 \cite{qin-etal-2023-mmsd2} dataset. We also report the performance on MMSD\cite{cai-etal-2019-multi}, which is a biased dataset in Table \ref{tab:results_mmsd}.
 The dataset statistics are reported in Table \ref{tab:stats}. We use \texttt{flan-t5-large} \footnote{\url{google/flan-t5-large}} as our backbone LLM and for generating rationales, we use the LVLM \texttt{Qwen2-VL-7B-Instruct}\footnote{\url{
Qwen/Qwen2-VL-7B-Instruct}}, due to its better zero-shot performance on our task over other LVLMs as validated in Figure \ref{fig:lvlm_comp}. For image and text feature extractors, we use \texttt{clip-vit-large-patch14}\footnote{\url{openai/clip-vit-large-patch14}}.
We train our model for 20 epochs with Adam optimizer, maintaining a batch size of 12 and a learning rate of 5e-5. We pick the model with the best validation accuracy for testing. All experiments are carried out on 1xNvidia A100 80GB GPU. 

